	  test('processing state only updates the active turn status bar', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const bootstrapSource = scripts.find(script => script.label === 'bootstrap.js')?.source || '';
    const renderMessagesSource = scripts.find(script => script.label === 'render-messages.js')?.source || '';
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    assert.strictEqual(typeof context.addMessage, 'function');
    assert.strictEqual(typeof context.setProcessing, 'function');
    assert.match(bootstrapSource, /activeProcessingTurnId/);
    assert.doesNotMatch(bootstrapSource, /turnEls\.forEach\(\(_turnData, turnId\) => \{\s*updateTurnState\(turnId,/);
    assert.doesNotMatch(renderMessagesSource, /turnEls\.forEach\(\(_turnData, turnId\) => \{\s*updateTurnState\(turnId,/);

    for (let index = 0; index < 150; index++) {
      context.addMessage({
        id: 'turn-' + index,
        role: 'user',
        content: 'Message ' + index,
        timestamp: Date.now(),
      });
    }

    const messages = elements.get('messages');
    assert.ok(messages);
    const turns: any[] = [];
    const statusBars: any[] = [];
    const collectStatusBars = (node: any) => {
      if (!node) return;
      if (node.className === 'turn') turns.push(node);
      if (node.className === 'turn-status-bar') statusBars.push(node);
      for (const child of node.children || []) collectStatusBars(child);
    };
    collectStatusBars(messages);
    assert.strictEqual(turns.length, 150);
    assert.strictEqual(statusBars.length, 150);
    assert.strictEqual(turns[0].getAttribute('aria-busy'), 'false');
    assert.strictEqual(statusBars[0].getAttribute('role'), 'status');
    assert.strictEqual(statusBars[0].getAttribute('aria-live'), 'polite');
    assert.strictEqual(statusBars[0].getAttribute('aria-atomic'), 'true');
    const send = elements.get('send');
    assert.ok(send, 'expected send button');

    const displayWrites: Array<{ bar: any; value: string }> = [];
    for (const bar of statusBars) {
      let display = String(bar.style.display || '');
      Object.defineProperty(bar.style, 'display', {
        configurable: true,
        get() {
          return display;
        },
        set(value: unknown) {
          display = String(value);
          displayWrites.push({ bar, value: display });
        },
      });
    }
    let sendDisabled = !!send.disabled;
    let sendDisabledReads = 0;
    let sendDisabledWrites = 0;
    Object.defineProperty(send, 'disabled', {
      configurable: true,
      get() {
        sendDisabledReads++;
        return sendDisabled;
      },
      set(value: unknown) {
        sendDisabledWrites++;
        sendDisabled = !!value;
      },
    });

    context.setProcessing(true);
    assert.strictEqual(displayWrites.length, 1, 'expected processing start to touch only the active turn');
    assert.strictEqual(displayWrites[0].bar, statusBars[149]);
    assert.strictEqual(displayWrites[0].value, 'flex');
    assert.strictEqual(turns[149].getAttribute('aria-busy'), 'true');
    assert.strictEqual(turns[0].getAttribute('aria-busy'), 'false');

    sendDisabledReads = 0;
    sendDisabledWrites = 0;
    context.setProcessing(true);
    assert.strictEqual(displayWrites.length, 1, 'unchanged processing start should not rewrite the active turn');
    assert.strictEqual(sendDisabledReads, 0, 'unchanged processing start should skip input-state reads');
    assert.strictEqual(sendDisabledWrites, 0, 'unchanged processing start should skip input-state writes');

    context.setProcessing(false);
    assert.strictEqual(displayWrites.length, 2, 'expected processing stop to clear only the active turn');
    assert.strictEqual(displayWrites[1].bar, statusBars[149]);
    assert.strictEqual(displayWrites[1].value, 'none');
    assert.strictEqual(turns[149].getAttribute('aria-busy'), 'false');

    sendDisabledReads = 0;
    sendDisabledWrites = 0;
    context.setProcessing(false);
    assert.strictEqual(displayWrites.length, 2, 'unchanged processing stop should not rewrite the active turn');
    assert.strictEqual(sendDisabledReads, 0, 'unchanged processing stop should skip input-state reads');
    assert.strictEqual(sendDisabledWrites, 0, 'unchanged processing stop should skip input-state writes');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

