    let nextIntervalId = 0;
    const timeouts = new Map<number, { callback: () => void; delay: number; cleared: boolean }>();
    const intervals = new Map<number, { callback: () => void; delay: number; cleared: boolean }>();
    const frames = new Map<number, { callback: () => void; cleared: boolean }>();
    const clearedTimeouts: number[] = [];
    const clearedIntervals: number[] = [];
    const cancelledFrames: number[] = [];
    context.setTimeout = (callback: () => void, delay?: number) => {
      const id = ++nextTimeoutId;
      timeouts.set(id, { callback, delay: Number(delay || 0), cleared: false });
      return id;
    };
    context.clearTimeout = (id: number) => {
      const timer = timeouts.get(id);
      if (timer) timer.cleared = true;
      clearedTimeouts.push(id);
    };
    context.setInterval = (callback: () => void, delay?: number) => {
      const id = ++nextIntervalId;
      intervals.set(id, { callback, delay: Number(delay || 0), cleared: false });
      return id;
    };
	    context.clearInterval = (id: number) => {
	      const timer = intervals.get(id);
	      if (timer) timer.cleared = true;
	      clearedIntervals.push(id);
	    };
	    context.requestAnimationFrame = (callback: () => void) => {
	      const id = frames.size;
	      frames.set(id, { callback, cleared: false });
	      return id;
	    };
    context.window.requestAnimationFrame = context.requestAnimationFrame;
