  test('timed-out image reads abort and release the composer', async () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;
    const scripts = extractOrderedScriptSources(controller.webviewApi.getHtml(webview));
    const { context, elements, posted } = createMockBrowserContext();
    const timers: Array<{ callback: () => void; delay: number }> = [];
    let readerAborted = false;
    context.setTimeout = (callback: () => void, delay: number) => {
      timers.push({ callback, delay });
      return timers.length;
    };
    context.clearTimeout = () => {};
    context.FileReader = function FileReader(this: any) {
      this.result = '';
      this.readAsDataURL = () => {};
      this.abort = () => {
        readerAborted = true;
        if (typeof this.onabort === 'function') this.onabort();
      };
    };
    runScriptsInMockBrowser(scripts, context);
    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [],
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        mode: 'build',
        processing: false,
      },
    });

    const input = elements.get('input');
    const send = elements.get('send');
    const inputHint = elements.get('inputHint');
    assert.ok(input);
    assert.ok(send);
    assert.ok(inputHint);
    input.value = 'text survives a stalled image';
    input.dispatchEvent({ type: 'input' });

    const attachPromise = context.attachImageFiles(createArrayLike([{
      type: 'image/png',
      name: 'stalled.png',
      size: 1024,
    }]), { source: 'selected' });
    const readTimeout = timers.find(timer => timer.delay === 15000);
    assert.ok(readTimeout, 'expected a bounded image read timer');
    assert.strictEqual(send.disabled, true);

    readTimeout.callback();
    await attachPromise;

    assert.strictEqual(readerAborted, true);
    assert.strictEqual(input.value, 'text survives a stalled image');
    assert.strictEqual(send.disabled, false);
    assert.strictEqual(send.getAttribute('aria-label'), 'Send, send message');
    assert.strictEqual(inputHint.textContent, 'Could not read image file.');
    assert.strictEqual(elements.get('sessionSelect')?.disabled, false);
    assert.ok(!posted.some(message => message?.type === 'send'));
    assert.ok(!posted.some(message => message?.type === WEBVIEW_MESSAGE_ERROR));
  });

  test('webview recreation restores the draft and extension-owned image attachments until send acceptance', async () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;
    const scripts = extractOrderedScriptSources(controller.webviewApi.getHtml(webview));
    let sharedState: Record<string, unknown> = {};

    const first = createMockBrowserContext();
    first.context.acquireVsCodeApi = () => ({
      getState: () => sharedState,
      setState: (state: Record<string, unknown>) => {
        sharedState = state;
        return state;
      },
      postMessage: (message: unknown) => first.posted.push(message),
    });
    runScriptsInMockBrowser(scripts, first.context);
    first.context.FileReader = function FileReader(this: any) {
      this.result = '';
      this.readAsDataURL = (file: any) => {
        this.result = file.dataUrl;
        if (typeof this.onload === 'function') this.onload();
      };
    };
    first.context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [],
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        composerAttachments: [],
        mode: 'build',
        processing: false,
      },
    });

    const firstInput = first.elements.get('input');
    assert.ok(firstInput);
    firstInput.value = 'draft survives a hidden view';
    firstInput.dispatchEvent({ type: 'input' });
    first.context.persistComposerDraftStateNow();
    await first.context.attachImageFiles(createArrayLike([{
      type: 'image/png',
      name: 'diagram.png',
      size: 4,
      dataUrl: 'data:image/png;base64,AAAA',
    }]), { source: 'selected' });

    const attachmentState = first.posted
      .filter(message => message?.type === 'composerAttachmentsState')
      .at(-1);
    assert.deepStrictEqual(JSON.parse(JSON.stringify(attachmentState?.attachments)), [{
      mediaType: 'image/png',
      dataUrl: 'data:image/png;base64,AAAA',
      filename: 'diagram.png',
    }]);
    assert.strictEqual(sharedState.composerDraft, 'draft survives a hidden view');
    assert.doesNotMatch(
      JSON.stringify(sharedState),
      /data:image/,
      'large attachment bytes should stay out of frequently rewritten webview state'
    );

    first.context.window.dispatchEvent({ type: 'pagehide' });

    const second = createMockBrowserContext();
    second.context.acquireVsCodeApi = () => ({
      getState: () => sharedState,
      setState: (state: Record<string, unknown>) => {
        sharedState = state;
        return state;
      },
      postMessage: (message: unknown) => second.posted.push(message),
    });
    runScriptsInMockBrowser(scripts, second.context);

    const secondInput = second.elements.get('input');
    assert.ok(secondInput);
    assert.strictEqual(secondInput.value, 'draft survives a hidden view');
    second.context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [],
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        composerAttachments: attachmentState?.attachments,
        mode: 'build',
        processing: false,
      },
    });

    const secondAttachments = second.elements.get('inputAttachments');
    assert.ok(secondAttachments);
    assert.strictEqual(secondAttachments.children.length, 1);
    assert.strictEqual(secondAttachments.children[0]?.title, 'diagram.png · image/png');

    secondInput.dispatchEvent({
      type: 'keydown',
      key: 'Enter',
      shiftKey: false,
      preventDefault: () => {},
    });
    const sendMessage = second.posted.find(message => message?.type === 'send');
    assert.ok(sendMessage?.submissionId);
    assert.strictEqual(
      sharedState.composerDraft,
      'draft survives a hidden view',
      'posting should retain the persisted draft until the extension accepts it'
    );
    assert.strictEqual(sharedState.composerSubmissionId, sendMessage.submissionId);
    assert.ok(
      !second.posted.some(message =>
        message?.type === 'composerAttachmentsState' &&
        Array.isArray(message.attachments) &&
        message.attachments.length === 0
      ),
      'posting should not clear extension-owned attachment state before acceptance'
    );

    second.context.window.dispatchEvent({ type: 'pagehide' });
    const third = createMockBrowserContext();
    third.context.acquireVsCodeApi = () => ({
      getState: () => sharedState,
      setState: (state: Record<string, unknown>) => {
        sharedState = state;
        return state;
      },
      postMessage: (message: unknown) => third.posted.push(message),
    });
    runScriptsInMockBrowser(scripts, third.context);
    third.context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [],
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        composerAttachments: attachmentState?.attachments,
        composerSubmissionState: {
          id: sendMessage.submissionId,
          status: 'pending',
          draft: 'draft survives a hidden view',
        },
        mode: 'build',
        processing: false,
      },
    });
    const thirdInput = third.elements.get('input');
    const thirdAttachments = third.elements.get('inputAttachments');
    assert.ok(thirdInput);
    assert.ok(thirdAttachments);
    assert.strictEqual(thirdInput.value, '');
    assert.strictEqual(thirdAttachments.children.length, 0);
    assert.strictEqual(third.elements.get('send')?.disabled, true);
    assert.strictEqual(third.elements.get('sessionSelect')?.disabled, true);
    assert.strictEqual(sharedState.composerDraft, 'draft survives a hidden view');

    third.context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'sendState',
        submissionId: sendMessage.submissionId,
        status: 'accepted',
        draft: 'draft survives a hidden view',
      },
    });
    assert.strictEqual(sharedState.composerDraft, undefined, 'acceptance should delete the submitted draft');
    assert.strictEqual(sharedState.composerSubmissionId, undefined);
    assert.strictEqual(thirdAttachments.children.length, 0);
    assert.strictEqual(third.elements.get('sessionSelect')?.disabled, false);
    assert.ok(third.posted.some(message =>
      message?.type === 'composerSubmissionSettled' &&
      message.submissionId === sendMessage.submissionId
    ));
    assert.ok(!third.posted.some(message => message?.type === WEBVIEW_MESSAGE_ERROR));
  });

