  test('send failure notice avoids unrelated control sweep', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    context.acquireVsCodeApi = () => ({
      postMessage: (message: any) => {
        if (message && message.type === 'send') throw new Error('send failed');
        posted.push(message);
      },
    });
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [],
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        mode: 'build',
        processing: false,
      },
    });

    const input = elements.get('input');
    const inputHint = elements.get('inputHint');
    const newSessionBtn = elements.get('newSession');
    assert.ok(input, 'expected composer input to be created during startup');
    assert.ok(inputHint, 'expected input hint to be created during startup');
    assert.ok(newSessionBtn, 'expected new-session button to be created during startup');

    let newSessionDisabled = !!newSessionBtn.disabled;
    let newSessionDisabledReads = 0;
    let newSessionDisabledWrites = 0;
    Object.defineProperty(newSessionBtn, 'disabled', {
      configurable: true,
      get() {
        newSessionDisabledReads++;
        return newSessionDisabled;
      },
      set(value: unknown) {
        newSessionDisabledWrites++;
        newSessionDisabled = !!value;
      },
    });

    input.value = 'send should fail';
    const event: any = { type: 'keydown', key: 'Enter', shiftKey: false };
    input.dispatchEvent(event);

    assert.strictEqual(event.defaultPrevented, true);
    assert.strictEqual(input.value, 'send should fail', 'failed send should keep the draft');
    assert.strictEqual(inputHint.textContent, 'Failed to send message.');
    assert.strictEqual(newSessionDisabledReads, 0, 'failed send notice should not read unrelated session controls');
    assert.strictEqual(newSessionDisabledWrites, 0, 'failed send notice should not rewrite unrelated session controls');
    assert.ok(!posted.some(message => message && message.type === 'send'));
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

