  test('image transfer handlers scan array-like file lists without materializing arrays', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const bootstrap = scripts.find(script => script.label === 'bootstrap.js')?.source || '';
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    assert.match(bootstrap, /function getArrayLikeLength\(/);
    assert.match(bootstrap, /function collectImageFilesFromItems\(items\)/);
    assert.doesNotMatch(
      bootstrap,
      /Array\.from\((?:dataTransfer\.items|dataTransfer\.files|e\.clipboardData\.items|imageFileInput\.files|e\.dataTransfer\.files|files)\)/
    );

    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [] } });
    const inputComposer = elements.get('inputComposer');
    assert.ok(inputComposer, 'expected input composer element to be created during startup');
    let dragClassWrites = 0;
    const originalToggle = inputComposer.classList.toggle;
    const originalContains = inputComposer.classList.contains;
    let dragClassReads = 0;
    inputComposer.classList.toggle = (name: string, force?: boolean) => {
      if (name === 'drag-over') dragClassWrites++;
      return originalToggle(name, force);
    };
    inputComposer.classList.contains = (name: string) => {
      if (name === 'drag-over') dragClassReads++;
      return originalContains(name);
    };
    const isDragOver = () => originalContains('drag-over');

	    const dataTransfer = {
	      dropEffect: '',
	      items: createArrayLike([{ kind: 'file', type: 'IMAGE/PNG' }]),
	      files: createArrayLike([]),
	    };
    let prevented = false;
    let stopped = false;

    inputComposer.dispatchEvent({
      type: 'dragover',
      dataTransfer,
      preventDefault: () => { prevented = true; },
      stopPropagation: () => { stopped = true; },
    });

    assert.strictEqual(prevented, true);
    assert.strictEqual(stopped, true);
    assert.strictEqual(dataTransfer.dropEffect, 'copy');
    assert.strictEqual(isDragOver(), true);
    assert.strictEqual(dragClassWrites, 1, 'first image dragover should enable the visual drag state once');

    inputComposer.dispatchEvent({
      type: 'dragover',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(dragClassWrites, 1, 'repeated image dragover should not rewrite an unchanged visual state');

    inputComposer.dispatchEvent({
      type: 'dragenter',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(dragClassWrites, 1, 'image dragenter should not rewrite an already-active visual state');

    inputComposer.dispatchEvent({
      type: 'dragenter',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(dragClassWrites, 1, 'nested image dragenter should not rewrite an already-active visual state');

    inputComposer.dispatchEvent({
      type: 'dragleave',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(isDragOver(), true);
    assert.strictEqual(dragClassWrites, 1, 'nested image dragleave should keep the visual state active');

    inputComposer.dispatchEvent({
      type: 'dragleave',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(isDragOver(), false);
    assert.strictEqual(dragClassWrites, 2, 'final image dragleave should clear the visual state once');

    inputComposer.dispatchEvent({
      type: 'dragover',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(isDragOver(), true);
    assert.strictEqual(dragClassWrites, 3, 'image dragover should recover the visual state after a leave');

    inputComposer.dispatchEvent({
      type: 'dragleave',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(isDragOver(), false);
    assert.strictEqual(dragClassWrites, 4, 'dragleave should clear a dragover-only visual state');

    inputComposer.dispatchEvent({
      type: 'dragenter',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(isDragOver(), true);
    assert.strictEqual(dragClassWrites, 5, 'new image dragenter should enable the visual state once');

    inputComposer.dispatchEvent({
      type: 'drop',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(isDragOver(), false);
    assert.strictEqual(dragClassWrites, 6, 'drop should clear the visual drag state once');

    inputComposer.dispatchEvent({
      type: 'dragover',
      dataTransfer,
      preventDefault: () => {},
      stopPropagation: () => {},
    });
    assert.strictEqual(isDragOver(), true);
    assert.strictEqual(dragClassWrites, 7, 'image dragover should recover visual state after drop');

    let staleDropPrevented = false;
    let staleDropStopped = false;
    inputComposer.dispatchEvent({
      type: 'drop',
      dataTransfer: { dropEffect: '', items: createArrayLike([]), files: createArrayLike([]) },
      preventDefault: () => { staleDropPrevented = true; },
      stopPropagation: () => { staleDropStopped = true; },
    });
    assert.strictEqual(isDragOver(), false);
    assert.strictEqual(dragClassWrites, 8, 'non-image drop should clear stale visual drag state once');
    assert.strictEqual(dragClassReads, 0, 'image drag handlers should use cached visual state without classList.contains reads');
    assert.strictEqual(staleDropPrevented, false, 'non-image stale drop should not be claimed');
    assert.strictEqual(staleDropStopped, false, 'non-image stale drop should keep propagating');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

