  test('goal command insert preserves existing command prefixes', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });

    const input = elements.get('input');
    const goalCommandInsert = elements.get('goalCommandInsert');
    assert.ok(input, 'expected composer input to be created during startup');
    assert.ok(goalCommandInsert, 'expected goal insert button to be created during startup');

    let inputValue = '';
    let inputValueWrites = 0;
    Object.defineProperty(input, 'value', {
      configurable: true,
      get() {
        return inputValue;
      },
      set(value: unknown) {
        inputValue = String(value);
        inputValueWrites++;
      },
    });

    input.value = '  /GOAL keep existing';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    inputValueWrites = 0;
    goalCommandInsert.dispatchEvent({ type: 'click' });
    assert.strictEqual(input.value, '  /GOAL keep existing', 'existing goal command prefix should be preserved');
    assert.strictEqual(inputValueWrites, 0, 'preserving an existing goal prefix should not rewrite the textarea value');

    input.value = 'ordinary input';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    inputValueWrites = 0;
    goalCommandInsert.dispatchEvent({ type: 'click' });
    assert.strictEqual(input.value, '/goal ', 'ordinary input should be replaced with goal command starter');
    assert.strictEqual(inputValueWrites, 1, 'inserting a missing goal command should write the textarea value once');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

