	  test('quick actions expose labels and use scoped click handling', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const bootstrap = scripts.find(script => script.label === 'bootstrap.js')?.source || '';
	    const readTag = html.match(/<button\b(?=[^>]*\bclass="quick-action")(?=[^>]*\btitle="Read README")[^>]*>/i)?.[0] || '';
	    const listTag = html.match(/<button\b(?=[^>]*\bclass="quick-action")(?=[^>]*\btitle="List files")[^>]*>/i)?.[0] || '';
	    const searchTag = html.match(/<button\b(?=[^>]*\bclass="quick-action")(?=[^>]*\btitle="Search code")[^>]*>/i)?.[0] || '';
	    const quickActionMarkup = [
	      ['Read README', '📖'],
	      ['List files', '📁'],
	      ['Search code', '🔍'],
	    ];

	    assert.match(html, /id="quickActions"/);
	    assert.match(readTag, /\btitle="Read README"/);
	    assert.match(readTag, /\baria-label="Read README, quick action"/);
	    assert.doesNotMatch(readTag, /\bdata-cmd=/);
	    assert.match(listTag, /\btitle="List files"/);
	    assert.match(listTag, /\baria-label="List files, quick action"/);
	    assert.doesNotMatch(listTag, /\bdata-cmd=/);
	    assert.match(searchTag, /\btitle="Search code"/);
	    assert.match(searchTag, /\baria-label="Search code, quick action"/);
	    assert.doesNotMatch(searchTag, /\bdata-cmd=/);
	    for (const [label, icon] of quickActionMarkup) {
	      const escapedIcon = icon.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
	      assert.match(
	        html,
	        new RegExp(
	          `<button\\b[^>]*\\btitle="${label}"[^>]*\\baria-label="${label}, quick action"[^>]*><span\\b[^>]*\\baria-hidden="true"[^>]*>${escapedIcon}<\\/span><span>${label}<\\/span><\\/button>`,
	          'i'
	        )
	      );
	    }
	    assert.match(
	      html,
	      /\.quick-action\s*\{[\s\S]*?display:\s*inline-flex;[\s\S]*?align-items:\s*center;[\s\S]*?justify-content:\s*center;[\s\S]*?gap:\s*6px;[\s\S]*?min-height:\s*30px;[\s\S]*?white-space:\s*nowrap;[\s\S]*?transition:\s*background-color 0\.15s ease,[\s\S]*?color 0\.15s ease,[\s\S]*?border-color 0\.15s ease;[\s\S]*?\}/
	    );
	    assert.match(
	      html,
	      /\.quick-action:focus-visible\s*\{[\s\S]*?outline: 1px solid var\(--vscode-focusBorder\);[\s\S]*?outline-offset:\s*1px;[\s\S]*?\}/
	    );
	    assert.match(bootstrap, /const quickActions = document\.getElementById\('quickActions'\);/);
	    assert.match(bootstrap, /const quickActionCommandByButton = new WeakMap\(\);/);
	    assert.match(bootstrap, /quickActions\.addEventListener\('click'/);
	    assert.match(bootstrap, /const buttons = quickActions && quickActions\.children \? quickActions\.children : \[\];/);
	    assert.match(bootstrap, /function findQuickActionButton\(target\)/);
	    assert.doesNotMatch(bootstrap, /target\.closest\('\.quick-action'\)/);
	    assert.doesNotMatch(bootstrap, /querySelectorAll\('\.quick-action'\)/);
	    const documentClickStart = bootstrap.indexOf("document.addEventListener('click'");
	    assert.ok(documentClickStart >= 0, 'expected document click handler');
	    const documentClickEnd = bootstrap.indexOf("document.addEventListener('keydown'", documentClickStart);
	    assert.ok(documentClickEnd > documentClickStart, 'expected keydown listener after document click handler');
	    assert.doesNotMatch(bootstrap.slice(documentClickStart, documentClickEnd), /quickAction/);

	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);
	    const quickActions = elements.get('quickActions');
	    const input = elements.get('input');
	    assert.ok(quickActions, 'expected quick actions container to be created during startup');
	    assert.ok(input, 'expected composer input to be created during startup');

	    let inputValue = '';
	    let inputValueWrites = 0;
	    Object.defineProperty(input, 'value', {
	      configurable: true,
	      get() {
	        return inputValue;
	      },
	      set(value: unknown) {
	        inputValue = String(value);
	        inputValueWrites++;
	      },
	    });

	    const quickAction = createMockElement('button');
	    quickAction.className = 'quick-action';
	    quickAction.title = 'Read README';
	    const quickActionIcon = createMockElement('span');
	    quickAction.appendChild(quickActionIcon);
	    quickActions.appendChild(quickAction);
	    let quickActionSelectorCalls = 0;
	    quickActions.querySelectorAll = () => {
	      quickActionSelectorCalls++;
	      throw new Error('quick action command caching should walk direct children');
	    };
	    context.cacheQuickActionCommands();
	    quickAction.className = '';
	    const focusEvents: unknown[] = [];
	    input.focus = (options?: unknown) => {
	      context.document.activeElement = input;
	      focusEvents.push(options);
	    };
	    quickActions.dispatchEvent({ type: 'click', target: quickActionIcon });

	    assert.strictEqual(quickActionSelectorCalls, 0, 'quick action command caching should avoid selector queries');
	    assert.strictEqual(quickAction.dataset.cmd, undefined);
	    assert.strictEqual(input.value, 'Read README');
	    assert.strictEqual(inputValueWrites, 1, 'first quick action click should write the composer value once');
	    assert.strictEqual(context.document.activeElement, input);
	    inputValueWrites = 0;
	    quickActions.dispatchEvent({ type: 'click', target: quickActionIcon });
	    assert.strictEqual(input.value, 'Read README');
	    assert.strictEqual(inputValueWrites, 0, 'repeating the same quick action should not rewrite the composer value');
	    assert.strictEqual(context.document.activeElement, input);
	    assert.deepStrictEqual(
	      focusEvents.filter(event => !(event && typeof event === 'object' && (event as any).preventScroll === true)),
	      [],
	      'quick action composer focus should avoid scrolling the transcript'
	    );
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

	  test('goal command suggestion skips redundant visibility writes', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });

    const input = elements.get('input');
    const goalCommandSuggestion = elements.get('goalCommandSuggestion');
    assert.ok(input, 'expected composer input to be created during startup');
    assert.ok(goalCommandSuggestion, 'expected /goal suggestion element to be created during startup');

    goalCommandSuggestion.classList.add('hidden');
	    let hiddenClassWrites = 0;
	    let hiddenClassReads = 0;
	    const originalAdd = goalCommandSuggestion.classList.add;
	    const originalContains = goalCommandSuggestion.classList.contains;
	    const originalRemove = goalCommandSuggestion.classList.remove;
	    const originalToggle = goalCommandSuggestion.classList.toggle;
	    goalCommandSuggestion.classList.add = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalAdd(...names);
	    };
	    goalCommandSuggestion.classList.contains = (name: string) => {
	      if (name === 'hidden') hiddenClassReads++;
	      return originalContains(name);
	    };
	    goalCommandSuggestion.classList.remove = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalRemove(...names);
	    };
	    goalCommandSuggestion.classList.toggle = (name: string, force?: boolean) => {
	      if (name === 'hidden') hiddenClassWrites++;
	      return originalToggle(name, force);
	    };

    input.value = 'ordinary input';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    input.dispatchEvent({ type: 'keyup' });
    input.dispatchEvent({ type: 'click' });
    input.dispatchEvent({ type: 'focus' });
    assert.strictEqual(hiddenClassWrites, 0, 'ordinary repeated input should not rewrite an already-hidden suggestion');
    assert.strictEqual(hiddenClassReads, 0, 'ordinary repeated input should not reread hidden suggestion visibility');

    input.value = '/g';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    input.dispatchEvent({ type: 'input' });
    assert.strictEqual(hiddenClassWrites, 1, 'showing /goal suggestion should reveal once despite syncInputState also running');
    assert.strictEqual(hiddenClassReads, 0, 'showing /goal suggestion should apply cached visibility without hidden reads');

	    input.value = '  /GOAL';
	    input.selectionStart = input.value.length;
	    input.selectionEnd = input.value.length;
	    input.dispatchEvent({ type: 'keyup' });
	    assert.strictEqual(hiddenClassWrites, 1, 'case-insensitive /goal with leading whitespace should keep the suggestion visible');
	    assert.strictEqual(hiddenClassReads, 0, 'case-insensitive /goal should not reread visible suggestion state');

	    input.value = '\u00a0/GOAL';
	    input.selectionStart = input.value.length;
	    input.selectionEnd = input.value.length;
	    input.dispatchEvent({ type: 'keyup' });
	    assert.strictEqual(hiddenClassWrites, 1, 'non-ASCII leading whitespace should keep the suggestion visible');
	    assert.strictEqual(hiddenClassReads, 0, 'non-ASCII leading whitespace should not reread visible suggestion state');

    input.dispatchEvent({ type: 'keyup' });
    input.dispatchEvent({ type: 'click' });
    input.dispatchEvent({ type: 'focus' });
    assert.strictEqual(hiddenClassWrites, 1, 'unchanged visible suggestion should not rewrite on repeated composer events');
    assert.strictEqual(hiddenClassReads, 0, 'unchanged visible suggestion should not reread hidden state');

    input.value = '/goal ';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    input.dispatchEvent({ type: 'input' });
    assert.strictEqual(hiddenClassWrites, 2, 'whitespace after /goal should hide the suggestion once');
    assert.strictEqual(hiddenClassReads, 0, 'hiding /goal suggestion should apply cached visibility without hidden reads');

    input.value = '/goalx';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    input.dispatchEvent({ type: 'input' });
    assert.strictEqual(hiddenClassWrites, 2, 'non-matching /goal prefix should stay hidden without duplicate writes');
    assert.strictEqual(hiddenClassReads, 0, 'non-matching /goal prefix should not reread hidden suggestion state');

    input.value = '/go';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    input.dispatchEvent({ type: 'input' });
    assert.strictEqual(hiddenClassWrites, 3, 'returning to a valid /goal prefix should reveal once');
    assert.strictEqual(hiddenClassReads, 0, 'returning to a valid /goal prefix should reveal without hidden reads');

    input.value = 'ordinary input';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    input.dispatchEvent({ type: 'input' });
    assert.strictEqual(hiddenClassWrites, 4, 'hiding /goal suggestion should hide once');
    assert.strictEqual(hiddenClassReads, 0, 'final /goal suggestion hide should not reread hidden state');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

