	  test('inline destructive confirmations are labelled control groups', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const confirmations = [
      {
        id: 'sessionClearConfirm',
        labelId: 'sessionClearConfirmText',
      },
      {
        id: 'memoryDropConfirm',
        labelId: 'memoryDropConfirmText',
      },
      {
        id: 'autoApprovedToolsClearConfirm',
        labelId: 'autoApprovedToolsClearConfirmText',
      },
      {
        id: 'revertDiscardConfirm',
        labelId: 'revertDiscardConfirmText',
      },
    ];

    for (const { id, labelId } of confirmations) {
      const confirmTag = html.match(new RegExp(`<div\\b[^>]*\\bid="${id}"[^>]*>`, 'i'))?.[0] || '';
      const labelTag = html.match(new RegExp(`<div\\b[^>]*\\bid="${labelId}"[^>]*>`, 'i'))?.[0] || '';

      assert.ok(confirmTag, `expected ${id} container`);
      assert.match(confirmTag, /\brole="group"/);
      assert.match(confirmTag, new RegExp(`\\baria-labelledby="${labelId}"`));
      assert.doesNotMatch(confirmTag, /\baria-label=/);
      assert.doesNotMatch(confirmTag, /\baria-describedby=/);
      assert.doesNotMatch(confirmTag, /\brole="alert"/);
      assert.doesNotMatch(confirmTag, /\baria-live=/);
      assert.ok(labelTag, `expected ${labelId} visible label`);
    }

    const confirmationButtons = [
      { id: 'sessionClearCancel', label: 'Cancel clear session', text: 'Cancel' },
      { id: 'sessionClearConfirmRun', label: 'Clear current session', text: 'Clear current' },
      { id: 'memoryDropCancel', label: 'Cancel drop memories', text: 'Cancel' },
      { id: 'memoryDropConfirmRun', label: 'Drop memories and generated artifacts', text: 'Drop memories' },
      { id: 'autoApprovedToolsClearCancel', label: 'Cancel clear always allowed tools', text: 'Cancel' },
      { id: 'autoApprovedToolsClearConfirmRun', label: 'Clear always allowed tools', text: 'Clear always allowed' },
      { id: 'revertDiscardCancel', label: 'Cancel discard undone history', text: 'Cancel' },
      { id: 'revertDiscardConfirmRun', label: 'Discard undone history', text: 'Discard' },
    ];
    const confirmationTriggers = [
      {
        id: 'sessionClearCurrent',
        text: 'Clear current',
        title: 'Clear messages and runtime state for the current session',
        label: 'Clear current, clear messages and runtime state for the current session',
        controls: 'sessionClearConfirm',
      },
      {
        id: 'sessionClearSaved',
        text: 'Clear saved',
        title: 'Delete all saved sessions, todos, and input history from workspace storage',
        label: 'Clear saved, delete all saved sessions, todos, and input history from workspace storage',
        controls: 'sessionClearConfirm',
      },
      {
        id: 'autoApprovedToolsClear',
        text: 'Clear always allowed',
        title: 'Clear all saved always-allowed tool approvals',
        label: 'Clear always allowed, clear all saved always-allowed tool approvals',
        controls: 'autoApprovedToolsClearConfirm',
      },
    ];

    for (const { id, label, text } of confirmationButtons) {
      const match = html.match(new RegExp(`<button\\b[^>]*\\bid="${id}"[^>]*>([^<]*)<\\/button>`, 'i'));
      const tag = match?.[0] || '';
      assert.ok(tag, `expected ${id} button`);
      assert.match(tag, new RegExp(`\\baria-label="${label}"`));
      assert.match(tag, new RegExp(`\\btitle="${label}"`));
      assert.strictEqual(match?.[1], text);
      assert.ok(label.startsWith(text), `${id} accessible label should start with visible text`);
	    }
    for (const { id, text, title, label, controls } of confirmationTriggers) {
      const match = html.match(new RegExp(`<button\\b[^>]*\\bid="${id}"[^>]*>([^<]*)<\\/button>`, 'i'));
      const tag = match?.[0] || '';
      assert.ok(tag, `expected ${id} trigger`);
      assert.strictEqual(match?.[1], text);
      assert.ok(label.startsWith(text), `${id} accessible label should start with visible text`);
      assert.match(tag, new RegExp(`\\btitle="${title}"`));
      assert.match(tag, new RegExp(`\\baria-label="${label}"`));
      assert.match(tag, new RegExp(`\\baria-controls="${controls}"`));
      assert.match(tag, /\baria-expanded="false"/);
    }
	  });

	  test('inline destructive confirmations focus cancel first and restore trigger on user close', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    context.window.dispatchEvent({
	      type: 'message',
	      data: { type: 'init', messages: [], skills: [], autoApprovedTools: ['read'] },
	    });

	    const confirmations = [
	      {
	        name: 'memory drop',
	        setter: 'setMemoryDropConfirmPending',
	        triggerId: 'memoryDrop',
	        cancelId: 'memoryDropCancel',
	        confirmId: 'memoryDropConfirm',
	      },
	      {
	        name: 'auto-approved tools clear',
	        setter: 'setAutoApprovedToolsClearConfirmPending',
	        triggerId: 'autoApprovedToolsClear',
	        cancelId: 'autoApprovedToolsClearCancel',
	        confirmId: 'autoApprovedToolsClearConfirm',
	      },
	    ];

	    for (const confirmation of confirmations) {
	      const trigger = elements.get(confirmation.triggerId);
	      const cancel = elements.get(confirmation.cancelId);
	      const confirm = elements.get(confirmation.confirmId);
	      const setPending = (context as any)[confirmation.setter];
	      assert.ok(trigger, `expected ${confirmation.name} trigger`);
	      assert.ok(cancel, `expected ${confirmation.name} cancel`);
	      assert.ok(confirm, `expected ${confirmation.name} confirmation`);
	      assert.strictEqual(typeof setPending, 'function', `expected ${confirmation.name} helper`);

	      trigger.disabled = false;
	      cancel.disabled = false;
	      confirm.classList.add('hidden');
	      trigger.setAttribute('aria-expanded', 'false');
	      const focusEvents: Array<{ id: string; options: unknown }> = [];
	      trigger.focus = (options?: unknown) => {
	        context.document.activeElement = trigger;
	        focusEvents.push({ id: 'trigger', options });
	      };
	      cancel.focus = (options?: unknown) => {
	        context.document.activeElement = cancel;
	        focusEvents.push({ id: 'cancel', options });
	      };

	      setPending(false, { sync: false });
	      assert.strictEqual(focusEvents.length, 0, `${confirmation.name} closed state should not move focus`);

	      setPending(true, { sync: false });
	      assert.strictEqual(confirm.classList.contains('hidden'), false, `${confirmation.name} should be visible`);
	      assert.strictEqual(trigger.getAttribute('aria-expanded'), 'true', `${confirmation.name} trigger should be expanded`);
	      assert.strictEqual(context.document.activeElement, cancel, `${confirmation.name} should focus the safe cancel action`);

	      setPending(true, { sync: false });
	      assert.deepStrictEqual(focusEvents.map(event => event.id), ['cancel'], `${confirmation.name} unchanged open state should not refocus`);

	      setPending(false, { sync: false });
	      assert.strictEqual(confirm.classList.contains('hidden'), true, `${confirmation.name} should close`);
	      assert.strictEqual(trigger.getAttribute('aria-expanded'), 'false', `${confirmation.name} trigger should collapse`);
	      assert.strictEqual(context.document.activeElement, trigger, `${confirmation.name} user close should restore trigger focus`);

	      setPending(true, { sync: false });
	      assert.strictEqual(context.document.activeElement, cancel, `${confirmation.name} reopen should focus cancel again`);
	      setPending(false, { sync: false, restoreFocus: false });
	      assert.strictEqual(context.document.activeElement, cancel, `${confirmation.name} programmatic close should not steal focus`);
	      assert.deepStrictEqual(focusEvents.map(event => event.id), ['cancel', 'trigger', 'cancel']);
	      assert.deepStrictEqual(
	        focusEvents.filter(event => !(event.options && typeof event.options === 'object' && (event.options as any).preventScroll === true)),
	        [],
	        `${confirmation.name} focus should avoid scrolling the transcript`
	      );
	    }

	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

	  test('memory drop confirmation skips duplicate aria and visibility reads', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });

	    const memoryDropConfirm = elements.get('memoryDropConfirm');
	    const memoryDrop = elements.get('memoryDrop');
	    const memoryDropCancel = elements.get('memoryDropCancel');
	    assert.ok(memoryDropConfirm, 'expected memory drop confirmation');
	    assert.ok(memoryDrop, 'expected memory drop button');
	    assert.ok(memoryDropCancel, 'expected memory drop cancel button');
	    memoryDropConfirm.classList.add('hidden');
	    memoryDrop.setAttribute('aria-expanded', 'false');
	    memoryDrop.disabled = false;
	    memoryDropCancel.disabled = false;
	    const focusEvents: Array<{ id: string; options: unknown }> = [];
	    memoryDrop.focus = (options?: unknown) => {
	      context.document.activeElement = memoryDrop;
	      focusEvents.push({ id: 'drop', options });
	    };
	    memoryDropCancel.focus = (options?: unknown) => {
	      context.document.activeElement = memoryDropCancel;
	      focusEvents.push({ id: 'cancel', options });
	    };

	    let hiddenClassReads = 0;
	    let hiddenClassWrites = 0;
	    const originalConfirmAdd = memoryDropConfirm.classList.add;
	    const originalConfirmContains = memoryDropConfirm.classList.contains;
	    const originalConfirmRemove = memoryDropConfirm.classList.remove;
	    const originalConfirmToggle = memoryDropConfirm.classList.toggle;
	    memoryDropConfirm.classList.contains = (name: string) => {
	      if (name === 'hidden') hiddenClassReads++;
	      return originalConfirmContains(name);
	    };
	    memoryDropConfirm.classList.add = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalConfirmAdd(...names);
	    };
	    memoryDropConfirm.classList.remove = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalConfirmRemove(...names);
	    };
	    memoryDropConfirm.classList.toggle = (name: string, force?: boolean) => {
	      if (name === 'hidden') hiddenClassWrites++;
	      return originalConfirmToggle(name, force);
	    };

	    let ariaExpandedReads = 0;
	    let ariaExpandedWrites = 0;
	    const originalGetAttribute = memoryDrop.getAttribute;
	    const originalSetAttribute = memoryDrop.setAttribute;
	    memoryDrop.getAttribute = function getAttribute(name: string) {
	      if (name === 'aria-expanded') ariaExpandedReads++;
	      return originalGetAttribute.call(this, name);
	    };
	    memoryDrop.setAttribute = function setAttribute(name: string, value: unknown) {
	      if (name === 'aria-expanded') ariaExpandedWrites++;
	      return originalSetAttribute.call(this, name, value);
	    };
	    const totalReads = () => hiddenClassReads + ariaExpandedReads;
	    const totalWrites = () => hiddenClassWrites + ariaExpandedWrites;

	    assert.strictEqual(typeof context.setMemoryDropConfirmPending, 'function');
	    context.setMemoryDropConfirmPending(false, { sync: false });
	    assert.strictEqual(totalWrites(), 0, 'initial closed confirmation sync should not rewrite matching state');
	    assert.strictEqual(hiddenClassReads, 0, 'initial closed confirmation sync should not read confirmation visibility');
	    const afterInitialSyncReads = totalReads();

	    context.setMemoryDropConfirmPending(false, { sync: false });
	    assert.strictEqual(totalReads(), afterInitialSyncReads, 'unchanged closed confirmation should not re-read DOM state');
	    assert.strictEqual(totalWrites(), 0, 'unchanged closed confirmation should not rewrite state');

	    context.setMemoryDropConfirmPending(true, { sync: false });
	    assert.strictEqual(hiddenClassWrites, 1, 'opening confirmation should reveal once');
	    assert.strictEqual(hiddenClassReads, 0, 'opening confirmation should use cached visibility without reading the hidden class');
	    assert.strictEqual(ariaExpandedWrites, 1, 'opening confirmation should expand the drop button once');
	    assert.strictEqual(context.document.activeElement, memoryDropCancel, 'opening confirmation should focus the safe cancel action');
	    const afterOpenReads = totalReads();
	    const afterOpenWrites = totalWrites();

	    context.setMemoryDropConfirmPending(true, { sync: false });
	    assert.strictEqual(totalReads(), afterOpenReads, 'unchanged open confirmation should not re-read DOM state');
	    assert.strictEqual(totalWrites(), afterOpenWrites, 'unchanged open confirmation should not rewrite state');
	    assert.deepStrictEqual(focusEvents.map(event => event.id), ['cancel'], 'unchanged open confirmation should not refocus');

	    context.setMemoryDropConfirmPending(false, { sync: false });
	    assert.strictEqual(hiddenClassWrites, 2, 'closing confirmation should hide once');
	    assert.strictEqual(hiddenClassReads, 0, 'closing confirmation should use cached visibility without reading the hidden class');
	    assert.strictEqual(ariaExpandedWrites, 2, 'closing confirmation should collapse the drop button once');
	    assert.strictEqual(context.document.activeElement, memoryDrop, 'closing confirmation should restore focus to the drop trigger');
	    const afterClosedReads = totalReads();
	    const afterClosedWrites = totalWrites();

	    context.setMemoryDropConfirmPending(false, { sync: false });
	    assert.strictEqual(totalReads(), afterClosedReads, 'unchanged closed confirmation should not re-read state again');
	    assert.strictEqual(totalWrites(), afterClosedWrites, 'unchanged closed confirmation should not rewrite state again');
	    assert.deepStrictEqual(focusEvents.map(event => event.id), ['cancel', 'drop'], 'unchanged closed confirmation should not refocus');

	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

