  test('composer keyboard shortcuts respect IME composition', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [] } });

    const input = elements.get('input');
    assert.ok(input, 'expected input element to be created during startup');
    assert.strictEqual(typeof context.setInputHistoryEntries, 'function');
    input.value = '  draft message  ';

    const before = posted.length;
    let prevented = false;
    input.dispatchEvent({ type: 'compositionstart' });
    input.dispatchEvent({
      type: 'keydown',
      key: 'Enter',
      shiftKey: false,
      preventDefault: () => { prevented = true; },
    });

    assert.strictEqual(prevented, false, 'expected composing Enter to be left to the IME');
    assert.ok(!posted.slice(before).some(message => message && message.type === 'send'));

    context.setInputHistoryEntries(['previous prompt']);
    input.value = '';
    prevented = false;
    input.dispatchEvent({
      type: 'keydown',
      key: 'ArrowUp',
      preventDefault: () => { prevented = true; },
    });

    assert.strictEqual(prevented, false, 'expected composing ArrowUp to be left to the IME');
    assert.strictEqual(input.value, '', 'expected composing ArrowUp not to navigate input history');

    input.dispatchEvent({ type: 'compositionend' });
    prevented = false;
    input.dispatchEvent({
      type: 'keydown',
      key: 'Enter',
      keyCode: 229,
      shiftKey: false,
      preventDefault: () => { prevented = true; },
    });

    assert.strictEqual(prevented, false, 'expected keyCode 229 Enter fallback to be left to the IME');
    assert.ok(!posted.slice(before).some(message => message && message.type === 'send'));

    prevented = false;
    input.dispatchEvent({
      type: 'keydown',
      key: 'ArrowUp',
      preventDefault: () => { prevented = true; },
    });

    assert.strictEqual(prevented, true, 'expected ordinary ArrowUp to keep input history navigation');
    assert.strictEqual(input.value, 'previous prompt');

    input.value = '  draft message  ';
    prevented = false;
    input.dispatchEvent({
      type: 'keydown',
      key: 'Enter',
      shiftKey: false,
      preventDefault: () => { prevented = true; },
    });

    const sendMessages = posted.slice(before).filter(message => message && message.type === 'send');
    assert.strictEqual(prevented, true, 'expected ordinary Enter to keep send-on-enter behavior');
	    assert.strictEqual(sendMessages.length, 1);
	    assert.strictEqual(sendMessages[0].message, 'draft message');
	  });

