	    const longModelName = 'Friendly model ' + 'n'.repeat(170) + 'NAME_END_MARKER';
	    const picker = {
	      currentModel: 'current-model',
	      favorites: [{ id: longModelId, name: longModelName }],
	      recent: [],
	      all: [],
	    };
	    context.window.dispatchEvent({ type: 'message', data: { type: 'init', currentModel: 'current-model', messages: [] } });
	    context.window.dispatchEvent({ type: 'message', data: { type: 'modelPickerState', reveal: true, picker } });

	    const modelPickerList = elements.get('modelPickerList');
	    assert.ok(modelPickerList, 'expected model picker list to be created during startup');
	    assert.strictEqual(typeof context.getModelDisplayText, 'function');
	    const expectedDisplayName = context.getModelDisplayText(longModelName);

	    const buttons: any[] = [];
