	    assert.strictEqual(itemButton.title, 'Switch to model: ' + expectedDisplayName);
	    assert.strictEqual(itemButton.getAttribute('aria-label'), expectedDisplayName + ', switch model');
	    assert.strictEqual(favoriteButton.title, 'Remove from favorites: ' + expectedDisplayName);
	    assert.strictEqual(favoriteButton.getAttribute('aria-label'), 'Toggle favorite model: ' + expectedDisplayName);
	    assert.ok(!nameEl.textContent.includes('NAME_END_MARKER'));
	    assert.ok(!itemButton.title.includes('NAME_END_MARKER'));
	    assert.ok(!favoriteButton.title.includes('NAME_END_MARKER'));

	    const beforeFavoritePost = posted.length;
