	  test('model picker list delegates row actions without per-row handlers', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    const picker = {
	      currentModel: 'model-1',
	      favorites: [
	        { id: 'model-2', name: 'Model 2' },
	      ],
	      recent: [],
	      all: [
	        { id: 'model-1', name: 'Model 1' },
	      ],
	    };
	    context.window.dispatchEvent({ type: 'message', data: { type: 'init', currentModel: 'model-1', messages: [] } });
	    context.window.dispatchEvent({ type: 'message', data: { type: 'modelPickerState', reveal: true, picker } });

	    const modelPickerList = elements.get('modelPickerList');
	    assert.ok(modelPickerList, 'expected model picker list to be created during startup');
	    const collectButtons = () => {
	      const buttons: any[] = [];
	      const visit = (node: any) => {
	        if (!node) return;
	        if (node.type === 'button') buttons.push(node);
	        for (const child of node.children || []) visit(child);
	      };
	      visit(modelPickerList);
	      return buttons;
	    };
	    const buttons = collectButtons();
	    const favoriteButton = buttons.find(button => String(button.className || '').includes('model-picker-favorite'));
	    const switchButton = buttons.find(button => String(button.className || '').includes('model-picker-item') && !button.disabled);
	    assert.ok(favoriteButton, 'expected favorite action button');
	    assert.ok(switchButton, 'expected non-current model switch button');

	    let favoritePrevented = false;
	    let favoriteStopped = false;
	    const beforeFavoritePost = posted.length;
	    modelPickerList.dispatchEvent({
	      type: 'click',
	      target: favoriteButton.children[0],
	      preventDefault: () => { favoritePrevented = true; },
	      stopPropagation: () => { favoriteStopped = true; },
	    });
	    assert.strictEqual(favoritePrevented, true, 'favorite click should be claimed by the delegated list handler');
	    assert.strictEqual(favoriteStopped, true, 'favorite click should not bubble past the model picker list');
	    const favoritePosts = posted.slice(beforeFavoritePost).filter(message => message && message.type === 'toggleFavoriteModel');
	    assert.strictEqual(favoritePosts.length, 1);
	    assert.strictEqual(favoritePosts[0].model, 'model-2');

	    context.window.dispatchEvent({ type: 'message', data: { type: 'modelPickerState', reveal: true, picker } });
	    let switchPrevented = false;
	    const beforeSwitchPost = posted.length;
	    modelPickerList.dispatchEvent({
	      type: 'click',
	      target: switchButton.children[0],
	      preventDefault: () => { switchPrevented = true; },
	    });
	    assert.strictEqual(switchPrevented, true, 'model switch click should be claimed by the delegated list handler');
	    const switchPosts = posted.slice(beforeSwitchPost).filter(message => message && message.type === 'changeModel');
	    assert.strictEqual(switchPosts.length, 1);
	    assert.strictEqual(switchPosts[0].model, 'model-2');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

	  test('model picker list buttons skip duplicate disabled writes', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    context.window.dispatchEvent({ type: 'message', data: { type: 'init', currentModel: 'model-1', messages: [] } });
	    context.window.dispatchEvent({
	      type: 'message',
	      data: {
	        type: 'modelPickerState',
	        reveal: true,
		        picker: {
		          currentModel: 'model-1',
		          favorites: [
		            { id: 'model-2', name: 'Model 2' },
		          ],
		          recent: [],
		          all: [
		            { id: 'model-1', name: 'Model 1' },
		          ],
		        },
		      },
    });

	    const modelPickerList = elements.get('modelPickerList');
	    assert.ok(modelPickerList, 'expected model picker list to be created during startup');
	    const collectButtons = () => {
	      const buttons: any[] = [];
	      const visit = (node: any) => {
	        if (!node) return;
	        if (node.type === 'button') buttons.push(node);
	        for (const child of node.children || []) visit(child);
	      };
	      visit(modelPickerList);
	      return buttons;
	    };
			    const buttons = collectButtons();
			    assert.strictEqual(buttons.length, 4, 'expected each model row to render item and favorite buttons');
			    const activeModelPickerControls = buttons.filter(
			      button => !(String(button.className || '').includes('model-picker-item') && button.disabled)
			    );
			    const currentItemButton = buttons.find(button => button.disabled);
			    assert.ok(currentItemButton, 'expected current model select button to be disabled');
			    assert.strictEqual(currentItemButton.getAttribute('aria-label'), 'Model 1, current model');
			    assert.strictEqual(currentItemButton.title, 'Current model: Model 1');
			    const favoriteButtons = buttons.filter(button => String(button.className || '').includes('model-picker-favorite'));
			    assert.deepStrictEqual(
				      favoriteButtons.map(button => [
				        button.getAttribute('aria-label'),
				        button.getAttribute('aria-pressed'),
				        button.title,
				        button.children[0]?.getAttribute?.('aria-hidden'),
				        button.children[0]?.textContent,
				      ]),
				      [
				        ['Toggle favorite model: Model 2', 'true', 'Remove from favorites: Model 2', 'true', '★'],
				        ['Toggle favorite model: Model 1', 'false', 'Add to favorites: Model 1', 'true', '☆'],
				      ]
				    );

	    let queryCount = 0;
	    modelPickerList.querySelectorAll = (selector: string) => {
	      assert.strictEqual(selector, 'button');
	      queryCount++;
	      return collectButtons();
	    };
	    let hiddenReadCount = 0;
	    const originalModelPickerListContains = modelPickerList.classList.contains;
	    modelPickerList.classList.contains = (name: string) => {
	      if (name === 'hidden') hiddenReadCount++;
	      return originalModelPickerListContains(name);
	    };

	    let disabledWrites = 0;
	    for (const button of buttons) {
	      let disabled = !!button.disabled;
	      Object.defineProperty(button, 'disabled', {
	        configurable: true,
	        get: () => disabled,
	        set: (value: unknown) => {
	          disabledWrites++;
	          disabled = !!value;
	        },
	      });
	    }

		    assert.strictEqual(typeof context.setModelPickerListControlsDisabled, 'function');
		    context.setModelPickerListControlsDisabled(false, { force: true });
		    assert.strictEqual(queryCount, 0, 'forced visible model picker sync should use cached button refs');
		    assert.strictEqual(disabledWrites, 0, 'already-enabled model picker buttons should not rewrite disabled=false');
		    assert.strictEqual(currentItemButton.disabled, true, 'current model select button should remain disabled');

		    context.setModelPickerListControlsDisabled(true);
		    assert.strictEqual(queryCount, 0, 'disabling model picker buttons should not rescan rendered rows');
		    assert.strictEqual(disabledWrites, activeModelPickerControls.length, 'disabling should write each active model picker control once');
		    const queriesAfterDisable = queryCount;
		    context.setModelPickerListControlsDisabled(true);
		    assert.strictEqual(queryCount, queriesAfterDisable, 'unchanged disabled state should not rescan model picker buttons');
		    assert.strictEqual(disabledWrites, activeModelPickerControls.length, 'unchanged disabled state should not rewrite model picker buttons');

		    context.setModelPickerListControlsDisabled(false);
		    assert.strictEqual(queryCount, queriesAfterDisable, 'enabling model picker buttons should not rescan rendered rows');
		    assert.strictEqual(disabledWrites, activeModelPickerControls.length * 2, 'enabling should write each active model picker control once');
		    assert.strictEqual(currentItemButton.disabled, true, 'current model select button should stay disabled after reenabling controls');
		    assert.strictEqual(hiddenReadCount, 0, 'model picker control sync should reuse cached visibility');
		    modelPickerList.classList.contains = originalModelPickerListContains;
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

	  test('model picker list control sync prunes detached row controls', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    context.window.dispatchEvent({ type: 'message', data: { type: 'init', currentModel: 'model-1', messages: [] } });
	    context.window.dispatchEvent({
	      type: 'message',
	      data: {
	        type: 'modelPickerState',
	        reveal: true,
	        picker: {
	          currentModel: 'model-1',
	          favorites: [
	            { id: 'model-2', name: 'Model 2' },
	          ],
	          recent: [],
	          all: [
	            { id: 'model-1', name: 'Model 1' },
	          ],
	        },
	      },
	    });

	    const modelPickerList = elements.get('modelPickerList');
	    assert.ok(modelPickerList, 'expected model picker list to be created during startup');
	    const collectButtons = () => {
	      const buttons: any[] = [];
	      const visit = (node: any) => {
	        if (!node) return;
	        if (node.type === 'button') buttons.push(node);
	        for (const child of node.children || []) visit(child);
	      };
	      visit(modelPickerList);
	      return buttons;
	    };
	    const buttons = collectButtons();
	    const activeModelPickerControls = buttons.filter(
	      button => !(String(button.className || '').includes('model-picker-item') && button.disabled)
	    );
	    assert.strictEqual(activeModelPickerControls.length, 3, 'expected three cached active model picker controls');

	    let detachedDisabledWrites = 0;
	    for (const button of activeModelPickerControls) {
	      let disabled = !!button.disabled;
	      Object.defineProperty(button, 'disabled', {
	        configurable: true,
	        get: () => disabled,
	        set: (value: unknown) => {
	          detachedDisabledWrites++;
	          disabled = !!value;
	        },
	      });
	    }

	    let queryCount = 0;
	    modelPickerList.querySelectorAll = () => {
	      queryCount++;
	      throw new Error('model picker control sync should use cached row controls');
	    };
	    let containsChecks = 0;
	    modelPickerList.contains = (node: unknown) => {
	      containsChecks++;
	      return !activeModelPickerControls.includes(node);
	    };
	    modelPickerList.replaceChildren();

	    assert.strictEqual(typeof context.setModelPickerListControlsDisabled, 'function');
	    context.setModelPickerListControlsDisabled(true);
	    assert.strictEqual(queryCount, 0, 'processing sync should not rescan detached model picker rows');
	    assert.strictEqual(containsChecks, activeModelPickerControls.length, 'processing sync should validate each cached model picker control once');
	    assert.strictEqual(detachedDisabledWrites, 0, 'processing sync should not write detached model picker controls');

	    context.setModelPickerListControlsDisabled(false);
	    assert.strictEqual(queryCount, 0, 'idle sync should not rescan pruned model picker rows');
	    assert.strictEqual(containsChecks, activeModelPickerControls.length, 'idle sync should not recheck controls after pruning them');
	    assert.strictEqual(detachedDisabledWrites, 0, 'idle sync should not write pruned model picker controls');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

