	    context.appendCompactRenderStateKeyPart(expectedToolKeyBuilder, secretTool.name);
	    context.appendCompactRenderStateKeyPart(expectedToolKeyBuilder, secretTool.description);
	    context.appendCompactRenderStateKeyPart(expectedToolKeyBuilder, secretTool.category);
	    context.appendCompactRenderStateKeyPart(expectedToolKeyBuilder, '1');
	    context.appendCompactRenderStateKeyPart(expectedToolKeyBuilder, '0');
	    context.appendCompactRenderStateKeyPart(expectedToolKeyBuilder, secretToolParamText.renderKey);
	    context.appendCompactRenderStateKeyPart(expectedToolKeyBuilder, '1');
	    context.appendCompactRenderStateKeyPart(expectedToolKeyBuilder, context.getToolCatalogDefaultRenderKey(secretTool.parameters.properties.path));
	    assert.strictEqual(secretToolRenderText, context.finishCompactRenderStateKey(expectedToolKeyBuilder));
	    assert.ok(secretToolRenderText.length < 32, 'tool catalog per-tool render key should stay compact');
	    assert.ok(!secretToolRenderText.includes('tools-catalog-key-secret'), 'tool catalog per-tool render key should not retain raw metadata');
	    const secretCatalogRenderKey = context.getToolsCatalogRenderKey(
	      { tools: [secretTool], filter: ['tools-catalog-key-secret-filter'] },
	      1,
	      1,
	      'tools-catalog-key-secret-query',
	      'tools-catalog-key-secret-query',
	      1,
	      secretToolRenderText
	    );
	    const expectedCatalogKeyBuilder = context.createCompactRenderStateKeyBuilder();
	    context.appendCompactRenderStateKeyPart(expectedCatalogKeyBuilder, 1);
	    context.appendCompactRenderStateKeyPart(expectedCatalogKeyBuilder, 1);
	    context.appendCompactRenderStateKeyPart(expectedCatalogKeyBuilder, 'tools-catalog-key-secret-query');
	    context.appendCompactRenderStateKeyPart(expectedCatalogKeyBuilder, 'tools-catalog-key-secret-query');
	    context.appendCompactRenderStateKeyPart(expectedCatalogKeyBuilder, 1);
	    context.appendCompactRenderStateKeyPart(expectedCatalogKeyBuilder, 1);
	    context.appendCompactRenderStateKeyPart(expectedCatalogKeyBuilder, 'tools-catalog-key-secret-filter');
	    context.appendCompactRenderStateKeyPart(expectedCatalogKeyBuilder, 1);
