			    toolsCatalogSearchInput.value = longQuery;
			    toolsCatalogSearchInput.dispatchEvent({ type: 'input' });
			    assert.strictEqual(frames.length, 1, 'long tool search should schedule one render frame');
			    frames.shift()?.();

			    const summary = toolsCatalog.children.find((child: any) => child.className === 'tools-catalog-summary');
			    const empty = toolsCatalog.children.find((child: any) => child.className === 'tools-catalog-empty');
