			  test('tool catalog row display caps long provider metadata', () => {
			    const controller = createStandaloneChatController();
			    const webview = {
			      cspSource: 'test-csp',
			      asWebviewUri: (uri: unknown) => uri,
			    } as unknown as vscode.Webview;

			    const html = controller.webviewApi.getHtml(webview);
			    const scripts = extractOrderedScriptSources(html);
			    const { context, elements, posted } = createMockBrowserContext();
			    runScriptsInMockBrowser(scripts, context);

			    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [] } });
			    assert.strictEqual(typeof context.getToolsCatalogRowDisplayText, 'function');
			    assert.strictEqual(typeof context.getToolCatalogParamText, 'function');
			    assert.strictEqual(typeof context.getToolCatalogSearchText, 'function');
			    assert.strictEqual(context.getToolsCatalogRowDisplayText('x'.repeat(241), 240), 'x'.repeat(240) + '…');

			    const properties: Record<string, { type: string }> = {};
			    const required: string[] = [];
			    for (let index = 0; index < 20; index++) {
			      const name = 'param_' + String(index).padStart(2, '0') + '_' + 'p'.repeat(24);
			      properties[name] = { type: 'string' };
			      if (index % 3 === 0) required.push(name);
			    }
			    const hiddenParam = 'param_' + 'z'.repeat(180) + '_END_MARKER';
			    properties[hiddenParam] = { type: 'string' };
			    required.push(hiddenParam);
			    const longToolId = 'workspace_long_row_' + 'i'.repeat(170) + '_ID_END_MARKER';
			    const expectedToolIdDisplay = longToolId.slice(0, 160) + '…';
			    const longDescription = 'Description ' + 'd'.repeat(260) + 'END_MARKER';
			    const longCategory = 'category-' + 'c'.repeat(80) + 'END_MARKER';
			    const tool = {
			      id: longToolId,
			      name: 'Workspace long row',
			      description: longDescription,
			      readOnly: true,
			      requiresApproval: false,
			      category: longCategory,
			      parameters: { type: 'object', properties },
			      required,
			    };

			    const paramText = context.getToolCatalogParamText(tool);
			    assert.ok(paramText.renderText.endsWith('…'), 'expected parameter summary to be truncated');
			    assert.ok(paramText.renderText.length <= 241, 'expected parameter summary to stay capped');
			    assert.doesNotMatch(paramText.renderText, /END_MARKER/);
			    assert.ok(context.getToolCatalogSearchText(tool).includes('end_marker'), 'full metadata should remain searchable');
			    assert.ok(context.getToolCatalogSearchText(tool).includes('id_end_marker'), 'full tool id should remain searchable');

			    context.window.dispatchEvent({
			      type: 'message',
			      data: {
			        type: 'toolsCatalogState',
			        reveal: true,
			        toolsCatalog: {
			          total: 1,
			          shown: 1,
			          filter: [],
			          tools: [tool],
			        },
			      },
			    });

			    const toolsCatalog = elements.get('toolsCatalog');
			    assert.ok(toolsCatalog, 'expected tools catalog element');
			    const items = toolsCatalog.children.find((child: any) => child.className === 'tools-catalog-items');
			    const item = items?.children?.[0];
			    assert.ok(item, 'expected visible tools catalog item');
			    const head = item.children.find((child: any) => child.className === 'tools-catalog-head');
			    const id = head?.children?.find((child: any) => child.className === 'tools-catalog-id');
			    const badges = head?.children?.find((child: any) => child.className === 'tools-catalog-badges');
			    const categoryBadge = badges?.children?.[1];
			    const desc = item.children.find((child: any) => child.className === 'tools-catalog-desc');
			    const params = item.children.find((child: any) => child.className === 'tools-catalog-params');
			    const runner = item.children.find((child: any) => child.className === 'tools-catalog-runner');
			    const args = runner?.children?.find((child: any) => child.className === 'tools-catalog-args');
			    const runRow = runner?.children?.find((child: any) => child.className === 'tools-catalog-run-row');
			    const status = runRow?.children?.find((child: any) => child.className === 'tools-catalog-status');
			    const runButton = runRow?.children?.find((child: any) => child.className === 'context-btn');
			    assert.ok(id, 'expected tool id element');
			    assert.ok(desc, 'expected description element');
			    assert.ok(params, 'expected params element');
			    assert.ok(args, 'expected arguments element');
			    assert.ok(status, 'expected status element');
			    assert.ok(runButton, 'expected run button');
			    assert.ok(categoryBadge, 'expected category badge');
			    assert.strictEqual(id.textContent, expectedToolIdDisplay);
			    assert.strictEqual(id.title, expectedToolIdDisplay);
			    assert.strictEqual(args.getAttribute('aria-label'), 'Arguments for ' + expectedToolIdDisplay);
			    assert.strictEqual(args.getAttribute('aria-describedby'), status.id);
			    assert.strictEqual(status.id, 'toolsCatalogRunStatus-0');
			    assert.strictEqual(runButton.getAttribute('aria-label'), 'Run ' + expectedToolIdDisplay);
			    assert.strictEqual(runButton.title, 'Run ' + expectedToolIdDisplay);
			    assert.ok(String(desc.textContent).endsWith('…'), 'expected description display text to be truncated');
			    assert.ok(String(desc.textContent).length <= 241, 'expected description display text to stay capped');
			    assert.ok(String(categoryBadge.textContent).endsWith('…'), 'expected category badge display text to be truncated');
			    assert.ok(String(categoryBadge.textContent).length <= 49, 'expected category badge display text to stay capped');
			    assert.strictEqual(params.textContent, paramText.renderText);
			    assert.doesNotMatch(
			      String(id.textContent) +
			        String(id.title) +
			        String(args.getAttribute('aria-label') || '') +
			        String(args.getAttribute('aria-describedby') || '') +
			        String(status.id) +
			        String(runButton.getAttribute('aria-label') || '') +
			        String(runButton.title) +
			        String(desc.textContent) +
			        String(categoryBadge.textContent) +
			        String(params.textContent),
			      /(?:END_MARKER|ID_END_MARKER)/
			    );
			    const beforeRun = posted.length;
			    toolsCatalog.dispatchEvent({ type: 'click', target: runButton, preventDefault: () => {} });
			    const runPosts = posted.slice(beforeRun).filter(message => message && message.type === 'runTool');
			    assert.strictEqual(runPosts.length, 1, 'running a capped tool id should post once');
			    assert.strictEqual(runPosts[0].toolId, longToolId);
			    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
			  });

