    runScriptsInMockBrowser(scripts, context);
    context.requestAnimationFrame = (callback: () => void) => {
      callback();
      return 1;
    };

	    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [] } });
	    assert.strictEqual(typeof context.getManualToolResultRenderInfo, 'function');
	    assert.strictEqual(typeof context.createCompactRenderStateKeyBuilder, 'function');
	    assert.strictEqual(typeof context.appendCompactRenderStateKeyPart, 'function');
	    assert.strictEqual(typeof context.finishCompactRenderStateKey, 'function');
	    const secretManualResult = context.getManualToolResultRenderInfo({
	      toolId: 'manual-result-key-secret-tool',
	      success: false,
      error: 'manual-result-key-secret-error-' + 'x'.repeat(80),
      data: 'manual-result-key-secret-output-' + 'y'.repeat(4100),
	      truncated: true,
	    });
	    assert.ok(secretManualResult, 'expected manual tool result render info');
	    const expectedManualResultKeyBuilder = context.createCompactRenderStateKeyBuilder();
	    context.appendCompactRenderStateKeyPart(expectedManualResultKeyBuilder, secretManualResult.summaryText);
	    context.appendCompactRenderStateKeyPart(expectedManualResultKeyBuilder, secretManualResult.outputText.length);
	    context.appendCompactRenderStateKeyPart(expectedManualResultKeyBuilder, secretManualResult.outputPreviewText);
	    assert.strictEqual(secretManualResult.renderKey, context.finishCompactRenderStateKey(expectedManualResultKeyBuilder));
