    assert.strictEqual(dropdownAppendCount, 0, 'single skill dropdown result should avoid direct live dropdown appends');
    assert.strictEqual(items.length, 1);
    assert.strictEqual(items[0].id, 'skillDropdownOption-0');
    assert.strictEqual(items[0].textContent, 'read');
    assert.strictEqual(items[0].getAttribute('aria-selected'), 'true');
    assert.strictEqual(input.getAttribute('aria-expanded'), 'true');
