  test('skill dropdown filters large skill lists without extra arrays and batches visible rows', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const bootstrap = scripts.find(script => script.label === 'bootstrap.js')?.source || '';
	    assert.match(html, /\.skill-dropdown\s*\{[\s\S]*?overflow-y:\s*auto;[\s\S]*?overscroll-behavior:\s*contain;/);
	    const { context, elements } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });

    const input = elements.get('input');
    const skillDropdown = elements.get('skillDropdown');
    assert.ok(input, 'expected composer input to be created during startup');
    assert.ok(skillDropdown, 'expected skill dropdown to be created during startup');
	    assert.strictEqual(typeof context.normalizeAvailableSkills, 'function');
	    assert.strictEqual(typeof context.getSkillDropdownRenderKey, 'function');
	    assert.strictEqual(typeof context.createCompactRenderStateKeyBuilder, 'function');
	    assert.strictEqual(typeof context.appendCompactRenderStateKeyPart, 'function');
	    assert.strictEqual(typeof context.finishCompactRenderStateKey, 'function');
	    const secretSkillName = 'skill-dropdown-key-secret-' + 'x'.repeat(120);
	    const secretAvailableSkills = context.normalizeAvailableSkills([secretSkillName]);
	    const expectedAvailableSkillsKeyBuilder = context.createCompactRenderStateKeyBuilder();
	    context.appendCompactRenderStateKeyPart(expectedAvailableSkillsKeyBuilder, secretSkillName);
	    context.appendCompactRenderStateKeyPart(expectedAvailableSkillsKeyBuilder, 1);
	    assert.strictEqual(secretAvailableSkills.key, context.finishCompactRenderStateKey(expectedAvailableSkillsKeyBuilder));
	    assert.ok(secretAvailableSkills.key.length < 32, 'available skills key should stay compact');
	    assert.ok(!secretAvailableSkills.key.includes('skill-dropdown-key-secret'), 'available skills key should not retain raw skill names');
	    input.value = '$skill-dropdown-key-secret';
	    input.selectionStart = input.value.length;
	    input.selectionEnd = input.value.length;
	    context.setAvailableSkills([secretSkillName]);
	    const secretDropdownRenderKey = context.getSkillDropdownRenderKey();
	    const expectedDropdownKeyBuilder = context.createCompactRenderStateKeyBuilder();
	    context.appendCompactRenderStateKeyPart(expectedDropdownKeyBuilder, 1);
	    context.appendCompactRenderStateKeyPart(expectedDropdownKeyBuilder, secretSkillName);
	    assert.strictEqual(secretDropdownRenderKey, context.finishCompactRenderStateKey(expectedDropdownKeyBuilder));
	    assert.ok(secretDropdownRenderKey.length < 32, 'skill dropdown render key should stay compact');
	    assert.ok(!secretDropdownRenderKey.includes('skill-dropdown-key-secret'), 'skill dropdown render key should not retain raw visible skill names');

    input.value = '$skill_09';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;

	    let dropdownAppendCount = 0;
	    let dropdownReplaceCount = 0;
	    const originalAppendChild = skillDropdown.appendChild;
	    const originalReplaceChildren = skillDropdown.replaceChildren;
	    skillDropdown.appendChild = (child: unknown) => {
	      dropdownAppendCount++;
	      return originalAppendChild.call(skillDropdown, child);
	    };
	    skillDropdown.replaceChildren = (...children: unknown[]) => {
	      dropdownReplaceCount++;
	      return originalReplaceChildren.call(skillDropdown, ...children);
	    };

    let ariaSelectedReads = 0;
    const originalCreateElement = context.document.createElement;
    context.document.createElement = (tag: string) => {
      const el = originalCreateElement.call(context.document, tag);
      const originalGetAttribute = el.getAttribute;
      el.getAttribute = (name: string) => {
        if (name === 'aria-selected') ariaSelectedReads++;
        return originalGetAttribute.call(el, name);
      };
      return el;
    };

    const skills = Array.from({ length: 500 }, (_value, index) => `skill_${String(index).padStart(3, '0')}`);
    assert.strictEqual(typeof context.setAvailableSkills, 'function');
    if (!context.JSON) context.JSON = JSON;
    const originalJsonStringify = context.JSON.stringify;
    let stringifyCalls = 0;
    context.JSON.stringify = (...args: unknown[]) => {
      stringifyCalls++;
      return Reflect.apply(originalJsonStringify, context.JSON, args);
    };
    context.setAvailableSkills(skills);
    assert.strictEqual(stringifyCalls, 0, 'skill catalog updates should avoid JSON serialization for unchanged-key detection');
    context.JSON.stringify = originalJsonStringify;

	    const items = skillDropdown.children.filter((child: any) => String(child.className).includes('skill-dropdown-item'));
	    assert.strictEqual(dropdownReplaceCount, 1, 'expected visible skill rows to replace live dropdown children once');
	    assert.strictEqual(dropdownAppendCount, 0, 'expected visible skill rows to avoid direct live dropdown appends');
	    assert.strictEqual(items.length, 10);
    assert.strictEqual(items[0].textContent, 'skill_090');
    assert.strictEqual(items[9].textContent, 'skill_099');
    assert.strictEqual(ariaSelectedReads, 0, 'fresh skill dropdown render should not run the existing-row selection sync pass');
    assert.doesNotMatch(bootstrap, /availableSkills\.filter/, 'expected skill filtering to avoid full intermediate arrays');

	    input.value = '$target';
	    input.selectionStart = input.value.length;
	    input.selectionEnd = input.value.length;
	    context.setAvailableSkills(['alpha-target', 'target-start', 'target-other']);
	    const prefixItems = skillDropdown.children.filter((child: any) => String(child.className).includes('skill-dropdown-item'));
	    assert.deepStrictEqual(
	      prefixItems.map((child: any) => child.textContent),
	      ['target-start', 'target-other'],
	      'prefix matches should replace earlier substring matches when they appear later in the skill list'
	    );

	    const longPrefix = Array.from({ length: 200 }, (_value, index) => `word${index}`).join(' ');
	    input.value = `${longPrefix} $target trailing`;
	    input.selectionStart = input.value.length;
	    input.selectionEnd = input.value.length;
	    input.dispatchEvent({ type: 'input' });
	    assert.ok(skillDropdown.classList.contains('hidden'), 'skill dropdown should follow only the token at the caret');

	    input.value = `${longPrefix} $target`;
	    input.selectionStart = input.value.length;
	    input.selectionEnd = input.value.length;
	    input.dispatchEvent({ type: 'input' });
	    const longPrefixItems = skillDropdown.children.filter((child: any) => String(child.className).includes('skill-dropdown-item'));
	    assert.deepStrictEqual(
	      longPrefixItems.map((child: any) => child.textContent),
	      ['target-start', 'target-other'],
	      'skill dropdown should match the current token after a long prompt prefix'
	    );
  });

  test('skill dropdown arrow navigation updates selection without rebuilding rows', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });

    const input = elements.get('input');
    const skillDropdown = elements.get('skillDropdown');
    assert.ok(input, 'expected composer input to be created during startup');
    assert.ok(skillDropdown, 'expected skill dropdown to be created during startup');

    let innerHtml = skillDropdown.innerHTML || '';
    let clearWrites = 0;
    Object.defineProperty(skillDropdown, 'innerHTML', {
      configurable: true,
      get: () => innerHtml,
      set(value: unknown) {
        innerHtml = String(value);
        if (innerHtml === '') {
          clearWrites++;
          skillDropdown.children = [];
          skillDropdown.firstChild = null;
        }
      },
    });

    let dropdownAppendCount = 0;
    const originalAppendChild = skillDropdown.appendChild;
    skillDropdown.appendChild = (child: unknown) => {
      dropdownAppendCount++;
      return originalAppendChild.call(skillDropdown, child);
    };

    input.value = '$skill_0';
    input.selectionStart = input.value.length;
    input.selectionEnd = input.value.length;
    context.setAvailableSkills(['skill_000', 'skill_001', 'skill_002']);

    const items = skillDropdown.children.filter((child: any) => String(child.className).includes('skill-dropdown-item'));
    assert.strictEqual(items.length, 3);
    assert.strictEqual(items[0].id, 'skillDropdownOption-0');
	    for (const item of items) {
	      assert.strictEqual(item.dataset.index, undefined);
	    }
	    assert.strictEqual(items[0].type, undefined, 'skill listbox options should not be interactive buttons');
	    assert.match(String(items[0].className), /\bselected\b/);
	    assert.strictEqual(items[0].getAttribute('aria-selected'), 'true');
	    assert.strictEqual(items[1].getAttribute('aria-selected'), undefined);
	    assert.strictEqual(input.getAttribute('aria-expanded'), 'true');
	    assert.strictEqual(input.getAttribute('aria-activedescendant'), 'skillDropdownOption-0');
	    let ariaSelectedReads = 0;
	    let ariaSelectedWrites = 0;
	    let ariaSelectedRemovals = 0;
	    for (const item of items) {
	      const originalGetAttribute = item.getAttribute;
	      const originalSetAttribute = item.setAttribute;
	      const originalRemoveAttribute = item.removeAttribute;
	      item.getAttribute = (name: string) => {
	        if (name === 'aria-selected') ariaSelectedReads++;
	        return originalGetAttribute.call(item, name);
	      };
	      item.setAttribute = (name: string, value: unknown) => {
	        if (name === 'aria-selected') ariaSelectedWrites++;
	        return originalSetAttribute.call(item, name, value);
	      };
	      item.removeAttribute = (name: string) => {
	        if (name === 'aria-selected') ariaSelectedRemovals++;
	        return originalRemoveAttribute.call(item, name);
	      };
	    }

	    dropdownAppendCount = 0;
	    clearWrites = 0;
	    ariaSelectedReads = 0;
	    ariaSelectedWrites = 0;
	    ariaSelectedRemovals = 0;
	    let prevented = 0;
	    input.dispatchEvent({ type: 'keydown', key: 'ArrowDown', preventDefault: () => { prevented++; } });

	    assert.strictEqual(prevented, 1);
	    assert.strictEqual(dropdownAppendCount, 0, 'arrow selection should not append rebuilt option rows');
	    assert.strictEqual(clearWrites, 0, 'arrow selection should not clear the dropdown body');
	    assert.strictEqual(ariaSelectedReads, 1, 'arrow selection should only inspect the newly selected option aria state');
	    assert.strictEqual(ariaSelectedWrites, 1, 'arrow selection should only set the newly selected option aria state');
	    assert.strictEqual(ariaSelectedRemovals, 1, 'arrow selection should remove aria-selected from the previous option');
	    assert.doesNotMatch(String(items[0].className), /\bselected\b/);
	    assert.strictEqual(items[0].getAttribute('aria-selected'), undefined);
	    assert.match(String(items[1].className), /\bselected\b/);
	    assert.strictEqual(items[1].getAttribute('aria-selected'), 'true');
	    assert.strictEqual(input.getAttribute('aria-activedescendant'), 'skillDropdownOption-1');

	    assert.strictEqual(typeof context.renderSkillDropdown, 'function');
	    ariaSelectedReads = 0;
	    ariaSelectedWrites = 0;
	    ariaSelectedRemovals = 0;
	    context.renderSkillDropdown();
	    assert.strictEqual(dropdownAppendCount, 0, 'selection-only rerender should not append rebuilt option rows');
	    assert.strictEqual(clearWrites, 0, 'selection-only rerender should not clear the dropdown body');
	    assert.strictEqual(ariaSelectedReads, 0, 'already-synced selection rerender should not inspect option aria states');
	    assert.strictEqual(ariaSelectedWrites, 0, 'already-synced selection rerender should not rewrite option aria states');
	    assert.strictEqual(ariaSelectedRemovals, 0, 'already-synced selection rerender should not remove option aria state');

		    ariaSelectedReads = 0;
		    ariaSelectedWrites = 0;
		    ariaSelectedRemovals = 0;
		    input.dispatchEvent({ type: 'keydown', key: 'ArrowUp', preventDefault: () => { prevented++; } });
		    assert.strictEqual(dropdownAppendCount, 0, 'reverse arrow selection should not append rebuilt option rows');
		    assert.strictEqual(clearWrites, 0, 'reverse arrow selection should not clear the dropdown body');
		    assert.strictEqual(ariaSelectedReads, 1, 'reverse arrow selection should only inspect the newly selected option aria state');
		    assert.strictEqual(ariaSelectedWrites, 1, 'reverse arrow selection should only set the newly selected option aria state');
		    assert.strictEqual(ariaSelectedRemovals, 1, 'reverse arrow selection should remove aria-selected from the previous option');
		    assert.match(String(items[0].className), /\bselected\b/);
		    assert.strictEqual(items[0].getAttribute('aria-selected'), 'true');
		    assert.strictEqual(items[1].getAttribute('aria-selected'), undefined);
	    assert.strictEqual(input.getAttribute('aria-activedescendant'), 'skillDropdownOption-0');

	    const modelSettingsPopover = elements.get('modelSettingsPopover');
	    const modelSettings = elements.get('modelSettings');
	    assert.ok(modelSettingsPopover, 'expected model settings popover to be created during startup');
	    assert.ok(modelSettings, 'expected model settings trigger to be created during startup');
	    context.document.activeElement = modelSettings;
	    context.openModelSettingsPopover();
	    assert.strictEqual(modelSettingsPopover.classList.contains('hidden'), false, 'expected model settings popover to open for Escape containment check');
	    const skillEscape: any = { type: 'keydown', key: 'Escape' };
	    input.dispatchEvent(skillEscape);
	    if (!skillEscape.cancelBubble) context.document.dispatchEvent(skillEscape);
	    assert.strictEqual(skillDropdown.classList.contains('hidden'), true, 'skill Escape should close the autocomplete listbox');
	    assert.strictEqual(modelSettingsPopover.classList.contains('hidden'), false, 'skill Escape should not bubble into document popover dismissal');
	    assert.strictEqual(skillEscape.defaultPrevented, true, 'skill Escape should be consumed');
	    assert.strictEqual(skillEscape.__stopImmediatePropagation, true, 'skill Escape should stop same-turn document Escape handlers');

	    input.value = 'ordinary input';
	    input.selectionStart = input.value.length;
	    input.selectionEnd = input.value.length;
    input.dispatchEvent({ type: 'input' });
    assert.strictEqual(input.getAttribute('aria-expanded'), 'false');
    assert.strictEqual(input.getAttribute('aria-activedescendant'), undefined);
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

