		    assert.strictEqual(clearWrites, 0, 'expected initial mention render to avoid innerHTML clearing');
		    assert.strictEqual(hiddenClassWrites, 1, 'opening dropdown should reveal once');
		    assert.strictEqual(hiddenClassReads, 0, 'opening dropdown should apply cached visibility without hidden reads');
		    assert.strictEqual(expandedWrites, 1, 'opening dropdown should set expanded state once');
		    assert.strictEqual(activeDescendantWrites, 1, 'opening dropdown should set active descendant once');
		    assert.strictEqual(expandedReads, 1, 'opening dropdown should inspect expanded state once');
		    assert.strictEqual(activeDescendantReads, 1, 'opening dropdown should inspect active descendant once');

		    dropdownAppendCount = 0;
