		    clearWrites = 0;
		    expandedReads = 0;
		    activeDescendantReads = 0;
		    context.setAvailableSkills(largeSkills.slice());
		    assert.strictEqual(dropdownReplaceCount, 0, 'unchanged skill list should not replace dropdown children');
		    assert.strictEqual(dropdownAppendCount, 0, 'unchanged skill list should not rebuild visible rows');
		    assert.strictEqual(clearWrites, 0, 'unchanged skill list should not clear dropdown body');
	    assert.strictEqual(hiddenClassWrites, 1, 'unchanged skill list should not rewrite visibility');
	    assert.strictEqual(hiddenClassReads, 0, 'unchanged skill list should not reread visibility');
	    assert.strictEqual(expandedWrites, 1, 'unchanged skill list should not rewrite expanded state');
	    assert.strictEqual(activeDescendantWrites, 1, 'unchanged skill list should not rewrite active descendant');
	    assert.strictEqual(expandedReads, 0, 'unchanged skill list should not read expanded state');
	    assert.strictEqual(activeDescendantReads, 0, 'unchanged skill list should not read active descendant state');

	    input.dispatchEvent({ type: 'keyup' });
	    input.dispatchEvent({ type: 'click' });
		    input.dispatchEvent({ type: 'focus' });
	    assert.strictEqual(dropdownReplaceCount, 0, 'unchanged mention context should not replace dropdown children');
	    assert.strictEqual(dropdownAppendCount, 0, 'unchanged mention context should not rebuild visible rows');
    assert.strictEqual(clearWrites, 0, 'unchanged mention context should not clear dropdown body');
    assert.strictEqual(hiddenClassWrites, 1, 'unchanged visible dropdown should not rewrite visibility');
    assert.strictEqual(hiddenClassReads, 0, 'unchanged visible dropdown should not reread visibility');
    assert.strictEqual(expandedWrites, 1, 'unchanged visible dropdown should not rewrite expanded state');
    assert.strictEqual(activeDescendantWrites, 1, 'unchanged visible dropdown should not rewrite active descendant');
    assert.strictEqual(expandedReads, 0, 'unchanged visible dropdown should not read expanded state');
    assert.strictEqual(activeDescendantReads, 0, 'unchanged visible dropdown should not read active descendant state');

    input.value = '$skill_08';
    input.selectionStart = input.value.length;
	    input.selectionEnd = input.value.length;
	    expandedReads = 0;
	    activeDescendantReads = 0;
