  test('todo popover skips unchanged body rebuilds', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted, getCreatedCount } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const todoPopoverBody = elements.get('todoPopoverBody');
    assert.ok(todoPopoverBody, 'expected todo popover body to be created during startup');

    let innerHtml = todoPopoverBody.innerHTML || '';
    let clearWrites = 0;
    Object.defineProperty(todoPopoverBody, 'innerHTML', {
      configurable: true,
      get: () => innerHtml,
      set(value: unknown) {
        innerHtml = String(value);
        if (innerHtml === '') {
          clearWrites++;
          todoPopoverBody.children = [];
          todoPopoverBody.firstChild = null;
        }
      },
    });

    let bodyAppendCount = 0;
    let bodyReplaceCount = 0;
    const originalAppendChild = todoPopoverBody.appendChild;
    const originalReplaceChildren = todoPopoverBody.replaceChildren;
    todoPopoverBody.appendChild = (child: unknown) => {
      bodyAppendCount++;
      return originalAppendChild.call(todoPopoverBody, child);
    };
    todoPopoverBody.replaceChildren = (...children: unknown[]) => {
      bodyReplaceCount++;
      return originalReplaceChildren.call(todoPopoverBody, ...children);
    };

	    const todos = Array.from({ length: 120 }, (_value, index) => ({
	      content: `Todo ${index}`,
	      status: index === 0 ? 'in_progress' : index % 7 === 0 ? 'completed' : 'pending',
	      priority: index % 3 === 0 ? 'high' : 'medium',
	    }));

	    assert.strictEqual(typeof context.renderTodoPopover, 'function');
	    context.renderTodoPopover([]);
	    assert.strictEqual(todoPopoverBody.getAttribute('role'), 'note');
	    assert.strictEqual(todoPopoverBody.getAttribute('aria-label'), 'Todo list status');
	    assert.strictEqual(todoPopoverBody.children.length, 1);
	    assert.strictEqual(todoPopoverBody.children[0].className, 'todo-empty');
	    assert.strictEqual(todoPopoverBody.children[0].textContent, 'No todos yet. The agent can use todowrite to track a plan.');
	    assert.strictEqual(bodyAppendCount, 0, 'initial empty todo render should avoid appendChild on the live popover body');
	    assert.strictEqual(bodyReplaceCount, 1, 'initial empty todo render should replace once');
	    assert.strictEqual(clearWrites, 0, 'initial empty todo render should avoid innerHTML clearing');

	    bodyAppendCount = 0;
	    bodyReplaceCount = 0;
	    clearWrites = 0;
	    context.renderTodoPopover(todos);
	    assert.strictEqual(bodyAppendCount, 0, 'expected initial todo render to avoid appendChild on the live popover body');
	    assert.strictEqual(bodyReplaceCount, 1, 'expected initial todo render to replace once');
    assert.strictEqual(clearWrites, 0, 'expected initial todo render to avoid innerHTML clearing');
    const createdAfterInitialRender = getCreatedCount();

    bodyAppendCount = 0;
    bodyReplaceCount = 0;
    clearWrites = 0;
    context.renderTodoPopover(todos.map(todo => ({ ...todo })));

    assert.strictEqual(bodyAppendCount, 0, 'unchanged todo data should not append another fragment');
    assert.strictEqual(bodyReplaceCount, 0, 'unchanged todo data should not replace the popover body');
    assert.strictEqual(clearWrites, 0, 'unchanged todo data should not clear the popover body');
    assert.strictEqual(getCreatedCount(), createdAfterInitialRender, 'unchanged todo data should not create replacement rows');

	    const whitespaceEquivalent = todos.map(todo => ({ ...todo, content: `  ${todo.content} \n` }));
	    context.renderTodoPopover(whitespaceEquivalent);
	    assert.strictEqual(bodyAppendCount, 0, 'whitespace-equivalent todo data should not append another fragment');
	    assert.strictEqual(bodyReplaceCount, 0, 'whitespace-equivalent todo data should not replace the popover body');
	    assert.strictEqual(clearWrites, 0, 'whitespace-equivalent todo data should not clear the popover body');
	    assert.strictEqual(getCreatedCount(), createdAfterInitialRender, 'whitespace-equivalent todo data should not create replacement rows');

	    const unicodeWhitespaceEquivalent = todos.map(todo => ({ ...todo, content: `\u00a0${todo.content}\u3000` }));
	    context.renderTodoPopover(unicodeWhitespaceEquivalent);
	    assert.strictEqual(bodyAppendCount, 0, 'unicode whitespace-equivalent todo data should not append another fragment');
	    assert.strictEqual(bodyReplaceCount, 0, 'unicode whitespace-equivalent todo data should not replace the popover body');
	    assert.strictEqual(clearWrites, 0, 'unicode whitespace-equivalent todo data should not clear the popover body');
	    assert.strictEqual(getCreatedCount(), createdAfterInitialRender, 'unicode whitespace-equivalent todo data should not create replacement rows');

    const renamed = todos.map(todo => ({ ...todo }));
    renamed[1] = { ...renamed[1], content: 'Renamed todo' };
    context.renderTodoPopover(renamed);
    assert.strictEqual(bodyAppendCount, 0, 'changed todo content should avoid appendChild on the live popover body');
    assert.strictEqual(bodyReplaceCount, 1, 'changed todo content should replace once');
    assert.strictEqual(clearWrites, 0, 'changed todo content should avoid innerHTML clearing');
    assert.strictEqual(todoPopoverBody.getAttribute('role'), 'list');

    bodyAppendCount = 0;
    bodyReplaceCount = 0;
    clearWrites = 0;
	    context.renderTodoPopover([
	      { content: '   ', status: 'pending', priority: 'medium' },
	      { content: '\u00a0\u3000', status: 'pending', priority: 'medium' },
	      {},
	      null,
	    ]);
	    assert.strictEqual(todoPopoverBody.getAttribute('role'), 'note');
	    assert.strictEqual(todoPopoverBody.getAttribute('aria-label'), 'Todo list status');
	    assert.strictEqual(todoPopoverBody.children.length, 1);
    assert.strictEqual(todoPopoverBody.children[0].className, 'todo-empty');
    assert.strictEqual(todoPopoverBody.children[0].textContent, 'No todos yet. The agent can use todowrite to track a plan.');
    assert.strictEqual(bodyAppendCount, 0, 'blank todo content should avoid appendChild on the live popover body');
    assert.strictEqual(bodyReplaceCount, 1, 'blank todo content should replace once');
    assert.strictEqual(clearWrites, 0, 'blank todo content should avoid innerHTML clearing');

    bodyAppendCount = 0;
    bodyReplaceCount = 0;
    clearWrites = 0;
    context.renderTodoPopover([]);
	    assert.strictEqual(todoPopoverBody.getAttribute('role'), 'note');
	    assert.strictEqual(todoPopoverBody.getAttribute('aria-label'), 'Todo list status');
    assert.strictEqual(bodyAppendCount, 0, 'empty todo content should avoid appendChild on the live popover body');
    assert.strictEqual(bodyReplaceCount, 0, 'equivalent empty todo content should skip replacing the popover body');
    assert.strictEqual(clearWrites, 0, 'empty todo content should avoid innerHTML clearing');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

