  test('context popover skips unchanged body rebuilds', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted, getCreatedCount } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const contextPopoverBody = elements.get('contextPopoverBody');
    assert.ok(contextPopoverBody, 'expected context popover body to be created during startup');

    let innerHtml = contextPopoverBody.innerHTML || '';
    let clearWrites = 0;
    Object.defineProperty(contextPopoverBody, 'innerHTML', {
      configurable: true,
      get: () => innerHtml,
      set(value: unknown) {
        innerHtml = String(value);
        if (innerHtml === '') {
          clearWrites++;
          contextPopoverBody.children = [];
          contextPopoverBody.firstChild = null;
        }
      },
    });

    let bodyAppendCount = 0;
    let bodyReplaceCount = 0;
    const originalAppendChild = contextPopoverBody.appendChild;
    const originalReplaceChildren = contextPopoverBody.replaceChildren;
    contextPopoverBody.appendChild = (child: unknown) => {
      bodyAppendCount++;
      return originalAppendChild.call(contextPopoverBody, child);
    };
    contextPopoverBody.replaceChildren = (...children: unknown[]) => {
      bodyReplaceCount++;
      return originalReplaceChildren.call(contextPopoverBody, ...children);
    };

    const snapshot = {
      totalTokens: 12345,
      contextLimitTokens: 20000,
      outputLimitTokens: 4000,
      percent: 62,
      inputTokens: 8000,
      outputTokens: 2000,
      cacheReadTokens: 1500,
      cacheWriteTokens: 500,
    };

    assert.strictEqual(typeof context.getContextPopoverRenderKey, 'function');
    assert.strictEqual(typeof context.createCompactRenderKeyBuilder, 'function');
    assert.strictEqual(typeof context.appendCompactContextRenderKeyPart, 'function');
    assert.strictEqual(typeof context.finishCompactRenderKey, 'function');
    const expectedContextKeyBuilder = context.createCompactRenderKeyBuilder();
    context.appendCompactContextRenderKeyPart(expectedContextKeyBuilder, 12345);
    context.appendCompactContextRenderKeyPart(expectedContextKeyBuilder, 20000);
    context.appendCompactContextRenderKeyPart(expectedContextKeyBuilder, 4000);
    context.appendCompactContextRenderKeyPart(expectedContextKeyBuilder, 62);
    context.appendCompactContextRenderKeyPart(expectedContextKeyBuilder, 8000);
    context.appendCompactContextRenderKeyPart(expectedContextKeyBuilder, 2000);
    context.appendCompactContextRenderKeyPart(expectedContextKeyBuilder, 1500);
    context.appendCompactContextRenderKeyPart(expectedContextKeyBuilder, 500);
    const contextRenderKey = context.getContextPopoverRenderKey(snapshot);
    assert.strictEqual(contextRenderKey, context.finishCompactRenderKey(expectedContextKeyBuilder));
    assert.ok(contextRenderKey.length < 32, 'context popover render key should stay compact');

    assert.strictEqual(typeof context.renderContextPopover, 'function');
    context.renderContextPopover(snapshot);
    assert.strictEqual(bodyAppendCount, 0, 'expected initial context render to avoid appendChild on the live popover body');
    assert.strictEqual(bodyReplaceCount, 1, 'expected initial context render to replace once');
    assert.strictEqual(clearWrites, 0, 'expected initial context render to avoid innerHTML clearing');
    const createdAfterInitialRender = getCreatedCount();

    bodyAppendCount = 0;
    bodyReplaceCount = 0;
    clearWrites = 0;
    context.renderContextPopover({ ...snapshot });

    assert.strictEqual(bodyAppendCount, 0, 'unchanged context data should not append another fragment');
    assert.strictEqual(bodyReplaceCount, 0, 'unchanged context data should not replace the popover body');
    assert.strictEqual(clearWrites, 0, 'unchanged context data should not clear the popover body');
    assert.strictEqual(getCreatedCount(), createdAfterInitialRender, 'unchanged context data should not create replacement rows');

    context.renderContextPopover({ ...snapshot, percent: 63 });
    assert.strictEqual(bodyAppendCount, 0, 'changed context data should avoid appendChild on the live popover body');
    assert.strictEqual(bodyReplaceCount, 1, 'changed context data should replace once');
    assert.strictEqual(clearWrites, 0, 'changed context data should avoid innerHTML clearing');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

  test('context and todo popover visibility skips duplicate class and aria reads', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const contextPopover = elements.get('contextPopover');
    const todoPopover = elements.get('todoPopover');
    const contextIndicator = elements.get('contextIndicator');
    const todoIndicator = elements.get('todoIndicator');
    assert.ok(contextPopover, 'expected context popover to be created during startup');
    assert.ok(todoPopover, 'expected todo popover to be created during startup');
    assert.ok(contextIndicator, 'expected context indicator to be created during startup');
    assert.ok(todoIndicator, 'expected todo indicator to be created during startup');
    assert.strictEqual(typeof context.updateContextIndicatorState, 'function');
    assert.strictEqual(typeof context.updateTodoIndicatorState, 'function');
    assert.strictEqual(typeof context.openContextPopover, 'function');
    assert.strictEqual(typeof context.closeContextPopover, 'function');
    assert.strictEqual(typeof context.openTodoPopover, 'function');
    assert.strictEqual(typeof context.closeTodoPopover, 'function');

    contextPopover.classList.add('hidden');
    todoPopover.classList.add('hidden');
    context.updateContextIndicatorState({ totalTokens: 123, contextLimitTokens: 1000, percent: 12 });
    context.updateTodoIndicatorState([{ content: 'One', status: 'pending', priority: 'medium' }]);

	    const observeAttributeState = (element: any, attributeName: string) => {
	      let reads = 0;
	      let writes = 0;
	      const originalGetAttribute = element.getAttribute;
	      const originalSetAttribute = element.setAttribute;
	      element.getAttribute = function getAttribute(name: string) {
	        if (name === attributeName) reads++;
	        return originalGetAttribute.call(this, name);
	      };
	      element.setAttribute = (name: string, value: unknown) => {
	        if (name === attributeName) writes++;
	        return originalSetAttribute.call(element, name, value);
	      };
	      return {
	        reads: () => reads,
	        resetReads: () => { reads = 0; },
	        writes: () => writes,
	      };
	    };
	    const contextExpandedState = observeAttributeState(contextIndicator, 'aria-expanded');
	    const todoExpandedState = observeAttributeState(todoIndicator, 'aria-expanded');

	    let contextHiddenReads = 0;
	    let contextHiddenWrites = 0;
	    const originalContextContains = contextPopover.classList.contains;
	    const originalContextAdd = contextPopover.classList.add;
	    const originalContextRemove = contextPopover.classList.remove;
	    const originalContextToggle = contextPopover.classList.toggle;
	    contextPopover.classList.contains = (name: string) => {
	      if (name === 'hidden') contextHiddenReads++;
	      return originalContextContains(name);
	    };
	    contextPopover.classList.add = (...names: string[]) => {
	      if (names.includes('hidden')) contextHiddenWrites++;
	      return originalContextAdd(...names);
	    };
	    contextPopover.classList.remove = (...names: string[]) => {
	      if (names.includes('hidden')) contextHiddenWrites++;
	      return originalContextRemove(...names);
	    };
	    contextPopover.classList.toggle = (name: string, force?: boolean) => {
	      if (name === 'hidden') contextHiddenWrites++;
	      return originalContextToggle(name, force);
	    };

	    let todoHiddenReads = 0;
	    let todoHiddenWrites = 0;
	    const originalTodoContains = todoPopover.classList.contains;
	    const originalTodoAdd = todoPopover.classList.add;
	    const originalTodoRemove = todoPopover.classList.remove;
	    const originalTodoToggle = todoPopover.classList.toggle;
	    todoPopover.classList.contains = (name: string) => {
	      if (name === 'hidden') todoHiddenReads++;
	      return originalTodoContains(name);
	    };
	    todoPopover.classList.add = (...names: string[]) => {
	      if (names.includes('hidden')) todoHiddenWrites++;
	      return originalTodoAdd(...names);
	    };
	    todoPopover.classList.remove = (...names: string[]) => {
	      if (names.includes('hidden')) todoHiddenWrites++;
	      return originalTodoRemove(...names);
	    };
	    todoPopover.classList.toggle = (name: string, force?: boolean) => {
	      if (name === 'hidden') todoHiddenWrites++;
	      return originalTodoToggle(name, force);
	    };

	    context.openContextPopover();
	    assert.strictEqual(contextHiddenReads, 0, 'context popover open should apply cached visibility without hidden reads');
	    contextExpandedState.resetReads();
	    contextHiddenReads = 0;
	    context.openContextPopover();
	    assert.strictEqual(contextHiddenWrites, 1, 'repeated context popover opens should reveal once');
	    assert.strictEqual(contextHiddenReads, 0, 'repeated context popover opens should reuse cached visibility');
	    assert.strictEqual(contextExpandedState.writes(), 1, 'repeated context popover opens should mark expanded once');
	    assert.strictEqual(contextExpandedState.reads(), 0, 'repeated context popover opens should not read expanded state');
	    assert.strictEqual(contextIndicator.getAttribute('aria-expanded'), 'true');
	    context.closeContextPopover();
	    assert.strictEqual(contextHiddenReads, 0, 'context popover close should apply cached visibility without hidden reads');
	    contextExpandedState.resetReads();
	    contextHiddenReads = 0;
	    context.closeContextPopover();
	    assert.strictEqual(contextHiddenWrites, 2, 'repeated context popover closes should hide once');
	    assert.strictEqual(contextHiddenReads, 0, 'repeated context popover closes should reuse cached visibility');
	    assert.strictEqual(contextExpandedState.writes(), 2, 'repeated context popover closes should mark collapsed once');
	    assert.strictEqual(contextExpandedState.reads(), 0, 'repeated context popover closes should not read expanded state');
	    assert.strictEqual(contextIndicator.getAttribute('aria-expanded'), 'false');

	    context.openTodoPopover();
	    assert.strictEqual(todoHiddenReads, 0, 'todo popover open should apply cached visibility without hidden reads');
	    todoExpandedState.resetReads();
	    todoHiddenReads = 0;
	    context.openTodoPopover();
	    assert.strictEqual(todoHiddenWrites, 1, 'repeated todo popover opens should reveal once');
	    assert.strictEqual(todoHiddenReads, 0, 'repeated todo popover opens should reuse cached visibility');
	    assert.strictEqual(todoExpandedState.writes(), 1, 'repeated todo popover opens should mark expanded once');
	    assert.strictEqual(todoExpandedState.reads(), 0, 'repeated todo popover opens should not read expanded state');
	    assert.strictEqual(todoIndicator.getAttribute('aria-expanded'), 'true');
	    context.closeTodoPopover();
	    assert.strictEqual(todoHiddenReads, 0, 'todo popover close should apply cached visibility without hidden reads');
	    todoExpandedState.resetReads();
	    todoHiddenReads = 0;
	    context.closeTodoPopover();
	    assert.strictEqual(todoHiddenWrites, 2, 'repeated todo popover closes should hide once');
	    assert.strictEqual(todoHiddenReads, 0, 'repeated todo popover closes should reuse cached visibility');
	    assert.strictEqual(todoExpandedState.writes(), 2, 'repeated todo popover closes should mark collapsed once');
	    assert.strictEqual(todoExpandedState.reads(), 0, 'repeated todo popover closes should not read expanded state');
	    assert.strictEqual(todoIndicator.getAttribute('aria-expanded'), 'false');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

	  test('context and todo popovers restore focus after keyboard or close-button dismissal', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);
	    elements.get('outputModal')?.classList.add('hidden');
	    const timeoutCallbacks: Array<() => void> = [];
	    context.setTimeout = (callback: () => void) => {
	      timeoutCallbacks.push(callback);
	      return timeoutCallbacks.length;
	    };

		    const focusOrder: string[] = [];
		    const focusEvents: Array<{ id: string; options: unknown }> = [];
		    const installFocus = (id: string) => {
		      const element = elements.get(id);
		      assert.ok(element, `expected ${id} to be created during startup`);
		      element.focus = (options?: unknown) => {
		        context.document.activeElement = element;
		        focusOrder.push(id);
		        focusEvents.push({ id, options });
		      };
		      return element;
		    };

	    const contextIndicator = installFocus('contextIndicator');
	    const contextPopover = elements.get('contextPopover');
	    const contextPopoverClose = installFocus('contextPopoverClose');
	    const todoIndicator = installFocus('todoIndicator');
	    const todoPopover = elements.get('todoPopover');
	    const todoPopoverClose = installFocus('todoPopoverClose');
	    const input = installFocus('input');
	    assert.ok(contextPopover, 'expected context popover to be created during startup');
	    assert.ok(todoPopover, 'expected todo popover to be created during startup');
	    contextPopover.contains = (target: unknown) => target === contextPopoverClose;
	    contextIndicator.contains = (target: unknown) => target === contextIndicator;
	    todoPopover.contains = (target: unknown) => target === todoPopoverClose;
	    todoIndicator.contains = (target: unknown) => target === todoIndicator;

	    context.window.dispatchEvent({
	      type: 'message',
	      data: {
	        type: 'init',
	        messages: [],
	        mode: 'build',
	        processing: false,
	        context: { totalTokens: 256, contextLimitTokens: 4096, percent: 6 },
	        todos: [{ content: 'Review focus behavior', status: 'pending', priority: 'medium' }],
	      },
    });
	    contextPopover.classList.add('hidden');
	    todoPopover.classList.add('hidden');

	    context.document.activeElement = contextIndicator;
	    context.openContextPopover();
	    assert.strictEqual(context.document.activeElement, contextPopoverClose, 'opening the context dialog should move focus inside it');
	    assert.strictEqual(contextIndicator.getAttribute('aria-expanded'), 'true');
	    context.document.dispatchEvent({ type: 'keydown', key: 'Escape' });
	    assert.strictEqual(contextPopover.classList.contains('hidden'), true);
	    assert.strictEqual(contextIndicator.getAttribute('aria-expanded'), 'false');
	    assert.strictEqual(context.document.activeElement, contextIndicator, 'Escape should return focus to the context trigger');

	    focusOrder.length = 0;
	    context.document.activeElement = todoIndicator;
	    context.openTodoPopover();
	    assert.strictEqual(context.document.activeElement, todoPopoverClose, 'opening the todo dialog should move focus inside it');
	    assert.strictEqual(todoIndicator.getAttribute('aria-expanded'), 'true');
	    todoPopoverClose.dispatchEvent({ type: 'click', preventDefault: () => {} });
	    assert.strictEqual(todoPopover.classList.contains('hidden'), true);
	    assert.strictEqual(todoIndicator.getAttribute('aria-expanded'), 'false');
	    assert.strictEqual(context.document.activeElement, todoIndicator, 'close button should return focus to the todo trigger');
	    assert.deepStrictEqual(focusOrder, ['todoPopoverClose', 'todoIndicator']);

	    focusOrder.length = 0;
	    timeoutCallbacks.length = 0;
	    context.document.activeElement = contextIndicator;
	    context.openContextPopover();
	    const outsideSurface = context.document.createElement('div');
	    context.document.dispatchEvent({ type: 'mousedown', target: outsideSurface });
	    assert.strictEqual(contextPopover.classList.contains('hidden'), true);
	    assert.strictEqual(contextIndicator.getAttribute('aria-expanded'), 'false');
	    assert.strictEqual(timeoutCallbacks.length, 1, 'outside pointer dismissal should schedule hidden-focus cleanup');
		    timeoutCallbacks.shift()?.();
		    assert.strictEqual(context.document.activeElement, input, 'outside pointer dismissal should not leave focus inside a hidden popover');
		    assert.deepStrictEqual(focusOrder, ['contextPopoverClose', 'input']);
		    assert.deepStrictEqual(
		      focusEvents.filter(event => !(event.options && typeof event.options === 'object' && (event.options as any).preventScroll === true)),
		      [],
		      'context and todo popover focus should avoid scrolling the transcript'
		    );
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

