  test('idle context and todo popover events skip visibility scans', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    let hiddenContainsChecks = 0;
    for (const id of ['contextPopover', 'todoPopover']) {
      const popover = elements.get(id);
      assert.ok(popover, `expected ${id} to be created during startup`);
      popover.classList.add('hidden');
      const originalContains = popover.classList.contains;
      popover.classList.contains = (name: string) => {
        if (name === 'hidden') hiddenContainsChecks++;
        return originalContains(name);
      };
    }

    context.document.dispatchEvent({ type: 'mousedown', target: context.document.createElement('outside') });
    assert.strictEqual(hiddenContainsChecks, 0, 'idle pointer dismissal should not scan hidden context or todo popovers');

    const idleEscape: any = { type: 'keydown', key: 'Escape' };
    context.document.dispatchEvent(idleEscape);
    assert.strictEqual(hiddenContainsChecks, 0, 'idle Escape should not scan hidden context or todo popovers');
    assert.strictEqual(!!idleEscape.defaultPrevented, false);
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

		  test('context indicator skips duplicate text title severity and visibility writes', () => {
		    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    const contextIndicator = elements.get('contextIndicator');
	    assert.ok(contextIndicator, 'expected context indicator to be created during startup');
	    contextIndicator.classList.add('hidden');

	    let textValue = String(contextIndicator.textContent || '');
	    let textReadCount = 0;
	    let textWriteCount = 0;
	    Object.defineProperty(contextIndicator, 'textContent', {
	      configurable: true,
	      get: () => {
	        textReadCount++;
	        return textValue;
	      },
	      set: (value: unknown) => {
	        textWriteCount++;
	        textValue = String(value);
	      },
    });

	    let titleValue = '';
	    let titleReadCount = 0;
	    let titleWriteCount = 0;
	    Object.defineProperty(contextIndicator, 'title', {
	      configurable: true,
	      get: () => {
	        titleReadCount++;
	        return titleValue;
	      },
	      set: (value: unknown) => {
	        titleWriteCount++;
	        titleValue = String(value);
	      },
    });

	    const originalSetAttribute = contextIndicator.setAttribute;
	    let ariaLabelWriteCount = 0;
	    contextIndicator.setAttribute = function setAttribute(name: string, value: unknown) {
	      if (name === 'aria-label') ariaLabelWriteCount++;
	      return originalSetAttribute.call(this, name, value);
	    };

		    let hiddenClassReads = 0;
		    let hiddenClassWrites = 0;
		    const originalContains = contextIndicator.classList.contains;
		    const originalAdd = contextIndicator.classList.add;
		    const originalRemove = contextIndicator.classList.remove;
		    contextIndicator.classList.contains = (name: string) => {
		      if (name === 'hidden') hiddenClassReads++;
		      return originalContains(name);
		    };
		    contextIndicator.classList.add = (...names: string[]) => {
		      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalAdd(...names);
	    };
	    contextIndicator.classList.remove = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalRemove(...names);
	    };

		    let severityToggleWrites = 0;
		    const originalToggle = contextIndicator.classList.toggle;
		    contextIndicator.classList.toggle = (name: string, force?: boolean) => {
		      if (name === 'hidden') hiddenClassWrites++;
		      if (name === 'warn' || name === 'danger') severityToggleWrites++;
		      return originalToggle(name, force);
		    };
	    const totalWrites = () => textWriteCount + titleWriteCount + ariaLabelWriteCount + hiddenClassWrites + severityToggleWrites;

	    const normalContext = {
	      totalTokens: 120,
	      contextLimitTokens: 200,
	      percent: 60,
	      inputTokens: 80,
	      outputTokens: 40,
	    };
	    assert.strictEqual(typeof context.updateContextIndicatorState, 'function');
	    context.updateContextIndicatorState(normalContext);
	    assert.strictEqual(textValue, '120 tok 60%');
	    assert.strictEqual(titleValue, 'Context: 120 / 200 (60%)\nInput: 80  Output: 40');
	    assert.strictEqual(contextIndicator.getAttribute('aria-label'), '120 tok 60%, context usage');
	    assert.strictEqual(textWriteCount, 1, 'initial context state should write label once');
	    assert.strictEqual(titleWriteCount, 1, 'initial context state should write title once');
	    assert.strictEqual(ariaLabelWriteCount, 1, 'initial context state should write accessible name once');
	    assert.strictEqual(hiddenClassWrites, 1, 'initial context state should reveal once');
	    assert.strictEqual(hiddenClassReads, 0, 'initial context state should apply cached visibility without hidden reads');
	    assert.strictEqual(severityToggleWrites, 0, 'normal context state should not toggle severity');
		    const afterNormal = totalWrites();

		    textReadCount = 0;
		    titleReadCount = 0;
		    context.updateContextIndicatorState(normalContext);
		    assert.strictEqual(textReadCount, 0, 'unchanged direct context state should skip indicator text reads');
		    assert.strictEqual(titleReadCount, 0, 'unchanged direct context state should skip indicator title reads');
		    assert.strictEqual(hiddenClassReads, 0, 'unchanged direct context state should not reread indicator visibility');
		    assert.strictEqual(totalWrites(), afterNormal, 'unchanged context state should not rewrite indicator state');
		    textReadCount = 0;
		    titleReadCount = 0;
	    context.window.dispatchEvent({ type: 'message', data: { type: 'context', context: normalContext } });
	    assert.strictEqual(textReadCount, 0, 'duplicate context message should skip indicator text reads');
	    assert.strictEqual(titleReadCount, 0, 'duplicate context message should skip indicator title reads');
	    assert.strictEqual(hiddenClassReads, 0, 'duplicate context message should not reread indicator visibility');
	    assert.strictEqual(totalWrites(), afterNormal, 'duplicate context message should not rewrite indicator state');

	    context.updateContextIndicatorState({
		      totalTokens: 1700,
		      contextLimitTokens: 2000,
		      percent: 85,
		      inputTokens: 1200,
		      outputTokens: 500,
		    });
		    assert.strictEqual(textValue, '1.7k tok 85%');
		    assert.strictEqual(contextIndicator.getAttribute('aria-label'), '1.7k tok 85%, context usage');
	    assert.strictEqual(textWriteCount, 2, 'warning context state should update label once');
	    assert.strictEqual(titleWriteCount, 2, 'warning context state should update title once');
	    assert.strictEqual(ariaLabelWriteCount, 2, 'warning context state should update accessible name once');
	    assert.strictEqual(hiddenClassWrites, 1, 'warning context state should keep visibility unchanged');
	    assert.strictEqual(hiddenClassReads, 0, 'warning context state should not reread visible indicator state');
	    assert.strictEqual(severityToggleWrites, 1, 'warning context state should set warn once');
	    const afterWarn = totalWrites();

		    context.updateContextIndicatorState({
		      totalTokens: 1_000_000,
		      contextLimitTokens: 2_000_000,
		      percent: 96,
		      inputTokens: 800_000,
		      outputTokens: 200_000,
	    });
		    assert.strictEqual(textValue, '1m tok 96%');
		    assert.strictEqual(contextIndicator.getAttribute('aria-label'), '1m tok 96%, context usage');
	    assert.strictEqual(textWriteCount, 3, 'danger context state should update label once');
	    assert.strictEqual(titleWriteCount, 3, 'danger context state should update title once');
	    assert.strictEqual(ariaLabelWriteCount, 3, 'danger context state should update accessible name once');
	    assert.strictEqual(hiddenClassWrites, 1, 'danger context state should keep visibility unchanged');
	    assert.strictEqual(hiddenClassReads, 0, 'danger context state should not reread visible indicator state');
	    assert.strictEqual(severityToggleWrites, 3, 'danger context state should swap warn for danger once');
	    const afterDanger = totalWrites();

		    context.updateContextIndicatorState({
		      totalTokens: 1_000_000,
		      contextLimitTokens: 2_000_000,
		      percent: 96,
		      inputTokens: 800_000,
		      outputTokens: 200_000,
	    });
	    assert.strictEqual(hiddenClassReads, 0, 'unchanged danger context state should not reread indicator visibility');
	    assert.strictEqual(totalWrites(), afterDanger, 'unchanged danger context state should not rewrite indicator state');
		    assert.ok(afterWarn < afterDanger, 'expected danger transition to be observed');
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

		  test('context messages reuse guard render key for changed indicator updates', () => {
		    const controller = createStandaloneChatController();
		    const webview = {
		      cspSource: 'test-csp',
		      asWebviewUri: (uri: unknown) => uri,
		    } as unknown as vscode.Webview;

		    const html = controller.webviewApi.getHtml(webview);
		    const scripts = extractOrderedScriptSources(html);
		    const { context, elements, posted } = createMockBrowserContext();
		    runScriptsInMockBrowser(scripts, context);

		    const contextIndicator = elements.get('contextIndicator');
		    assert.ok(contextIndicator, 'expected context indicator to be created during startup');
		    assert.strictEqual(typeof context.updateContextIndicatorState, 'function');
		    context.updateContextIndicatorState({
		      totalTokens: 120,
		      contextLimitTokens: 200,
		      outputLimitTokens: 100,
		      percent: 60,
		      inputTokens: 80,
		      outputTokens: 40,
		      cacheReadTokens: 5,
		      cacheWriteTokens: 3,
		    });

		    const changedContextValues: Record<string, number> = {
		      totalTokens: 1500,
		      contextLimitTokens: 2000,
		      outputLimitTokens: 1000,
		      percent: 75,
		      inputTokens: 1000,
		      outputTokens: 500,
		      cacheReadTokens: 20,
		      cacheWriteTokens: 10,
		    };
		    let contextFieldReads = 0;
		    const trackedContext: any = {};
		    for (const field of Object.keys(changedContextValues)) {
		      Object.defineProperty(trackedContext, field, {
		        configurable: true,
		        get: () => {
		          contextFieldReads++;
		          return changedContextValues[field];
		        },
		      });
		    }

		    context.window.dispatchEvent({ type: 'message', data: { type: 'context', context: trackedContext } });
		    assert.ok(
		      contextFieldReads <= 30,
		      'changed context messages should reuse the guard render key for the indicator update'
		    );
		    assert.strictEqual(contextIndicator.textContent, '1.5k tok 75%');
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

