  test('webview motion respects reduced-motion preferences', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);

    assert.match(html, /\.messages\s*\{[\s\S]*?scroll-behavior: auto;/);
    const messagesCssStart = html.indexOf('.messages {');
    const messagesCssEnd = html.indexOf('.messages:focus-visible', messagesCssStart);
    assert.ok(messagesCssStart >= 0 && messagesCssEnd > messagesCssStart, 'expected transcript CSS block');
    assert.doesNotMatch(
      html.slice(messagesCssStart, messagesCssEnd),
      /scroll-behavior:\s*smooth/,
      'programmatic transcript following must not animate behind streaming content'
    );
    assert.match(html, /@media \(prefers-reduced-motion: reduce\)/);
    assert.match(html, /animation-duration: 0\.001ms !important;/);
    assert.match(html, /animation-iteration-count: 1 !important;/);
    assert.match(html, /scroll-behavior: auto !important;/);
    assert.match(html, /transition-duration: 0\.001ms !important;/);
    const reducedMotionCss = html.slice(html.indexOf('@media (prefers-reduced-motion: reduce)'));
    for (const selector of [
      '.turn',
      '.step',
      '.message',
      '.operation-card',
      '.step.running .step-dot',
      '.turn-spinner',
      '.operation-banner-spinner',
    ]) {
      assert.ok(reducedMotionCss.includes(selector), `expected reduced-motion CSS to include ${selector}`);
    }
    assert.match(reducedMotionCss, /animation: none !important;/);
	    assert.match(reducedMotionCss, /opacity: 1;[\s\S]*?transform: none;/);
	    assert.match(reducedMotionCss, /\.queue-item:hover:not\(:disabled\)\s*\{[\s\S]*?transform: none;/);
	  });

