  test('stream token queues preserve falsy token values', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const timers: Array<() => void> = [];
    context.setTimeout = (callback: () => void) => {
      timers.push(callback);
      return timers.length;
    };
    context.clearTimeout = () => {};
    const runScheduledTimers = (message: string) => {
      const scheduled = timers.splice(0);
      assert.ok(scheduled.length > 0, message);
      for (const timer of scheduled) timer();
    };

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [
          { id: 'assistant-falsy-stream', role: 'assistant', content: '' },
          { id: 'thought-falsy-stream', role: 'thought', content: '' },
        ],
      },
    });

    const messages = elements.get('messages');
    assert.ok(messages, 'expected messages element');
    const assistantEl = messages.children.find((child: any) => child?.dataset?.id === 'assistant-falsy-stream');
    const thoughtEl = messages.children.find((child: any) => child?.dataset?.id === 'thought-falsy-stream');
    assert.ok(assistantEl, 'expected assistant message element');
    assert.ok(thoughtEl, 'expected thought message element');
    const assistantBubble = findMockChildByClass(assistantEl, 'message-bubble');
    const assistantContent = findMockChildByClass(assistantBubble, 'message-content');
    const thoughtContent = findMockChildByClass(thoughtEl, 'message-content');
    const thinkingDetails = findMockChildByClass(thoughtContent, 'thinking-details');
    const thinkingText = findMockChildByClass(thinkingDetails, 'thinking-text');
    assert.ok(assistantContent, 'expected assistant content element');
    assert.ok(thinkingText, 'expected thinking text element');
    const originalAssistantClassContains = assistantEl.classList.contains;
    assistantEl.classList.contains = (name: string) => name === 'assistant' || originalAssistantClassContains(name);
    assistantEl.querySelector = (selector: string) => selector === '.message-content' ? assistantContent : null;
    thoughtEl.querySelector = (selector: string) => selector === '.thinking-text' ? thinkingText : null;
    timers.length = 0;

    context.window.dispatchEvent({
      type: 'message',
      data: { type: 'token', messageId: 'assistant-falsy-stream', token: 0 },
    });
    runScheduledTimers('expected assistant token render timer');
	    assert.strictEqual(context.getAssistantMarkdownRaw(assistantContent), '0');
	    assert.strictEqual(assistantContent.dataset.raw, undefined);
    timers.length = 0;

    context.window.dispatchEvent({
      type: 'message',
      data: { type: 'token', messageId: 'thought-falsy-stream', token: false },
    });
    runScheduledTimers('expected thought token render timer');
    const thinkingTextNode = thinkingText.children.find((child: any) => child?.nodeType === 3);
    assert.strictEqual(thinkingTextNode?.textContent, 'false');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

	  test('empty assistant update discards pending stream tokens', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    let nextTimerId = 1;
    const timers = new Map<number, { callback: () => void; cleared: boolean }>();
    context.setTimeout = (callback: () => void) => {
      const id = nextTimerId++;
      timers.set(id, { callback, cleared: false });
      return id;
    };
    context.clearTimeout = (id: number) => {
      const timer = timers.get(id);
      if (timer) timer.cleared = true;
    };

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [{ id: 'assistant-reset-stream', role: 'assistant', content: '' }],
      },
    });

    const messages = elements.get('messages');
    assert.ok(messages, 'expected messages element');
    const assistantEl = messages.children.find((child: any) => child?.dataset?.id === 'assistant-reset-stream');
    assert.ok(assistantEl, 'expected assistant message element');

    let replacement: any = null;
    assistantEl.replaceWith = (next: any) => {
      const index = messages.children.indexOf(assistantEl);
      if (index >= 0) {
        messages.children[index] = next;
        next.parentNode = messages;
      }
      replacement = next;
    };

    context.window.dispatchEvent({
      type: 'message',
      data: { type: 'token', messageId: 'assistant-reset-stream', token: 'stale token' },
    });
    assert.strictEqual(timers.size, 1, 'expected queued assistant stream render timer');

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'updateMessage',
        message: { id: 'assistant-reset-stream', role: 'assistant', content: '  \n\t  ' },
      },
    });

    assert.strictEqual(timers.get(1)?.cleared, true, 'empty assistant update should clear the pending stream timer');
    for (const timer of timers.values()) {
      timer.callback();
    }

    assert.ok(replacement, 'expected assistant message replacement');
    const bubble = findMockChildByClass(replacement, 'message-bubble');
    const content = findMockChildByClass(bubble, 'message-content');
    assert.ok(content, 'expected replacement assistant content');
	    assert.strictEqual(context.getAssistantMarkdownRaw(content), '  \n\t  ');
	    assert.strictEqual(content.dataset.raw, undefined);
	    assert.doesNotMatch(String(content.innerHTML || ''), /stale token/);
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

