	  test('duplicate assistant updates skip DOM replacement and layout reads', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted, getCreatedCount } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const assistantMessage = { id: 'assistant-same', role: 'assistant', content: 'Hello **world**' };
    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [assistantMessage],
      },
    });

	    const messages = elements.get('messages');
	    assert.ok(messages, 'expected messages element');
	    const assistantEl = messages.children.find((child: any) => child?.dataset?.id === 'assistant-same');
	    assert.ok(assistantEl, 'expected assistant message element');
	    const assistantRenderKey = context.getMessageRenderKey(assistantMessage);
	    assert.strictEqual(assistantEl.dataset.messageRenderKey, context.getMessageRenderDatasetKey(assistantRenderKey));
	    assert.ok(!assistantEl.dataset.messageRenderKey.includes(String(assistantMessage.content)));

    let replaceCount = 0;
    assistantEl.replaceWith = (next: any) => {
      const index = messages.children.indexOf(assistantEl);
      if (index >= 0) {
        messages.children[index] = next;
        next.parentNode = messages;
      }
      replaceCount++;
    };

    let linkifyCount = 0;
    context.scheduleFileLinkifyIfNeeded = () => {
      linkifyCount++;
    };

    let scrollHeightReads = 0;
    let clientHeightReads = 0;
    Object.defineProperty(messages, 'scrollHeight', {
      configurable: true,
      get() {
        scrollHeightReads++;
        return 1000;
      },
    });
    Object.defineProperty(messages, 'clientHeight', {
      configurable: true,
      get() {
        clientHeightReads++;
        return 100;
      },
    });
    messages.scrollTop = 0;

    const createdBeforeDuplicate = getCreatedCount();
    context.window.dispatchEvent({
      type: 'message',
      data: { type: 'updateMessage', message: assistantMessage },
    });

    assert.strictEqual(getCreatedCount(), createdBeforeDuplicate, 'duplicate assistant update should not allocate DOM nodes');
    assert.strictEqual(replaceCount, 0, 'duplicate assistant update should not replace the rendered message');
    assert.strictEqual(linkifyCount, 0, 'duplicate assistant update should not rescan file links');
    assert.strictEqual(scrollHeightReads, 0, 'duplicate assistant update should not read transcript scrollHeight');
    assert.strictEqual(clientHeightReads, 0, 'duplicate assistant update should not read transcript clientHeight');

    const changedMessage = { ...assistantMessage, content: 'Hello again' };
    context.window.dispatchEvent({
      type: 'message',
      data: { type: 'updateMessage', message: changedMessage },
    });

    assert.ok(getCreatedCount() > createdBeforeDuplicate, 'changed assistant update should still render replacement DOM');
    assert.strictEqual(replaceCount, 1, 'changed assistant update should replace the rendered message once');
	    assert.strictEqual(linkifyCount, 1, 'changed assistant update should rescan file links once');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

