		  test('stream token flush uses cached message targets without re-querying rendered messages', () => {
		    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const timers: Array<() => void> = [];
    context.setTimeout = (callback: () => void) => {
      timers.push(callback);
      return timers.length;
    };
    context.clearTimeout = () => {};
    const runScheduledTimers = () => {
      const scheduled = timers.splice(0);
      assert.ok(scheduled.length >= 2, 'expected assistant and thought stream render timers');
      for (const timer of scheduled) timer();
    };

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [
          { id: 'assistant-cached-stream', role: 'assistant', content: '' },
          { id: 'thought-cached-stream', role: 'thought', content: '' },
        ],
      },
    });

    const messages = elements.get('messages');
    assert.ok(messages, 'expected messages element');
    const assistantEl = messages.children.find((child: any) => child?.dataset?.id === 'assistant-cached-stream');
    const thoughtEl = messages.children.find((child: any) => child?.dataset?.id === 'thought-cached-stream');
    assert.ok(assistantEl, 'expected assistant message element');
    assert.ok(thoughtEl, 'expected thought message element');
    const assistantBubble = findMockChildByClass(assistantEl, 'message-bubble');
    const assistantContent = findMockChildByClass(assistantBubble, 'message-content');
    const thoughtContent = findMockChildByClass(thoughtEl, 'message-content');
    const thinkingDetails = findMockChildByClass(thoughtContent, 'thinking-details');
    const thinkingText = findMockChildByClass(thinkingDetails, 'thinking-text');
    assert.ok(assistantContent, 'expected cached assistant content element');
    assert.ok(thinkingText, 'expected cached thinking text element');
    const originalAssistantClassContains = assistantEl.classList.contains;
    assistantEl.classList.contains = (name: string) => name === 'assistant' || originalAssistantClassContains(name);
    assistantEl.querySelector = () => {
      throw new Error('assistant stream flush should use the cached content element');
    };
    thoughtEl.querySelector = () => {
      throw new Error('thought stream flush should use the cached thinking element');
    };
    timers.length = 0;

    context.window.dispatchEvent({
      type: 'message',
      data: { type: 'token', messageId: 'assistant-cached-stream', token: 'hello' },
    });
    context.window.dispatchEvent({
      type: 'message',
      data: { type: 'token', messageId: 'thought-cached-stream', token: 'thinking' },
    });
    runScheduledTimers();

	    assert.strictEqual(context.getAssistantMarkdownRaw(assistantContent), 'hello');
	    assert.strictEqual(assistantContent.dataset.raw, undefined);
    const thinkingTextNode = thinkingText.children.find((child: any) => child?.nodeType === 3);
    assert.strictEqual(thinkingTextNode?.textContent, 'thinking');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

				  test('operation banner skips duplicate live-region text writes', () => {
		    const controller = createStandaloneChatController();
		    const webview = {
		      cspSource: 'test-csp',
		      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    let now = 10000;
	    const RealDate = Date;
	    const MockDate: any = function MockDate(this: unknown, ...args: unknown[]) {
	      return args.length ? new (RealDate as any)(...args) : new RealDate(now);
	    };
	    MockDate.now = () => now;
	    MockDate.parse = RealDate.parse;
	    MockDate.UTC = RealDate.UTC;
	    MockDate.prototype = RealDate.prototype;
	    context.Date = MockDate;
	    runScriptsInMockBrowser(scripts, context);

	    assert.strictEqual(typeof context.startOperation, 'function');
	    assert.strictEqual(typeof context.updateOperationBanner, 'function');
	    context.startOperation({ label: 'Generating answer', status: 'running', startedAt: 0 });

	    const operationBanner = elements.get('operationBanner');
	    const operationLabel = elements.get('operationLabel');
	    const operationElapsed = elements.get('operationElapsed');
	    const operationSpinner = elements.get('operationSpinner');
	    assert.ok(operationBanner, 'expected operation banner');
	    assert.ok(operationSpinner, 'expected operation spinner');
	    assert.strictEqual(operationLabel.textContent, 'Generating answer');
	    assert.strictEqual(operationElapsed.textContent, '10s');

			    let bannerClassWriteCount = 0;
			    let bannerClassReadCount = 0;
			    const originalBannerContains = operationBanner.classList.contains;
			    const originalBannerAdd = operationBanner.classList.add;
			    const originalBannerRemove = operationBanner.classList.remove;
			    const originalBannerToggle = operationBanner.classList.toggle;
			    operationBanner.classList.contains = (name: string) => {
			      if (name === 'hidden') bannerClassReadCount++;
			      return originalBannerContains(name);
			    };
			    operationBanner.classList.add = (...names: string[]) => {
			      if (names.includes('hidden')) bannerClassWriteCount++;
			      return originalBannerAdd(...names);
			    };
			    operationBanner.classList.remove = (...names: string[]) => {
			      if (names.includes('hidden')) bannerClassWriteCount++;
			      return originalBannerRemove(...names);
			    };
			    operationBanner.classList.toggle = (name: string, force?: boolean) => {
			      if (name === 'hidden') bannerClassWriteCount++;
			      return originalBannerToggle(name, force);
			    };

	    let labelValue = String(operationLabel.textContent || '');
	    let labelReadCount = 0;
	    let labelWriteCount = 0;
	    Object.defineProperty(operationLabel, 'textContent', {
	      configurable: true,
	      get: () => {
	        labelReadCount++;
	        return labelValue;
	      },
	      set: (value: unknown) => {
	        labelWriteCount++;
	        labelValue = String(value);
	      },
    });

	    let elapsedValue = String(operationElapsed.textContent || '');
	    let elapsedWriteCount = 0;
	    Object.defineProperty(operationElapsed, 'textContent', {
	      configurable: true,
	      get: () => elapsedValue,
	      set: (value: unknown) => {
	        elapsedWriteCount++;
	        elapsedValue = String(value);
	      },
    });

	    let spinnerDisplayValue = operationSpinner.style.display || '';
	    let spinnerDisplayWriteCount = 0;
	    Object.defineProperty(operationSpinner.style, 'display', {
	      configurable: true,
	      get: () => spinnerDisplayValue,
	      set: (value: unknown) => {
	        spinnerDisplayWriteCount++;
	        spinnerDisplayValue = String(value);
	      },
    });

		    context.updateOperationBanner();
		    assert.strictEqual(bannerClassReadCount, 0, 'unchanged operation banner visibility should not read classes');
		    assert.strictEqual(bannerClassWriteCount, 0, 'unchanged operation banner visibility should not rewrite classes');
		    assert.strictEqual(labelReadCount, 0, 'unchanged operation banner should not read label text');
	    assert.strictEqual(labelWriteCount, 0, 'unchanged operation label should not rewrite text');
	    assert.strictEqual(elapsedWriteCount, 0, 'unchanged elapsed text should not rewrite text');
	    assert.strictEqual(spinnerDisplayWriteCount, 0, 'unchanged running spinner should not rewrite display');

	    now = 11000;
		    context.updateOperationBanner();
		    assert.strictEqual(bannerClassReadCount, 0, 'elapsed timer ticks should not read operation banner visibility');
		    assert.strictEqual(bannerClassWriteCount, 0, 'elapsed timer ticks should not rewrite operation banner visibility');
		    assert.strictEqual(labelReadCount, 0, 'elapsed timer ticks should not read the label');
	    assert.strictEqual(labelWriteCount, 0, 'elapsed timer ticks should not rewrite the label');
	    assert.strictEqual(elapsedWriteCount, 1, 'elapsed timer tick should update only visible elapsed text');
	    assert.strictEqual(elapsedValue, '11s');
	    assert.strictEqual(spinnerDisplayWriteCount, 0, 'elapsed timer ticks should not rewrite spinner display');
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

	  test('duplicate operation updates skip banner refresh work', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    let now = 10000;
	    const RealDate = Date;
	    const MockDate: any = function MockDate(this: unknown, ...args: unknown[]) {
	      return args.length ? new (RealDate as any)(...args) : new RealDate(now);
	    };
	    MockDate.now = () => now;
	    MockDate.parse = RealDate.parse;
	    MockDate.UTC = RealDate.UTC;
	    MockDate.prototype = RealDate.prototype;
	    context.Date = MockDate;
	    let nextIntervalId = 0;
	    let intervalSetCount = 0;
	    let intervalClearCount = 0;
	    context.setInterval = (_callback: () => void, _delay?: number) => {
	      intervalSetCount++;
	      return ++nextIntervalId;
	    };
	    context.clearInterval = (_id: number) => {
	      intervalClearCount++;
	    };
	    runScriptsInMockBrowser(scripts, context);

	    const operation = { id: 'op-1', label: 'Generating answer', status: 'running', startedAt: 9000 };
	    context.startOperation(operation);
	    const intervalSetCountAfterStart = intervalSetCount;
	    const intervalClearCountAfterStart = intervalClearCount;

	    const operationLabel = elements.get('operationLabel');
	    const operationElapsed = elements.get('operationElapsed');
	    assert.ok(operationLabel, 'expected operation label');
	    assert.ok(operationElapsed, 'expected operation elapsed text');
	    assert.strictEqual(operationLabel.textContent, 'Generating answer');
	    assert.strictEqual(operationElapsed.textContent, '1s');

	    let labelValue = String(operationLabel.textContent || '');
	    let labelWriteCount = 0;
	    Object.defineProperty(operationLabel, 'textContent', {
	      configurable: true,
	      get: () => labelValue,
	      set: (value: unknown) => {
	        labelWriteCount++;
	        labelValue = String(value);
	      },
	    });

	    let elapsedValue = String(operationElapsed.textContent || '');
	    let elapsedWriteCount = 0;
	    Object.defineProperty(operationElapsed, 'textContent', {
	      configurable: true,
	      get: () => elapsedValue,
	      set: (value: unknown) => {
	        elapsedWriteCount++;
	        elapsedValue = String(value);
	      },
	    });

	    now = 12000;
	    context.window.dispatchEvent({ type: 'message', data: { type: 'operationStart', operation } });
	    assert.strictEqual(labelWriteCount, 0, 'duplicate operation start should not rewrite label text');
	    assert.strictEqual(elapsedWriteCount, 0, 'duplicate operation start should not refresh elapsed text');
	    assert.strictEqual(intervalSetCount, intervalSetCountAfterStart, 'duplicate operation start should not restart elapsed interval');
	    assert.strictEqual(intervalClearCount, intervalClearCountAfterStart, 'duplicate operation start should not clear elapsed interval');
	    assert.strictEqual(elapsedValue, '1s');

	    context.window.dispatchEvent({ type: 'message', data: { type: 'operationUpdate', operation } });
	    assert.strictEqual(labelWriteCount, 0, 'duplicate operation update should not rewrite label text');
	    assert.strictEqual(elapsedWriteCount, 0, 'duplicate operation update should not refresh elapsed text');
	    assert.strictEqual(elapsedValue, '1s');

	    context.window.dispatchEvent({
	      type: 'message',
	      data: {
	        type: 'operationUpdate',
	        operation: { ...operation, label: 'Applying edits' },
	      },
	    });
	    assert.strictEqual(labelWriteCount, 1, 'changed operation update should refresh label once');
	    assert.strictEqual(labelValue, 'Applying edits');
	    assert.strictEqual(elapsedWriteCount, 1, 'changed operation update should refresh elapsed once');
	    assert.strictEqual(elapsedValue, '3s');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

		  test('operation end hide timer cannot clear a newer operation', () => {
		    const controller = createStandaloneChatController();
		    const webview = {
		      cspSource: 'test-csp',
		      asWebviewUri: (uri: unknown) => uri,
		    } as unknown as vscode.Webview;

		    const html = controller.webviewApi.getHtml(webview);
		    const scripts = extractOrderedScriptSources(html);
		    const { context, elements, posted } = createMockBrowserContext();
		    let nextTimerId = 0;
		    const timers = new Map<number, { callback: () => void; delay: number; cleared: boolean }>();
		    context.setTimeout = (callback: () => void, delay?: number) => {
		      const id = ++nextTimerId;
		      timers.set(id, { callback, delay: Number(delay || 0), cleared: false });
		      return id;
		    };
		    context.clearTimeout = (id: number) => {
		      const timer = timers.get(id);
		      if (timer) timer.cleared = true;
		    };
		    runScriptsInMockBrowser(scripts, context);

		    assert.strictEqual(typeof context.startOperation, 'function');
		    assert.strictEqual(typeof context.endOperation, 'function');
		    context.startOperation({ id: 'operation-1', label: 'Generating answer', status: 'running', startedAt: 1000 });
		    context.endOperation('done', 'Generated answer');

		    const firstHideTimerId = nextTimerId;
		    assert.ok(firstHideTimerId > 0, 'expected operation end to schedule a delayed hide timer');
		    assert.strictEqual(timers.get(firstHideTimerId)?.delay, 1200);
		    context.endOperation('done', 'Generated answer');
		    assert.strictEqual(nextTimerId, firstHideTimerId, 'duplicate operation end should not schedule another hide timer');
		    assert.strictEqual(timers.get(firstHideTimerId)?.cleared, false, 'duplicate operation end should not clear the active hide timer');

		    context.startOperation({ id: 'operation-2', label: 'Applying edits', status: 'running', startedAt: 2000 });
		    assert.strictEqual(timers.get(firstHideTimerId)?.cleared, true, 'new operation should cancel the old hide timer');

		    const operationBanner = elements.get('operationBanner');
		    const operationLabel = elements.get('operationLabel');
		    assert.ok(operationBanner, 'expected operation banner');
		    assert.ok(operationLabel, 'expected operation label');
		    assert.strictEqual(operationLabel.textContent, 'Applying edits');

		    timers.get(firstHideTimerId)?.callback();
		    assert.strictEqual(operationBanner.classList.contains('hidden'), false, 'stale hide timer should not hide the newer operation');
		    assert.strictEqual(operationLabel.textContent, 'Applying edits', 'stale hide timer should not replace newer operation label');

		    context.endOperation('done', 'Applied edits');
		    const secondHideTimerId = nextTimerId;
		    assert.ok(secondHideTimerId > firstHideTimerId, 'expected newer operation end to own a fresh hide timer');
		    timers.get(secondHideTimerId)?.callback();
		    assert.strictEqual(operationBanner.classList.contains('hidden'), true, 'current hide timer should hide the completed operation');
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

