			  test('revert bar skips duplicate live-region and button writes', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    const revertState = {
	      active: true,
	      revertedMessages: 2,
	      files: [
	        { path: 'src/a.ts', additions: 1, deletions: 0 },
	        { path: 'src/b.ts', additions: 0, deletions: 2 },
	      ],
		    };
		    assert.strictEqual(typeof context.getRevertBarRenderKey, 'function');
		    assert.strictEqual(typeof context.createCompactRenderStateKeyBuilder, 'function');
		    assert.strictEqual(typeof context.appendCompactRenderStateKeyPart, 'function');
		    assert.strictEqual(typeof context.finishCompactRenderStateKey, 'function');
		    assert.strictEqual(context.getRevertBarRenderKey({ active: false }), 'inactive');
		    const longRevertPath = 'src/revert-key-secret-' + 'x'.repeat(140) + '.ts';
		    const longPathRevertKey = context.getRevertBarRenderKey({
		      active: true,
		      revertedMessages: 1,
		      files: [{ path: longRevertPath, additions: 1, deletions: 0 }],
		    });
		    const expectedRevertKeyBuilder = context.createCompactRenderStateKeyBuilder();
		    context.appendCompactRenderStateKeyPart(expectedRevertKeyBuilder, 1);
		    context.appendCompactRenderStateKeyPart(expectedRevertKeyBuilder, 'Undid 1 message and reverted 1 file.');
		    context.appendCompactRenderStateKeyPart(expectedRevertKeyBuilder, 1);
		    context.appendCompactRenderStateKeyPart(expectedRevertKeyBuilder, longRevertPath);
		    context.appendCompactRenderStateKeyPart(expectedRevertKeyBuilder, 1);
		    context.appendCompactRenderStateKeyPart(expectedRevertKeyBuilder, 0);
		    assert.strictEqual(longPathRevertKey, context.finishCompactRenderStateKey(expectedRevertKeyBuilder));
		    assert.ok(longPathRevertKey.length < 32, 'revert bar render key should stay compact');
	    assert.ok(!longPathRevertKey.includes('revert-key-secret'), 'revert bar render key should not retain file paths');
	    context.window.dispatchEvent({
	      type: 'message',
	      data: {
	        type: 'init',
	        messages: [],
	        mode: 'build',
	        processing: false,
	        canUndo: true,
	        canRedo: true,
	        revertState,
	      },
    });

	    const revertBar = elements.get('revertBar');
	    const revertStatus = elements.get('revertStatus');
	    const revertSummary = elements.get('revertSummary');
	    const revertFilesList = elements.get('revertFilesList');
	    const revertButtons = [
	      elements.get('revertRedo'),
	      elements.get('revertRedoAll'),
	      elements.get('revertDiff'),
	      elements.get('revertDiscard'),
	      elements.get('revertDiscardCancel'),
	      elements.get('revertDiscardConfirmRun'),
	    ];
	    assert.ok(revertBar, 'expected revert bar');
	    assert.ok(revertStatus, 'expected revert status');
	    assert.ok(revertFilesList, 'expected reverted files list');
	    assert.strictEqual(revertBar.classList.contains('hidden'), false);
	    assert.strictEqual(revertStatus.textContent, 'Undid 2 messages and reverted 2 files.');
	    assert.strictEqual(revertSummary.textContent, 'Undid 2 messages and reverted 2 files.');
	    assert.strictEqual(revertFilesList.children.length, 2);

		    let barClassWriteCount = 0;
		    const originalBarAdd = revertBar.classList.add;
		    const originalBarRemove = revertBar.classList.remove;
		    const originalBarToggle = revertBar.classList.toggle;
		    revertBar.classList.add = (...names: string[]) => {
		      barClassWriteCount++;
		      return originalBarAdd(...names);
		    };
		    revertBar.classList.remove = (...names: string[]) => {
		      barClassWriteCount++;
		      return originalBarRemove(...names);
		    };
		    revertBar.classList.toggle = (name: string, force?: boolean) => {
		      barClassWriteCount++;
		      return originalBarToggle(name, force);
		    };

	    let summaryValue = String(revertSummary.textContent || '');
	    let summaryWriteCount = 0;
	    Object.defineProperty(revertSummary, 'textContent', {
	      configurable: true,
	      get: () => summaryValue,
	      set: (value: unknown) => {
	        summaryWriteCount++;
	        summaryValue = String(value);
	      },
    });
	    let statusValue = String(revertStatus.textContent || '');
	    let statusWriteCount = 0;
	    Object.defineProperty(revertStatus, 'textContent', {
	      configurable: true,
	      get: () => statusValue,
	      set: (value: unknown) => {
	        statusWriteCount++;
	        statusValue = String(value);
	      },
    });

	    let listClearCount = 0;
	    Object.defineProperty(revertFilesList, 'innerHTML', {
	      configurable: true,
	      get: () => '',
	      set: (value: unknown) => {
	        listClearCount++;
	        if (String(value) === '') {
	          revertFilesList.children = [];
	          revertFilesList.firstChild = null;
	        }
	      },
    });
    let listAppendCount = 0;
    let listReplaceCount = 0;
    const originalListAppend = revertFilesList.appendChild;
    const originalListReplace = revertFilesList.replaceChildren;
    revertFilesList.appendChild = function appendChild(child: any) {
      listAppendCount++;
      return originalListAppend.call(this, child);
    };
    revertFilesList.replaceChildren = function replaceChildren(...children: unknown[]) {
      listReplaceCount++;
      return originalListReplace.call(this, ...children);
    };

	    const buttonReadCounts: number[] = [];
	    const buttonWriteCounts: number[] = [];
	    revertButtons.forEach((button, index) => {
	      assert.ok(button, 'expected revert button ' + index);
	      let disabledValue = Boolean(button.disabled);
	      buttonReadCounts[index] = 0;
	      buttonWriteCounts[index] = 0;
	      Object.defineProperty(button, 'disabled', {
	        configurable: true,
	        get: () => {
	          buttonReadCounts[index]++;
	          return disabledValue;
	        },
	        set: (value: unknown) => {
	          buttonWriteCounts[index]++;
	          disabledValue = Boolean(value);
	        },
	      });
    });
    const totalButtonReads = () => buttonReadCounts.reduce((sum, count) => sum + count, 0);
	    const totalButtonWrites = () => buttonWriteCounts.reduce((sum, count) => sum + count, 0);

	    assert.strictEqual(typeof context.updateRevertBar, 'function');
	    assert.strictEqual(typeof context.syncInputState, 'function');
	    buttonReadCounts.fill(0);
		    context.updateRevertBar(revertState);
		    context.syncInputState();
		    assert.strictEqual(barClassWriteCount, 0, 'unchanged revert visibility should not rewrite classes');
		    assert.strictEqual(statusWriteCount, 0, 'unchanged revert summary should not rewrite status text');
		    assert.strictEqual(summaryWriteCount, 0, 'unchanged revert summary should not rewrite text');
	    assert.strictEqual(listClearCount, 0, 'unchanged revert files should not clear the list');
	    assert.strictEqual(listAppendCount, 0, 'unchanged revert files should not append rows');
	    assert.strictEqual(listReplaceCount, 0, 'unchanged revert files should not replace rows');
	    assert.strictEqual(totalButtonReads(), 0, 'unchanged direct revert sync should skip revert button reads');
	    assert.deepStrictEqual(buttonWriteCounts, [0, 0, 0, 0, 0, 0], 'unchanged revert buttons should not rewrite disabled');

	    buttonReadCounts.fill(0);
	    context.window.dispatchEvent({ type: 'message', data: { type: 'revertState', canUndo: true, canRedo: true, revertState } });
	    assert.strictEqual(totalButtonReads(), 0, 'duplicate idle revert state should skip revert button reads');
	    assert.strictEqual(totalButtonWrites(), 0, 'duplicate idle revert state should not rewrite buttons');

	    buttonReadCounts.fill(0);
	    context.window.dispatchEvent({ type: 'message', data: { type: 'revertState', canUndo: true, canRedo: false, revertState } });
	    assert.ok(totalButtonReads() > 0, 'same rendered revert state with changed canRedo should sync controls');
	    assert.ok(totalButtonWrites() > 0, 'changed canRedo should rewrite affected revert controls');
	    context.window.dispatchEvent({ type: 'message', data: { type: 'revertState', canUndo: true, canRedo: true, revertState } });
	    buttonReadCounts.fill(0);
	    buttonWriteCounts.fill(0);

		    buttonReadCounts.fill(0);
		    context.window.dispatchEvent({ type: 'message', data: { type: 'revertActionState', pending: false } });
	    assert.strictEqual(totalButtonReads(), 0, 'duplicate idle revert action state should skip revert button reads');
	    assert.deepStrictEqual(buttonWriteCounts, [0, 0, 0, 0, 0, 0], 'duplicate idle revert action state should not rewrite buttons');

	    revertButtons[0].dispatchEvent({ type: 'click' });
	    assert.ok(totalButtonWrites() > 0, 'starting a revert action should disable revert controls');
	    buttonReadCounts.fill(0);
	    const writesBeforeRevertComplete = totalButtonWrites();
	    context.window.dispatchEvent({ type: 'message', data: { type: 'revertActionState', pending: false } });
	    assert.ok(totalButtonReads() > 0, 'finishing pending revert action should sync revert controls');
	    assert.ok(totalButtonWrites() > writesBeforeRevertComplete, 'finishing pending revert action should restore revert controls');
	    buttonReadCounts.fill(0);
	    const writesAfterRevertComplete = totalButtonWrites();
	    context.window.dispatchEvent({ type: 'message', data: { type: 'revertActionState', pending: false } });
	    assert.strictEqual(totalButtonReads(), 0, 'duplicate completed revert action state should skip revert button reads');
	    assert.strictEqual(totalButtonWrites(), writesAfterRevertComplete, 'duplicate completed revert action state should not rewrite controls');

	    context.updateRevertBar({
	      active: true,
	      revertedMessages: 3,
	      files: [
	        { path: 'src/a.ts', additions: 1, deletions: 0 },
	        { path: 'src/b.ts', additions: 0, deletions: 2 },
	        { path: 'src/c.ts', additions: 4, deletions: 1 },
	      ],
    });

	    assert.strictEqual(summaryValue, 'Undid 3 messages and reverted 3 files.');
	    assert.strictEqual(statusValue, 'Undid 3 messages and reverted 3 files.');
    assert.strictEqual(statusWriteCount, 1, 'changed revert summary should rewrite status text once');
    assert.strictEqual(summaryWriteCount, 1, 'changed revert summary should rewrite text once');
    assert.strictEqual(listClearCount, 0, 'changed revert files should avoid innerHTML clears');
    assert.strictEqual(listAppendCount, 0, 'changed revert files should avoid direct list appends');
    assert.strictEqual(listReplaceCount, 1, 'changed revert files should replace rows once');
    assert.strictEqual(revertFilesList.children.length, 3);

    context.updateRevertBar({ active: false });
    assert.strictEqual(statusValue, 'No undone messages.');
    assert.strictEqual(statusWriteCount, 2, 'clearing active revert state should update status once');
    assert.strictEqual(listClearCount, 0, 'clearing active revert state should avoid innerHTML clears');
    assert.strictEqual(listAppendCount, 0, 'clearing active revert state should avoid direct list appends');
    assert.strictEqual(listReplaceCount, 2, 'clearing active revert state should replace rows once');
    assert.strictEqual(revertFilesList.children.length, 0);
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

	  test('composer Escape hides revert bar through reusable hidden class state', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    const revertState = {
	      active: true,
	      revertedMessages: 1,
	      files: [{ path: 'src/a.ts', additions: 1, deletions: 0 }],
	    };
	    context.window.dispatchEvent({
	      type: 'message',
	      data: {
	        type: 'init',
	        messages: [],
	        mode: 'build',
	        processing: false,
	        canUndo: true,
	        canRedo: true,
	        revertState,
	      },
	    });

	    const input = elements.get('input');
	    const revertBar = elements.get('revertBar');
	    const modelSettingsPopover = elements.get('modelSettingsPopover');
	    const modelSettings = elements.get('modelSettings');
	    assert.ok(input, 'expected composer input');
	    assert.ok(revertBar, 'expected revert bar');
	    assert.ok(modelSettingsPopover, 'expected model settings popover');
		    assert.ok(modelSettings, 'expected model settings trigger');
		    assert.strictEqual(revertBar.classList.contains('hidden'), false);
		    assert.strictEqual(!!revertBar.hidden, false);
		    let hiddenClassReads = 0;
		    let hiddenClassWrites = 0;
		    const originalContains = revertBar.classList.contains;
		    const originalAdd = revertBar.classList.add;
		    const originalRemove = revertBar.classList.remove;
		    const originalToggle = revertBar.classList.toggle;
		    revertBar.classList.contains = (name: string) => {
		      if (name === 'hidden') hiddenClassReads++;
		      return originalContains(name);
		    };
		    revertBar.classList.add = (...names: string[]) => {
		      if (names.includes('hidden')) hiddenClassWrites++;
		      return originalAdd(...names);
		    };
		    revertBar.classList.remove = (...names: string[]) => {
		      if (names.includes('hidden')) hiddenClassWrites++;
		      return originalRemove(...names);
		    };
		    revertBar.classList.toggle = (name: string, force?: boolean) => {
		      if (name === 'hidden') hiddenClassWrites++;
		      return originalToggle(name, force);
		    };
		    let inputBlurCount = 0;
		    input.blur = () => {
		      inputBlurCount++;
		    };
		    context.document.activeElement = modelSettings;
		    context.openModelSettingsPopover();
		    assert.strictEqual(modelSettingsPopover.classList.contains('hidden'), false, 'expected model settings popover to open for Escape containment check');

	    let prevented = false;
	    const escapeEvent: any = {
	      type: 'keydown',
	      key: 'Escape',
	      preventDefault: () => {
	        prevented = true;
	      },
	    };
	    input.dispatchEvent(escapeEvent);
	    if (!escapeEvent.cancelBubble) context.document.dispatchEvent(escapeEvent);

		    assert.strictEqual(prevented, true);
		    assert.strictEqual(originalContains('hidden'), true, 'Escape should hide the revert bar with the shared hidden class');
		    assert.strictEqual(hiddenClassReads, 0, 'Escape should hide the revert bar without reading the hidden class');
		    assert.strictEqual(hiddenClassWrites, 1, 'Escape should hide the revert bar once');
		    assert.strictEqual(!!revertBar.hidden, false, 'Escape should not set the native hidden attribute');
		    assert.strictEqual(modelSettingsPopover.classList.contains('hidden'), false, 'composer Escape should not bubble into document popover dismissal');
		    assert.strictEqual(escapeEvent.__stopImmediatePropagation, true, 'composer Escape should stop same-turn document Escape handlers');

		    hiddenClassReads = 0;
		    hiddenClassWrites = 0;
		    const duplicateEscapeEvent: any = { type: 'keydown', key: 'Escape' };
		    input.dispatchEvent(duplicateEscapeEvent);
		    assert.strictEqual(hiddenClassReads, 0, 'cached hidden revert bar Escape should not read visibility');
		    assert.strictEqual(hiddenClassWrites, 0, 'cached hidden revert bar Escape should not rewrite visibility');
		    assert.strictEqual(inputBlurCount, 1, 'cached hidden revert bar Escape should fall back to blurring the input');
		    assert.strictEqual(duplicateEscapeEvent.__stopImmediatePropagation, true, 'cached hidden revert bar Escape should still be consumed by the composer');

		    hiddenClassReads = 0;
		    hiddenClassWrites = 0;
		    context.updateRevertBar(revertState);
		    assert.strictEqual(originalContains('hidden'), false, 'unchanged active revert state should be able to reveal the bar again');
		    assert.strictEqual(hiddenClassReads, 0, 'unchanged active revert state should reveal without reading the hidden class');
		    assert.strictEqual(hiddenClassWrites, 1, 'unchanged active revert state should reveal once after Escape hid the bar');
		    assert.strictEqual(!!revertBar.hidden, false, 're-showing the bar should not be blocked by a stale hidden attribute');
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

	  test('revert discard confirmation skips duplicate aria and visibility reads', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], mode: 'build', skills: [] } });

	    const revertDiscardConfirm = elements.get('revertDiscardConfirm');
	    const revertDiscard = elements.get('revertDiscard');
	    const revertDiscardCancel = elements.get('revertDiscardCancel');
	    assert.ok(revertDiscardConfirm, 'expected revert discard confirmation');
	    assert.ok(revertDiscard, 'expected revert discard button');
	    assert.ok(revertDiscardCancel, 'expected revert discard cancel button');
	    revertDiscardConfirm.classList.add('hidden');
	    revertDiscard.setAttribute('aria-expanded', 'false');
	    revertDiscard.disabled = false;
	    revertDiscardCancel.disabled = false;
	    const focusEvents: Array<{ id: string; options: unknown }> = [];
	    revertDiscard.focus = (options?: unknown) => {
	      context.document.activeElement = revertDiscard;
	      focusEvents.push({ id: 'discard', options });
	    };
	    revertDiscardCancel.focus = (options?: unknown) => {
	      context.document.activeElement = revertDiscardCancel;
	      focusEvents.push({ id: 'cancel', options });
	    };

	    let hiddenClassReads = 0;
	    let hiddenClassWrites = 0;
	    const originalConfirmAdd = revertDiscardConfirm.classList.add;
	    const originalConfirmContains = revertDiscardConfirm.classList.contains;
	    const originalConfirmRemove = revertDiscardConfirm.classList.remove;
	    const originalConfirmToggle = revertDiscardConfirm.classList.toggle;
	    revertDiscardConfirm.classList.contains = (name: string) => {
	      if (name === 'hidden') hiddenClassReads++;
	      return originalConfirmContains(name);
	    };
	    revertDiscardConfirm.classList.add = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalConfirmAdd(...names);
	    };
	    revertDiscardConfirm.classList.remove = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalConfirmRemove(...names);
	    };
	    revertDiscardConfirm.classList.toggle = (name: string, force?: boolean) => {
	      if (name === 'hidden') hiddenClassWrites++;
	      return originalConfirmToggle(name, force);
	    };

	    let ariaExpandedReads = 0;
	    let ariaExpandedWrites = 0;
	    const originalGetAttribute = revertDiscard.getAttribute;
	    const originalSetAttribute = revertDiscard.setAttribute;
	    revertDiscard.getAttribute = function getAttribute(name: string) {
	      if (name === 'aria-expanded') ariaExpandedReads++;
	      return originalGetAttribute.call(this, name);
	    };
	    revertDiscard.setAttribute = function setAttribute(name: string, value: unknown) {
	      if (name === 'aria-expanded') ariaExpandedWrites++;
	      return originalSetAttribute.call(this, name, value);
	    };
	    const totalReads = () => hiddenClassReads + ariaExpandedReads;
	    const totalWrites = () => hiddenClassWrites + ariaExpandedWrites;

	    assert.strictEqual(typeof context.setRevertDiscardConfirmPending, 'function');
	    context.setRevertDiscardConfirmPending(false, { sync: false });
	    assert.strictEqual(totalWrites(), 0, 'initial closed confirmation sync should not rewrite matching state');
	    assert.strictEqual(hiddenClassReads, 0, 'initial closed confirmation sync should not read confirmation visibility');
	    const afterInitialSyncReads = totalReads();

	    context.setRevertDiscardConfirmPending(false, { sync: false });
	    assert.strictEqual(totalReads(), afterInitialSyncReads, 'unchanged closed confirmation should not re-read DOM state');
	    assert.strictEqual(totalWrites(), 0, 'unchanged closed confirmation should not rewrite state');

	    context.setRevertDiscardConfirmPending(true, { sync: false });
	    assert.strictEqual(hiddenClassWrites, 1, 'opening confirmation should reveal once');
	    assert.strictEqual(hiddenClassReads, 0, 'opening confirmation should use cached visibility without reading the hidden class');
	    assert.strictEqual(ariaExpandedWrites, 1, 'opening confirmation should expand the discard button once');
	    assert.strictEqual(context.document.activeElement, revertDiscardCancel, 'opening confirmation should focus the safe cancel action');
	    const afterOpenReads = totalReads();
	    const afterOpenWrites = totalWrites();

	    context.setRevertDiscardConfirmPending(true, { sync: false });
	    assert.strictEqual(totalReads(), afterOpenReads, 'unchanged open confirmation should not re-read DOM state');
	    assert.strictEqual(totalWrites(), afterOpenWrites, 'unchanged open confirmation should not rewrite state');
	    assert.deepStrictEqual(focusEvents.map(event => event.id), ['cancel'], 'unchanged open confirmation should not refocus');

	    context.setRevertDiscardConfirmPending(false, { sync: false });
	    assert.strictEqual(hiddenClassWrites, 2, 'closing confirmation should hide once');
	    assert.strictEqual(hiddenClassReads, 0, 'closing confirmation should use cached visibility without reading the hidden class');
	    assert.strictEqual(ariaExpandedWrites, 2, 'closing confirmation should collapse the discard button once');
	    assert.strictEqual(context.document.activeElement, revertDiscard, 'closing confirmation should restore focus to the discard trigger');
	    const afterClosedReads = totalReads();
	    const afterClosedWrites = totalWrites();

	    context.setRevertDiscardConfirmPending(false, { sync: false });
	    assert.strictEqual(totalReads(), afterClosedReads, 'unchanged closed confirmation should not re-read state again');
	    assert.strictEqual(totalWrites(), afterClosedWrites, 'unchanged closed confirmation should not rewrite state again');
	    assert.deepStrictEqual(focusEvents.map(event => event.id), ['cancel', 'discard'], 'unchanged closed confirmation should not refocus');

	    context.setRevertDiscardConfirmPending(true, { sync: false });
	    assert.strictEqual(context.document.activeElement, revertDiscardCancel);
	    context.setRevertDiscardConfirmPending(false, { sync: false, restoreFocus: false });
	    assert.strictEqual(context.document.activeElement, revertDiscardCancel, 'programmatic close should not steal focus back to discard');
	    assert.deepStrictEqual(focusEvents.map(event => event.id), ['cancel', 'discard', 'cancel']);
	    assert.deepStrictEqual(
	      focusEvents.filter(event => !(event.options && typeof event.options === 'object' && (event.options as any).preventScroll === true)),
	      [],
	      'revert discard confirmation focus should avoid scrolling the transcript'
	    );
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

