	  test('escapeHtml uses a string escaper that is safe for generated attributes', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, getCreatedCount } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

	    const before = getCreatedCount();
	    const escaped = context.escapeHtml(`<tag attr="one">'two' & more`);
	    const escapedZero = context.escapeHtml(0);
	    const escapedFalse = context.escapeHtml(false);
	    const escapedNull = context.escapeHtml(null);
	    const after = getCreatedCount();

	    assert.strictEqual(escaped, '&lt;tag attr=&quot;one&quot;&gt;&#39;two&#39; &amp; more');
	    assert.strictEqual(escapedZero, '0');
	    assert.strictEqual(escapedFalse, 'false');
	    assert.strictEqual(escapedNull, '');
	    assert.strictEqual(after, before, 'expected escaping to avoid per-call DOM allocation');
	  });

  test('live markdown code fences stay code until the fence closes', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const openFence = context.renderMarkdown('```markdown\n# Still code');
    const closedFence = context.renderMarkdown('```markdown\n# Rendered\n```');
    const tildeFence = context.renderMarkdown('~~~ts\nconst x = 1;\n~~~');
    const longerFence = context.renderMarkdown('````ts\nconst ticks = "```";\n````');
	    const infoFence = context.renderMarkdown('```ts title="demo"\nconst labeled = true;\n```');
	    const sanitizedFence = context.renderMarkdown('``` .bad/lang$ title="demo"\nconst safe = true;\n```');
	    const markdownInfoFence = context.renderMarkdown('```markdown title="demo"\n# Rendered too\n```');
	    const longLanguage = 'a'.repeat(80);
	    const expectedLanguage = 'a'.repeat(64);
	    const longLanguageFence = context.renderMarkdown('```' + longLanguage + '\nlong();\n```');

    assert.strictEqual(countOccurrences(tildeFence, 'data-action="copyCodeBlock"'), 1);
    assert.match(openFence, /<pre tabindex="0" data-scrollable="true" aria-label="markdown code block"><code class="language-markdown"># Still code<\/code><\/pre>/);
    assert.doesNotMatch(openFence, /<h1>Still code<\/h1>/);
    assert.match(closedFence, /<h1>Rendered<\/h1>/);
    assert.doesNotMatch(closedFence, /data-action="copyCodeBlock"/);
    assert.match(tildeFence, /title="Copy ts code block" aria-label="Copy ts code block">Copy<\/button>/);
    assert.match(tildeFence, /<pre tabindex="0" data-scrollable="true" aria-label="ts code block"><code class="language-ts">const x = 1;<\/code><\/pre>/);
    assert.match(longerFence, /<pre tabindex="0" data-scrollable="true" aria-label="ts code block"><code class="language-ts">const ticks = &quot;```&quot;;<\/code><\/pre>/);
    assert.match(infoFence, /<pre tabindex="0" data-scrollable="true" aria-label="ts code block"><code class="language-ts">const labeled = true;<\/code><\/pre>/);
    assert.doesNotMatch(infoFence, /title=&quot;demo&quot;/);
		    assert.match(sanitizedFence, /<pre tabindex="0" data-scrollable="true" aria-label="\.badlang code block"><code class="language-.badlang">const safe = true;<\/code><\/pre>/);
		    assert.doesNotMatch(sanitizedFence, /title=&quot;demo&quot;/);
		    assert.match(markdownInfoFence, /<h1>Rendered too<\/h1>/);
		    assert.ok(longLanguageFence.includes(`title="Copy ${expectedLanguage} code block" aria-label="Copy ${expectedLanguage} code block">Copy</button>`));
		    assert.ok(longLanguageFence.includes(`<pre tabindex="0" data-scrollable="true" aria-label="${expectedLanguage} code block"><code class="language-${expectedLanguage}">long();</code></pre>`));
		    assert.ok(!longLanguageFence.includes(longLanguage), 'markdown code fence language metadata should not inject full pathological identifiers');
		  });

