	  test('code block copy feedback clears stale reset timers on repeated clicks', async () => {
		    const controller = createStandaloneChatController();
		    const webview = {
	      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    let copiedText = '';
    context.navigator.clipboard.writeText = async (text: unknown) => {
      copiedText = String(text);
    };

    let nextTimerId = 0;
    const timers = new Map<number, { callback: () => void; cleared: boolean }>();
    context.setTimeout = (callback: () => void) => {
      const id = ++nextTimerId;
      timers.set(id, { callback, cleared: false });
      return id;
    };
    context.clearTimeout = (id: number) => {
      const timer = timers.get(id);
      if (timer) timer.cleared = true;
    };

	    let codeTextReads = 0;
		    const code = createMockElement('code');
		    code.localName = 'code';
		    Object.defineProperty(code, 'textContent', {
		      configurable: true,
		      get() {
		        codeTextReads++;
		        return 'const twice = true;';
		      },
		    });
		    const codeBlock = createMockElement('code-block');
		    const pre = createMockElement('pre');
		    codeBlock.classList.add('markdown-code-block');
		    let codeBlockLookupCount = 0;
		    codeBlock.querySelector = (selector: string) => {
		      codeBlockLookupCount++;
		      return selector === 'code' ? code : null;
		    };
		    const copyButton = createMockElement('button');
		    copyButton.textContent = 'Copy';
		    copyButton.dataset.action = 'copyCodeBlock';
		    codeBlock.appendChild(copyButton);
		    pre.appendChild(code);
		    codeBlock.appendChild(pre);
			    codeBlock.contains = (node: unknown) => node === copyButton;
		    let codeBlockLayoutParentReads = 0;
		    Object.defineProperty(copyButton, 'parentNode', {
		      configurable: true,
		      get: () => {
		        codeBlockLayoutParentReads++;
		        return codeBlock;
		      },
		    });
			    copyButton.setAttribute('aria-label', 'Copy code block');
		    let textValue = String(copyButton.textContent || '');
		    let textReadCount = 0;
		    let textWriteCount = 0;
		    Object.defineProperty(copyButton, 'textContent', {
		      configurable: true,
		      get: () => {
		        textReadCount++;
		        return textValue;
		      },
		      set: (value: unknown) => {
		        textWriteCount++;
		        textValue = String(value);
		      },
	    });
		    let ariaWriteCount = 0;
		    let ariaReadCount = 0;
		    const originalGetAttribute = copyButton.getAttribute;
		    copyButton.getAttribute = function getAttribute(name: string) {
		      if (name === 'aria-label') ariaReadCount++;
		      return originalGetAttribute.call(this, name);
		    };
		    const originalSetAttribute = copyButton.setAttribute;
		    copyButton.setAttribute = function setAttribute(name: string, value: unknown) {
		      if (name === 'aria-label') ariaWriteCount++;
		      return originalSetAttribute.call(this, name, value);
		    };
		    let copiedClassToggleCount = 0;
		    let copiedClassContainsCount = 0;
		    const originalContains = copyButton.classList.contains;
		    copyButton.classList.contains = (name: string) => {
		      if (name === 'copied') copiedClassContainsCount++;
		      return originalContains(name);
		    };
		    const originalToggle = copyButton.classList.toggle;
		    copyButton.classList.toggle = (name: string, force?: boolean) => {
		      if (name === 'copied') copiedClassToggleCount++;
		      return originalToggle(name, force);
		    };
	    const totalStateWrites = () => textWriteCount + ariaWriteCount + copiedClassToggleCount;
	    let codeBlockOwnerScans = 0;
	    copyButton.closest = (selector: string) => {
	      if (selector === '[data-action]') return copyButton;
	      if (selector === '[data-action="copyCodeBlock"]') return copyButton;
	      if (selector === '.markdown-code-block') {
	        codeBlockOwnerScans++;
	        return codeBlock;
	      }
      return null;
    };

	    context.document.dispatchEvent({ type: 'click', target: copyButton });
	    await new Promise(resolve => setTimeout(resolve, 0));
	    assert.strictEqual(textWriteCount, 1, 'first click should write copied text once');
		    assert.strictEqual(ariaWriteCount, 1, 'first click should write copied aria label once');
		    assert.strictEqual(copiedClassToggleCount, 1, 'first click should set copied class once');
		    const afterFirstClick = totalStateWrites();
		    const readsAfterFirstClick = {
		      text: textReadCount,
		      aria: ariaReadCount,
		      copiedClass: copiedClassContainsCount,
		    };

		    context.document.dispatchEvent({ type: 'click', target: copyButton });
		    await new Promise(resolve => setTimeout(resolve, 0));

		    assert.strictEqual(copiedText, 'const twice = true;');
			    assert.strictEqual(codeBlockOwnerScans, 0, 'repeated code copy should use the direct owning code-block layout');
		    assert.strictEqual(codeBlockLayoutParentReads, 1, 'repeated code copy should reuse the cached owning code block after one layout walk');
			    assert.strictEqual(codeBlockLookupCount, 0, 'repeated copy should use the direct code element layout');
		    assert.strictEqual(codeTextReads, 1, 'repeated copy should not reread rendered code text');
		    assert.strictEqual(timers.size, 2);
		    assert.strictEqual(timers.get(1)?.cleared, true, 'expected second click to cancel the first reset timer');
		    assert.strictEqual(timers.get(2)?.cleared, false);
		    assert.strictEqual(totalStateWrites(), afterFirstClick, 'second click should not rewrite unchanged copied state');
		    assert.deepStrictEqual(
		      { text: textReadCount, aria: ariaReadCount, copiedClass: copiedClassContainsCount },
		      readsAfterFirstClick,
		      'second click should not re-read unchanged copied state'
		    );
			    assert.strictEqual(textValue, 'Copied');
			    assert.strictEqual(copyButton.getAttribute('aria-label'), 'Copied code block');
			    assert.strictEqual(copyButton.dataset.copyResetText, undefined);
			    assert.strictEqual(copyButton.dataset.copyResetAriaLabel, undefined);

		    timers.get(2)?.callback();

	    assert.strictEqual(textValue, 'Copy');
		    assert.strictEqual(copyButton.getAttribute('aria-label'), 'Copy code block');
		    assert.strictEqual(copyButton.classList.contains('copied'), false);
	    assert.strictEqual(textWriteCount, 2, 'timer reset should write reset text once');
	    assert.strictEqual(ariaWriteCount, 2, 'timer reset should write reset aria label once');
		    assert.strictEqual(copiedClassToggleCount, 2, 'timer reset should clear copied class once');
		  });

  test('assistant markdown copy avoids rendered DOM serialization', async () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    let copiedText = '';
    context.navigator.clipboard.writeText = async (text: unknown) => {
      copiedText = String(text);
    };

    let innerHtmlReads = 0;
    let textContentReads = 0;
    const contentEl = {
      get innerHTML() {
        innerHtmlReads++;
        return '<strong>raw</strong> markdown';
      },
      get textContent() {
        textContentReads++;
        return 'raw markdown';
      },
    };
    context.rememberAssistantMarkdownRaw(contentEl, '**raw** markdown');
    const messageEl = {
      dataset: { id: 'assistant-copy' },
      querySelector: (selector: string) => selector === '.message-content' ? contentEl : null,
    };
    const copyButton = createMockElement('button');
    copyButton.textContent = 'MD';
    copyButton.dataset.action = 'copyAssistantMarkdown';
    copyButton.setAttribute('aria-label', 'MD, copy assistant response as Markdown');
    const closestSelectors: string[] = [];
    copyButton.closest = (selector: string) => {
      closestSelectors.push(selector);
      if (selector === '[data-action]') return copyButton;
      if (selector === '.message.assistant') return messageEl;
      return null;
    };

    context.document.dispatchEvent({ type: 'click', target: copyButton });
    await new Promise(resolve => setTimeout(resolve, 0));

    assert.strictEqual(copiedText, '**raw** markdown');
    assert.strictEqual(innerHtmlReads, 0, 'Markdown copy should not read rendered HTML');
    assert.strictEqual(textContentReads, 0, 'Markdown copy should not read rendered text');
    assert.deepStrictEqual(closestSelectors, ['.message.assistant']);
    assert.strictEqual(copyButton.textContent, '✓');
    assert.strictEqual(copyButton.getAttribute('aria-label'), 'Copied assistant Markdown');
  });

