    messageEl.querySelector = function querySelector(selector: string) {
      messageBodyLookupCount++;
      if (selector === '.message-content') return contentEl;
      return originalQuerySelector.call(this, selector);
    };

    context.queueAssistantMarkdownToken('assistant-copy-streamed', ' **streamed**', false);
