  test('assistant markdown stream skips unchanged rendered html writes', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const timers: Array<() => void> = [];
    context.setTimeout = (callback: () => void) => {
      timers.push(callback);
      return timers.length;
    };
    context.clearTimeout = () => {};

    context.addMessage({
      id: 'assistant-markdown-noop',
      role: 'assistant',
      content: 'cached',
      timestamp: Date.now(),
    });

    const messages = elements.get('messages');
    const messageEl = (messages?.children || []).find((child: any) => child?.dataset?.id === 'assistant-markdown-noop');
    assert.ok(messageEl, 'expected assistant message element');
    const bubbleEl = findMockChildByClass(messageEl, 'message-bubble');
    const contentEl = findMockChildByClass(bubbleEl, 'message-content');
    assert.ok(contentEl, 'expected assistant content element');

    const originalContains = messageEl.classList.contains;
    messageEl.classList.contains = (name: string) => name === 'assistant' || originalContains(name);
    let linkifyScheduleCount = 0;
    context.scheduleFileLinkifyIfNeeded = () => {
      linkifyScheduleCount++;
    };

    let innerHtml = String(contentEl.innerHTML || '');
    let innerHtmlWrites = 0;
    Object.defineProperty(contentEl, 'innerHTML', {
      configurable: true,
      get: () => innerHtml,
      set: (value: unknown) => {
        innerHtmlWrites++;
        innerHtml = String(value);
      },
    });

    context.queueAssistantMarkdownToken('assistant-markdown-noop', '\n', false);
    assert.strictEqual(timers.length, 1, 'expected trailing newline render timer');
    timers.shift()?.();
    assert.strictEqual(context.getAssistantMarkdownRaw(contentEl), 'cached\n');
    assert.strictEqual(innerHtmlWrites, 0, 'trailing newline should not rewrite unchanged rendered markdown html');
    assert.strictEqual(linkifyScheduleCount, 0, 'trailing newline should not schedule file linkification for unchanged rendered html');

    context.queueAssistantMarkdownToken('assistant-markdown-noop', ' **changed**', false);
    assert.strictEqual(timers.length, 1, 'expected changed markdown render timer');
    timers.shift()?.();
    assert.strictEqual(context.getAssistantMarkdownRaw(contentEl), 'cached\n **changed**');
    assert.strictEqual(innerHtmlWrites, 1, 'changed markdown html should rewrite once');
    assert.strictEqual(linkifyScheduleCount, 1, 'changed rendered markdown html should schedule linkification once');
    assert.match(innerHtml, /changed/);
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

  test('empty assistant markdown render skips empty innerHTML writes', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    assert.strictEqual(typeof context.renderAssistantMarkdownInto, 'function');
    const contentEl = createMockElement('assistant-content');
    contentEl.className = 'message-content md';
    let innerHtml = '';
    let innerHtmlWrites = 0;
    Object.defineProperty(contentEl, 'innerHTML', {
      configurable: true,
      get: () => innerHtml,
      set: (value: unknown) => {
        innerHtmlWrites++;
        innerHtml = String(value);
        if (innerHtml === '') {
          contentEl.children = [];
          contentEl.firstChild = null;
        }
      },
    });

    const emptyInfo = context.renderAssistantMarkdownInto(contentEl, '');
    assert.strictEqual(emptyInfo.raw, '');
    assert.strictEqual(emptyInfo.htmlChanged, false);
    assert.strictEqual(innerHtmlWrites, 0, 'empty assistant markdown should not clear an already-empty content element');

    const blankInfo = context.renderAssistantMarkdownInto(contentEl, '\n');
    assert.strictEqual(blankInfo.raw, '\n');
    assert.strictEqual(blankInfo.htmlChanged, false);
    assert.strictEqual(innerHtmlWrites, 0, 'blank-only assistant markdown should keep the empty html cache without writes');

    const changedInfo = context.renderAssistantMarkdownInto(contentEl, '**changed**');
    assert.strictEqual(changedInfo.raw, '**changed**');
    assert.strictEqual(changedInfo.htmlChanged, true);
    assert.strictEqual(innerHtmlWrites, 1, 'non-empty rendered markdown should write html once');
    assert.match(innerHtml, /changed/);

    const duplicateInfo = context.renderAssistantMarkdownInto(contentEl, '**changed**');
    assert.strictEqual(duplicateInfo.raw, '**changed**');
    assert.strictEqual(duplicateInfo.htmlChanged, false);
    assert.strictEqual(innerHtmlWrites, 1, 'duplicate rendered markdown should reuse the html cache');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

