	  test('clipboard fallback removes its temporary textarea when copy command throws', async () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    assert.strictEqual(typeof context.writeClipboard, 'function');
    context.navigator.clipboard.writeText = undefined;
    let execCommandCalls = 0;
    context.document.execCommand = () => {
      execCommandCalls++;
      throw new Error('copy failed');
    };

    const appended: any[] = [];
    const originalAppendChild = context.document.body.appendChild;
    context.document.body.appendChild = function appendChild(child: any) {
      appended.push(child);
      return originalAppendChild.call(this, child);
    };
    const beforeChildren = context.document.body.children.length;

    const ok = await context.writeClipboard('fallback copy text');

    assert.strictEqual(ok, false);
    assert.strictEqual(execCommandCalls, 1);
    assert.strictEqual(appended.length, 1, 'expected one temporary textarea');
    assert.strictEqual(appended[0].id, 'textarea');
    assert.strictEqual(appended[0].style.opacity, '0');
    assert.strictEqual(appended[0].style.pointerEvents, 'none');
    assert.strictEqual(appended[0].parentNode, undefined);
	    assert.strictEqual(context.document.body.children.length, beforeChildren);
	  });

