		    outputModalCopy.getAttribute = function getAttribute(name: string) {
		      if (name === 'aria-label') copyAriaReadCount++;
		      return originalGetAttribute.call(this, name);
		    };
		    const originalSetAttribute = outputModalCopy.setAttribute;
		    outputModalCopy.setAttribute = function setAttribute(name: string, value: unknown) {
		      if (name === 'aria-label') copyAriaWriteCount++;
	      return originalSetAttribute.call(this, name, value);
	    };

		    let hiddenClassWrites = 0;
