	    context.document.dispatchEvent({ type: 'keydown', key: 'Tab', shiftKey: true, preventDefault: () => { tabPrevented++; } });
	    assert.strictEqual(tabPrevented, 4, 'modal Shift+Tab from the body should be handled');
	    assert.strictEqual(context.document.activeElement, outputModalClose, 'Shift+Tab on the first modal control should wrap to the last');
		    assert.strictEqual(outputModalQueryCount, 0, 'modal Shift+Tab should not query descendants');
		    assert.deepStrictEqual(focusOrder.slice(0, 5), ['close', 'body', 'copy', 'body', 'close'], 'modal keyboard handling should cycle through copy close and body controls');
		    assert.deepStrictEqual(
		      focusEvents.slice(0, 5).filter(event => !(event.options && typeof event.options === 'object' && (event.options as any).preventScroll === true)),
			      [],
			      'modal open and keyboard focus should avoid scrolling the transcript'
			    );
			    const focusEventsAfterKeyboard = focusEvents.length;
			    const scrollWritesAfterKeyboard = bodyScrollTopWriteCount;

