		    assert.strictEqual(hiddenClassReads, 0, 'unchanged open state should not re-read modal visibility');
		    assert.strictEqual(focusEvents.length, focusEventsAfterKeyboard, 'unchanged open state should not move focus again');
		    assert.strictEqual(bodyScrollTopWriteCount, scrollWritesAfterKeyboard, 'unchanged open state should not reset output scroll');

