		    assert.strictEqual(bodyAriaWriteCount, 1, 'same title should not rewrite the output body label');
		    assert.strictEqual(bodyWriteCount, 2, 'changed body should be rewritten once');
		    assert.strictEqual(hiddenClassWrites, 1, 'already-visible modal should stay visible without another class write');
		    assert.strictEqual(hiddenClassReads, 0, 'already-visible modal content change should not re-read visibility');

