		    assert.strictEqual(titleTooltipWriteCount, 2, 'changed title should rewrite the tooltip once');
		    assert.strictEqual(bodyAriaWriteCount, 2, 'changed title should relabel the scrollable output body once');
		    assert.strictEqual(bodyWriteCount, 2, 'same body should not be rewritten when only the title changes');
		    assert.strictEqual(hiddenClassWrites, 1, 'title-only changes should keep the modal visible without another class write');

	    context.openOutputModal('Run: retest', 0);
	    assert.strictEqual(bodyValue, '0');
	    assert.strictEqual(bodyWriteCount, 3, 'numeric output should be rendered instead of hidden as empty text');

	    context.openOutputModal('Run: retest', false);
