		    assert.strictEqual(copyTextWriteCount, 1, 'copy feedback should write copied label once');
		    assert.strictEqual(copyAriaWriteCount, 1, 'copy feedback should write copied aria label once');
		    assert.strictEqual(copyTitleWriteCount, 1, 'copy feedback should write copied title once');
		    const afterCopied = totalWrites();
		    const copyReadsAfterCopied = {
		      text: copyTextReadCount,
		      title: copyTitleReadCount,
		      aria: copyAriaReadCount,
		    };

	    context.showOutputModalCopyFeedback();
