		  test('output modal resets stale copy feedback when visible content changes', () => {
		    const controller = createStandaloneChatController();
		    const webview = {
		      cspSource: 'test-csp',
		      asWebviewUri: (uri: unknown) => uri,
		    } as unknown as vscode.Webview;

		    const html = controller.webviewApi.getHtml(webview);
		    const scripts = extractOrderedScriptSources(html);
		    const { context, elements, posted } = createMockBrowserContext();
		    runScriptsInMockBrowser(scripts, context);

		    const outputModal = elements.get('outputModal');
		    const outputModalCopy = elements.get('outputModalCopy');
		    assert.ok(outputModal, 'expected output modal element');
		    assert.ok(outputModalCopy, 'expected output modal copy button');
		    outputModal.classList.add('hidden');

		    let nextTimerId = 0;
		    const clearedTimerIds: unknown[] = [];
		    context.setTimeout = () => {
		      nextTimerId++;
		      return nextTimerId;
		    };
		    context.clearTimeout = (id: unknown) => {
		      clearedTimerIds.push(id);
		    };

		    context.openOutputModal('First output', 'alpha');
		    context.showOutputModalCopyFeedback();
		    assert.strictEqual(outputModalCopy.textContent, 'Copied');
		    assert.strictEqual(outputModalCopy.getAttribute('aria-label'), 'Copied full output');

		    context.openOutputModal('Second output', 'beta');
		    assert.strictEqual(outputModalCopy.textContent, 'Copy', 'changing visible output should clear stale copy feedback');
		    assert.strictEqual(outputModalCopy.getAttribute('aria-label'), 'Copy full output');
		    assert.deepStrictEqual(clearedTimerIds, [1], 'changing visible output should clear the stale copy reset timer');

		    context.showOutputModalCopyFeedback();
		    context.openOutputModal('Second output', 'beta');
		    assert.strictEqual(outputModalCopy.textContent, 'Copied', 'unchanged duplicate open should preserve current copy feedback');
		    assert.deepStrictEqual(clearedTimerIds, [1], 'unchanged duplicate open should not clear the active copy reset timer');
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

