  test('duplicate plan pending skips unchanged plan card rerenders', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const planMessage = {
      id: 'plan-1',
      role: 'plan',
      content: 'Plan\n\n1. Keep work scoped.',
      plan: { status: 'draft' },
      timestamp: Date.now(),
    };

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [planMessage],
        activePlanMessageId: 'plan-1',
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        mode: 'plan',
        planPending: true,
        processing: false,
      },
    });

	    const messages = elements.get('messages');
	    assert.ok(messages);
	    const planEl = messages.children.find((child: any) => child && child.dataset && child.dataset.id === 'plan-1');
	    assert.ok(planEl, 'expected plan message element to be rendered');
	    assert.strictEqual(typeof context.createCompactRenderKeyBuilder, 'function');
	    assert.strictEqual(typeof context.appendCompactRenderKeyPart, 'function');
	    assert.strictEqual(typeof context.finishCompactRenderKey, 'function');
	    const planRenderKey = context.getPlanCardRenderKey(planMessage);
	    const expectedPlanKeyBuilder = context.createCompactRenderKeyBuilder();
	    context.appendCompactRenderKeyPart(expectedPlanKeyBuilder, 'plan-1');
	    context.appendCompactRenderKeyPart(expectedPlanKeyBuilder, 'draft');
	    context.appendCompactRenderKeyPart(expectedPlanKeyBuilder, 'Plan\n\n1. Keep work scoped.');
	    context.appendCompactRenderKeyPart(expectedPlanKeyBuilder, '1');
	    assert.strictEqual(planRenderKey, context.finishCompactRenderKey(expectedPlanKeyBuilder));
	    assert.ok(planRenderKey.length < 32, 'plan render key should stay compact');
    assert.ok(!planRenderKey.includes('Keep work scoped'), 'plan render key should not retain raw plan content');
    assert.strictEqual(context.getPlanCardRenderDatasetKey(planRenderKey), context.getCompactRenderDatasetKey(planRenderKey));
    assert.strictEqual(planEl.dataset.planRenderKey, context.getPlanCardRenderDatasetKey(planRenderKey));
    assert.strictEqual(context.getRememberedPlanCardRenderKey(planEl), planRenderKey);
    assert.ok(!planEl.dataset.planRenderKey.includes('Keep work scoped'));

    let planInnerHtml = planEl.innerHTML || '';
    let planInnerHtmlWrites = 0;
    Object.defineProperty(planEl, 'innerHTML', {
      configurable: true,
      get: () => planInnerHtml,
      set(value: unknown) {
        planInnerHtmlWrites++;
        planInnerHtml = String(value);
      },
    });
    let planSelectorCalls = 0;
    planEl.querySelector = () => {
      planSelectorCalls++;
      throw new Error('duplicate plan pending should skip unchanged plan-card selectors');
    };
    const input = elements.get('input');
    assert.ok(input, 'expected composer input');
    let inputFocusCount = 0;
    input.focus = () => {
      inputFocusCount++;
    };
    let inputDisabledReadCount = 0;
    let inputDisabled = !!input.disabled;
    Object.defineProperty(input, 'disabled', {
      configurable: true,
      get: () => {
        inputDisabledReadCount++;
        return inputDisabled;
      },
      set: (value: unknown) => {
        inputDisabled = !!value;
      },
    });

    let scrollHeightReads = 0;
    let clientHeightReads = 0;
    Object.defineProperty(messages, 'scrollHeight', {
      configurable: true,
      get() {
        scrollHeightReads++;
        return 1000;
      },
    });
    Object.defineProperty(messages, 'clientHeight', {
      configurable: true,
      get() {
        clientHeightReads++;
        return 1000;
      },
    });
    messages.scrollTop = 0;

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'planPending',
        value: true,
        planMessageId: 'plan-1',
      },
    });

    assert.strictEqual(planInnerHtmlWrites, 0, 'duplicate plan pending should skip plan-card HTML replacement');
    assert.strictEqual(planSelectorCalls, 0, 'duplicate plan pending should skip plan-card selector lookups');
    assert.strictEqual(clientHeightReads, 0, 'duplicate plan pending should avoid near-bottom clientHeight reads');
    assert.strictEqual(scrollHeightReads, 0, 'duplicate plan pending should avoid near-bottom and autoscroll reads');
    assert.strictEqual(inputDisabledReadCount, 0, 'duplicate plan pending should skip composer control sync reads');
    assert.strictEqual(inputFocusCount, 0, 'duplicate plan pending should not refocus the composer');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

  test('changed plan with empty activity skips fragment allocation', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const planMessage = {
      id: 'plan-empty-activity',
      role: 'plan',
      content: 'Plan\n\n1. Keep work scoped.',
      plan: { status: 'draft' },
      timestamp: Date.now(),
    };

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [planMessage],
        activePlanMessageId: 'plan-empty-activity',
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        mode: 'plan',
        planPending: true,
        processing: false,
      },
    });

    const messages = elements.get('messages');
    assert.ok(messages);
    const planEl = messages.children.find((child: any) => child && child.dataset && child.dataset.id === 'plan-empty-activity');
    assert.ok(planEl, 'expected plan message element to be rendered');
    assert.strictEqual(typeof context.getCachedMessagePlanActivityParts, 'function');
    assert.strictEqual(typeof context.rerenderPlanMessage, 'function');

    const existingDetails = createMockElement('existing-empty-plan-details');
    const existingCountEl = createMockElement('existing-empty-plan-count');
    existingDetails.querySelector = (selector: string) =>
      selector === '.plan-activity-count' ? existingCountEl : null;
    const existingBody = createMockElement('existing-empty-plan-body');
    Object.defineProperty(existingBody, 'children', {
      configurable: true,
      get: () => [],
    });
    Object.defineProperty(existingBody, 'firstChild', {
      configurable: true,
      get: () => null,
    });

    let planInnerHtml = planEl.innerHTML || '';
    let replaced = false;
    Object.defineProperty(planEl, 'innerHTML', {
      configurable: true,
      get: () => planInnerHtml,
      set(value: unknown) {
        planInnerHtml = String(value);
        replaced = true;
      },
    });

    const nextDetails = createMockElement('next-empty-plan-details');
    const nextCountEl = createMockElement('next-empty-plan-count');
    nextDetails.querySelector = (selector: string) =>
      selector === '.plan-activity-count' ? nextCountEl : null;
    const nextBody = createMockElement('next-empty-plan-body');

    let seeding = true;
    let beforeReplaceSelectorCalls = 0;
    const afterReplaceSelectors: string[] = [];
    planEl.querySelector = (selector: string) => {
      if (seeding) {
        if (selector === '.plan-activity') return existingDetails;
        if (selector === '.plan-activity-body') return existingBody;
        return null;
      }
      if (!replaced) {
        beforeReplaceSelectorCalls++;
        throw new Error('empty activity rerender should use cached controls before replacing HTML');
      }
      afterReplaceSelectors.push(selector);
      if (selector === '.plan-activity') return nextDetails;
      if (selector === '.plan-activity-body') return nextBody;
      return null;
    };

    const seededParts = context.getCachedMessagePlanActivityParts(planEl);
    assert.strictEqual(seededParts.body, existingBody);
    assert.strictEqual(seededParts.details, existingDetails);
    seeding = false;

    let fragmentCalls = 0;
    const originalCreateDocumentFragment = context.document.createDocumentFragment;
    context.document.createDocumentFragment = () => {
      fragmentCalls++;
      return originalCreateDocumentFragment();
    };

    const changedPlanMessage = {
      ...planMessage,
      content: 'Updated plan\n\n1. Keep work scoped.\n2. Verify the path.',
      plan: { status: 'ready' },
    };

    assert.strictEqual(context.rerenderPlanMessage(changedPlanMessage, false), true);
    assert.strictEqual(fragmentCalls, 0, 'empty plan activity should not allocate a fragment');
    assert.strictEqual(beforeReplaceSelectorCalls, 0, 'empty rerender should not rescan existing plan activity controls');
    assert.deepStrictEqual(afterReplaceSelectors, ['.plan-activity', '.plan-activity-body']);
    assert.strictEqual(nextDetails.dataset.count, '0');
    assert.strictEqual(nextCountEl.textContent, '');
    assert.strictEqual(nextBody.children.length, 0);
    assert.strictEqual(context.getCachedMessagePlanActivityParts(planEl).body, nextBody);
    assert.strictEqual(context.getStepBody('plan-empty-activity'), nextBody);
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

