    const remainingChildren = movedChildren.slice();
    const existingBody = createMockElement('existing-plan-body');
    for (const child of movedChildren) {
      child.parentNode = existingBody;
    }
    Object.defineProperty(existingBody, 'children', {
      configurable: true,
      get: () => movedChildren,
    });
    Object.defineProperty(existingBody, 'firstChild', {
      configurable: true,
      get: () => {
        while (remainingChildren[0] && remainingChildren[0].parentNode !== existingBody) {
          remainingChildren.shift();
        }
        return remainingChildren[0] || null;
      },
    });

