	  test('plan activity cache returns partial misses without caching them', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    assert.strictEqual(typeof context.getCachedMessagePlanActivityParts, 'function');
    const planEl = createMockElement('plan-cache-retry');
    const details = createMockElement('plan-details');
    const body = createMockElement('plan-body');
    const count = createMockElement('plan-count');
    const partsBySelector = new Map<string, any>([
      ['.plan-activity', details],
      ['.plan-activity-body', body],
    ]);

    let availableSelectors = new Set<string>();
    let countReady = false;
    const selectors: string[] = [];
    const countSelectors: string[] = [];
    planEl.querySelector = (selector: string) => {
      selectors.push(selector);
      return availableSelectors.has(selector) ? partsBySelector.get(selector) || null : null;
    };
    details.querySelector = (selector: string) => {
      countSelectors.push(selector);
      return countReady && selector === '.plan-activity-count' ? count : null;
    };

    assert.strictEqual(context.getCachedMessagePlanActivityParts(planEl), null);
    assert.deepStrictEqual(selectors, ['.plan-activity', '.plan-activity-body']);
    assert.deepStrictEqual(countSelectors, []);

    availableSelectors = new Set(['.plan-activity']);
    countReady = true;
    const partialParts = context.getCachedMessagePlanActivityParts(planEl);
    assert.strictEqual(partialParts.details, details);
    assert.strictEqual(partialParts.body, null);
    assert.strictEqual(partialParts.count, count);
    assert.deepStrictEqual(selectors, ['.plan-activity', '.plan-activity-body', '.plan-activity', '.plan-activity-body']);
    assert.deepStrictEqual(countSelectors, ['.plan-activity-count']);

    availableSelectors = new Set(['.plan-activity', '.plan-activity-body']);
    const recoveredParts = context.getCachedMessagePlanActivityParts(planEl);
    assert.strictEqual(recoveredParts.details, details);
    assert.strictEqual(recoveredParts.body, body);
    assert.strictEqual(recoveredParts.count, count);
    assert.deepStrictEqual(selectors, [
      '.plan-activity',
      '.plan-activity-body',
      '.plan-activity',
      '.plan-activity-body',
      '.plan-activity',
      '.plan-activity-body',
    ]);
    assert.deepStrictEqual(countSelectors, ['.plan-activity-count', '.plan-activity-count']);

    planEl.querySelector = () => {
      throw new Error('complete plan activity parts should be cached after recovery');
    };
    details.querySelector = () => {
      throw new Error('cached plan count should not be queried again after recovery');
    };
    assert.strictEqual(context.getCachedMessagePlanActivityParts(planEl), recoveredParts);
  });

  test('duplicate step updates skip child selector and transcript scroll reads', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const stepMessage = {
      id: 'step-1',
      role: 'step',
      step: { status: 'running', mode: 'Build', model: 'step-render-key-secret-' + 'x'.repeat(120) },
      timestamp: Date.now(),
    };

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [stepMessage],
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        processing: true,
      },
    });

    const messages = elements.get('messages');
    assert.ok(messages);
    const stepEl = messages.children.find((child: any) => child && child.dataset && child.dataset.id === 'step-1');
    assert.ok(stepEl, 'expected step message element to be rendered');
    const stepRenderKey = context.getStepRenderKey(stepMessage);
    const expectedStepKeyBuilder = context.createCompactRenderKeyBuilder();
    context.appendCompactRenderKeyPart(expectedStepKeyBuilder, 'running');
    context.appendCompactRenderKeyPart(expectedStepKeyBuilder, 'Build');
    context.appendCompactRenderKeyPart(expectedStepKeyBuilder, stepMessage.step.model);
    assert.strictEqual(stepRenderKey, context.finishCompactRenderKey(expectedStepKeyBuilder));
    assert.ok(stepRenderKey.length < 32, 'step render key should stay compact');
    assert.ok(!stepRenderKey.includes('step-render-key-secret'), 'step render key should not retain raw step model text');
    assert.strictEqual(context.getStepRenderDatasetKey(stepRenderKey), context.getCompactRenderDatasetKey(stepRenderKey));
    assert.strictEqual(stepEl.dataset.stepRenderKey, context.getStepRenderDatasetKey(stepRenderKey));
    assert.strictEqual(context.getRememberedStepRenderKey(stepEl), stepRenderKey);
    assert.ok(!stepEl.dataset.stepRenderKey.includes('Build'));
    assert.ok(!stepEl.dataset.stepRenderKey.includes('step-render-key-secret'));

    const footer = stepEl.children[1];
    const modeEl = footer?.children?.[1];
    const sepEl = footer?.children?.[2];
    const modelEl = footer?.children?.[3];
    assert.ok(modeEl, 'expected step mode element');
    assert.ok(sepEl, 'expected step separator element');
    assert.ok(modelEl, 'expected step model element');

    let stepSelectorCalls = 0;
    stepEl.querySelector = () => {
      stepSelectorCalls++;
      throw new Error('step updates should use cached child controls');
    };
    let scrollHeightReads = 0;
    let clientHeightReads = 0;
    Object.defineProperty(messages, 'scrollHeight', {
      configurable: true,
      get() {
        scrollHeightReads++;
        return 1000;
      },
    });
    Object.defineProperty(messages, 'clientHeight', {
      configurable: true,
      get() {
        clientHeightReads++;
        return 1000;
      },
    });
    messages.scrollTop = 0;

    context.window.dispatchEvent({ type: 'message', data: { type: 'updateMessage', message: stepMessage } });
    assert.strictEqual(stepSelectorCalls, 0, 'duplicate step update should skip child selector lookups');
    assert.strictEqual(clientHeightReads, 0, 'duplicate step update should avoid near-bottom clientHeight reads');
    assert.strictEqual(scrollHeightReads, 0, 'duplicate step update should avoid near-bottom and autoscroll reads');

    const changedStepMessage = {
      ...stepMessage,
      step: { status: 'done', mode: 'Plan', model: 'gpt-test' },
    };
    context.window.dispatchEvent({ type: 'message', data: { type: 'updateMessage', message: changedStepMessage } });
    assert.strictEqual(stepSelectorCalls, 0, 'changed step update should still use cached child controls');
    assert.strictEqual(stepEl.className, 'step done');
    assert.strictEqual(modeEl.textContent, 'Plan');
    assert.strictEqual(modelEl.textContent, 'gpt-test');
    assert.strictEqual(sepEl.style.display || '', '');
    assert.strictEqual(modelEl.style.display || '', '');
    assert.strictEqual(clientHeightReads, 1, 'changed step update should read near-bottom clientHeight once');
    assert.strictEqual(scrollHeightReads, 2, 'changed step update should read once for near-bottom and once for autoscroll');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

	  test('step parts use known message layout before selector fallback', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
	      asWebviewUri: (uri: unknown) => uri,
	    } as unknown as vscode.Webview;

	    const html = controller.webviewApi.getHtml(webview);
	    const scripts = extractOrderedScriptSources(html);
	    const { context } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);

	    assert.strictEqual(typeof context.getCachedMessageStepParts, 'function');
	    const stepEl = createMockElement('step-layout-cache');
	    const body = createMockElement('step-body');
	    const footer = createMockElement('step-footer');
	    const dot = createMockElement('step-dot');
	    const mode = createMockElement('step-mode');
	    const sep = createMockElement('step-sep');
	    const model = createMockElement('step-model');
	    body.classList.add('step-body');
	    footer.classList.add('step-footer');
	    dot.classList.add('step-dot');
	    mode.classList.add('step-mode');
	    sep.classList.add('step-sep');
	    model.classList.add('step-model');
	    footer.appendChild(dot);
	    footer.appendChild(mode);
	    footer.appendChild(sep);
	    footer.appendChild(model);
	    stepEl.appendChild(body);
	    stepEl.appendChild(footer);
	    let containedStepParts = new Set([body, mode, sep, model]);
	    stepEl.contains = (node: unknown) => containedStepParts.has(node as any);

	    let selectorCalls = 0;
	    stepEl.querySelector = () => {
	      selectorCalls++;
	      throw new Error('known step layout should avoid child selectors');
	    };

	    const parts = context.getCachedMessageStepParts(stepEl);

	    assert.strictEqual(parts.body, body);
	    assert.strictEqual(parts.mode, mode);
	    assert.strictEqual(parts.sep, sep);
	    assert.strictEqual(parts.model, model);
	    assert.strictEqual(selectorCalls, 0);
	    assert.strictEqual(context.getCachedMessageStepParts(stepEl), parts);
	    const nextBody = createMockElement('next-step-body');
	    const nextFooter = createMockElement('next-step-footer');
	    const nextDot = createMockElement('next-step-dot');
	    const nextMode = createMockElement('next-step-mode');
	    const nextSep = createMockElement('next-step-sep');
	    const nextModel = createMockElement('next-step-model');
	    nextBody.classList.add('step-body');
	    nextFooter.classList.add('step-footer');
	    nextDot.classList.add('step-dot');
	    nextMode.classList.add('step-mode');
	    nextSep.classList.add('step-sep');
	    nextModel.classList.add('step-model');
	    nextFooter.appendChild(nextDot);
	    nextFooter.appendChild(nextMode);
	    nextFooter.appendChild(nextSep);
	    nextFooter.appendChild(nextModel);
	    stepEl.replaceChildren(nextBody, nextFooter);
	    containedStepParts = new Set([nextBody, nextMode, nextSep, nextModel]);
	    const nextParts = context.getCachedMessageStepParts(stepEl);
	    assert.strictEqual(nextParts.body, nextBody);
	    assert.strictEqual(nextParts.mode, nextMode);
	    assert.strictEqual(nextParts.sep, nextSep);
	    assert.strictEqual(nextParts.model, nextModel);
	    assert.strictEqual(context.getCachedMessageStepParts(stepEl), nextParts);
	    assert.strictEqual(selectorCalls, 0);
	  });

