			    assert.match(html, /\.lsp-location-list\s*\{[\s\S]*?display:\s*flex;[\s\S]*?flex-direction:\s*column;[\s\S]*?gap:\s*6px;/);

		    const rendered = context.formatToolCardBody({
	      id: 'lsp',
	      status: 'success',
	      args: JSON.stringify({ operation: 'references' }),
	      lsp: {
	        operation: 'references',
	        skippedOutsideWorkspace: 2,
	        truncated: true,
	        results: [
	          {
	            filePath: 'src/app.ts',
	            range: { start: { line: 12, character: 3 } },
	          },
	        ],
	      },
	    });

		    assert.match(rendered, /<div class="lsp-location-list" role="list" aria-label="LSP locations">/);
