			    assert.match(invalidRendered, /<div class="lsp-results"><div class="lsp-note" role="note" aria-label="No LSP results">No LSP results<\/div><\/div>/);
			    assert.doesNotMatch(invalidRendered, /\(No LSP results\)/);

			    const longHoverText = 'A'.repeat(4100);
