    const { context } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const lines = Array.from({ length: 130 }, (_, index) => ({
      kind: 'add',
      newLine: index + 1,
      text: 'line ' + String(index + 1),
    }));
    const rendered = context.formatToolCardBody({
      id: 'edit',
      status: 'success',
      approvalId: 'approval-large-diff',
      path: 'src/large.ts',
      diff: '@@ -0,0 +1,130 @@\n' + lines.map(line => '+' + line.text).join('\n'),
      diffView: {
        files: [
          {
            filePath: 'src/large.ts',
            hunks: [
              {
                header: '@@ -0,0 +1,130 @@',
                lines,
              },
            ],
          },
        ],
      },
    });

    assert.strictEqual((rendered.match(/class="tool-diff-row add"/g) || []).length, 120);
	    assert.match(rendered, /line 120/);
	    assert.doesNotMatch(rendered, /line 121/);
	    assert.match(rendered, /Diff preview truncated/);
		    assert.match(rendered, /<div class="tool-more" role="note" aria-label="Diff preview truncated">Diff preview truncated<\/div>/);
