		    assert.doesNotMatch(noPathStructuredRendered, /tool-diff-file-header/);
		    assert.doesNotMatch(noPathStructuredRendered, /tool-diff-hunk-header/);
		    assert.doesNotMatch(noPathStructuredRendered, /data-open-location-id=/);
		    assert.doesNotMatch(noPathStructuredRendered, /\baria-label=""/);

