		  test('consecutive batchable tool messages merge into one visible card', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const firstToolCall = {
      id: 'read',
      name: 'read',
      status: 'completed',
      path: 'src/one.ts',
      result: 'one',
    };
    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [
          { id: 'turn-1', role: 'user', content: 'Read files', timestamp: 1 },
          { id: 'tool-1', role: 'tool', turnId: 'turn-1', toolCall: firstToolCall },
        ],
      },
    });

    const messages = elements.get('messages');
    assert.ok(messages);
    const countByClassName = (node: any, className: string): number => {
      if (!node) return 0;
      let count = node.className === className ? 1 : 0;
      for (const child of node.children || []) {
        count += countByClassName(child, className);
      }
      return count;
    };
    const findById = (node: any, id: string): any => {
      if (!node) return null;
      if (node.dataset?.id === id) return node;
      for (const child of node.children || []) {
        const found = findById(child, id);
        if (found) return found;
      }
      return null;
    };

    const toolEl = findById(messages, 'tool-1');
    assert.ok(toolEl, 'expected first tool card');
    assert.strictEqual(countByClassName(messages, 'tool-message'), 1);

    const cardEl = context.document.createElement('div');
    cardEl.className = context.formatToolCardClass(firstToolCall);
    let cardBody = context.formatToolCardBody(firstToolCall);
    cardEl.innerHTML = cardBody;
    let bodyWriteCount = 0;
    Object.defineProperty(cardEl, 'innerHTML', {
      configurable: true,
      get: () => cardBody,
      set: (value: unknown) => {
        bodyWriteCount++;
        cardBody = String(value);
      },
    });
	    assert.strictEqual(typeof context.rememberMessageToolCardElement, 'function');
	    context.rememberMessageToolCardElement(toolEl, cardEl);
	    toolEl.querySelector = () => {
	      throw new Error('batch tool card update should use the cached card element');
	    };

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'message',
        message: {
          id: 'tool-2',
          role: 'tool',
          turnId: 'turn-1',
	          toolCall: { id: 'read', name: 'read', status: 'completed', path: 'src/two.ts', result: 'two' },
	        },
	      },
	    });

    assert.strictEqual(countByClassName(messages, 'tool-message'), 1, 'expected second read to merge into the first card');
    assert.strictEqual(bodyWriteCount, 1, 'expected one visible card body update for the new file');
    assert.match(cardBody, /Read Files \(2\)/);
    assert.match(cardBody, /src\/one\.ts/);
	    assert.match(cardBody, /src\/two\.ts/);

	    let scrollHeightReads = 0;
	    let clientHeightReads = 0;
    Object.defineProperty(messages, 'scrollHeight', {
      configurable: true,
      get() {
        scrollHeightReads++;
        return 1000;
      },
    });
    Object.defineProperty(messages, 'clientHeight', {
      configurable: true,
      get() {
        clientHeightReads++;
        return 100;
      },
    });
    messages.scrollTop = 0;
    const empty = elements.get('empty');
    let emptyDisplayReads = 0;
    let emptyDisplayWrites = 0;
    let emptyDisplayValue = 'none';
    Object.defineProperty(empty.style, 'display', {
      configurable: true,
      get() {
        emptyDisplayReads++;
        return emptyDisplayValue;
      },
      set(value: unknown) {
        emptyDisplayWrites++;
        emptyDisplayValue = String(value);
      },
    });

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'message',
        message: {
          id: 'tool-3',
          role: 'tool',
          turnId: 'turn-1',
          toolCall: { id: 'read', name: 'read', status: 'completed', path: 'src/two.ts', result: 'two again' },
        },
      },
    });

    assert.strictEqual(countByClassName(messages, 'tool-message'), 1, 'expected duplicate read path to reuse the existing card');
    assert.strictEqual(bodyWriteCount, 1, 'duplicate path should not rewrite the card body');
    assert.strictEqual(scrollHeightReads, 0, 'duplicate batch path should not read transcript scrollHeight');
    assert.strictEqual(clientHeightReads, 0, 'duplicate batch path should not read transcript clientHeight');
    assert.strictEqual(emptyDisplayReads, 0, 'duplicate batch path should not check empty-state display');
	    assert.strictEqual(emptyDisplayWrites, 0, 'duplicate batch path should not rewrite empty-state display');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

