  test('single queue item render skips fragment allocation', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    let fragmentCalls = 0;
    const originalCreateDocumentFragment = context.document.createDocumentFragment;
    context.document.createDocumentFragment = () => {
      fragmentCalls++;
      return originalCreateDocumentFragment.call(context.document);
    };
    runScriptsInMockBrowser(scripts, context);
    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [] } });
    fragmentCalls = 0;

    const queueItems = elements.get('queueItems');
    assert.ok(queueItems, 'expected queue items to be available');
    let queueItemsAppendWrites = 0;
    let queueItemsReplaceWrites = 0;
    let lastReplaceChildCount = 0;
    const originalQueueItemsAppendChild = queueItems.appendChild;
    const originalQueueItemsReplaceChildren = queueItems.replaceChildren;
    queueItems.appendChild = function appendChild(child: any) {
      queueItemsAppendWrites++;
      return originalQueueItemsAppendChild.call(this, child);
    };
    queueItems.replaceChildren = function replaceChildren(...children: unknown[]) {
      queueItemsReplaceWrites++;
      lastReplaceChildCount = children.length;
      return originalQueueItemsReplaceChildren.call(this, ...children);
    };

    context.setQueueState([{ id: 'q1', displayContent: 'first queued message', attachmentCount: 0 }]);
    assert.strictEqual(fragmentCalls, 0, 'single queue item should replace directly without fragment allocation');
    assert.strictEqual(queueItemsAppendWrites, 0, 'single queue item should avoid direct live appends');
    assert.strictEqual(queueItemsReplaceWrites, 1, 'single queue item should replace queue rows once');
    assert.strictEqual(lastReplaceChildCount, 1, 'single queue item should replace with the button directly');
    assert.strictEqual(queueItems.children.length, 1);
    assert.strictEqual(queueItems.children[0].className, 'queue-item');
    assert.strictEqual(queueItems.children[0].children[0].children[1].textContent, 'first queued message');

    fragmentCalls = 0;
    context.setQueueState([
      { id: 'q1', displayContent: 'first queued message', attachmentCount: 0 },
      { id: 'q2', displayContent: 'second queued message', attachmentCount: 1 },
    ]);
    assert.strictEqual(fragmentCalls, 1, 'multiple queue items should batch through one fragment');
    assert.strictEqual(queueItemsAppendWrites, 0, 'multiple queue items should still avoid direct live appends');
    assert.strictEqual(queueItemsReplaceWrites, 2, 'multiple queue items should replace queue rows once');
    assert.strictEqual(lastReplaceChildCount, 1, 'multiple queue items should replace with the fragment batch');
    assert.strictEqual(queueItems.children.length, 2);
    assert.strictEqual(queueItems.children[1].children[0].children[1].textContent, 'second queued message');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

  test('queue renderer skips duplicate DOM rebuilds for identical queue state', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted, getCreatedCount } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    assert.strictEqual(typeof context.setQueueState, 'function');
	    const queuedInputs = [{ id: 'q1', displayContent: 'queued message preview', attachmentCount: 1 }];
	    const before = getCreatedCount();
	    context.setQueueState(queuedInputs);
	    const afterFirst = getCreatedCount();
	    const queueBanner = elements.get('queueBanner');
	    const queueBannerCount = elements.get('queueBannerCount');
	    const queueBannerText = elements.get('queueBannerText');
	    const queueBannerHint = elements.get('queueBannerHint');
	    const queueStatus = elements.get('queueStatus');
	    const queueClearBtn = elements.get('queueClear');
	    assert.ok(queueBanner, 'expected queue banner to be available');
	    assert.ok(queueStatus, 'expected queue status to be available');
	    assert.ok(queueClearBtn, 'expected queue clear button to be available');
	    assert.strictEqual(queueStatus.textContent, '1 queued. Queued messages ready to run.');

	    let queueClearDisabledReadCount = 0;
	    let queueClearDisabledWriteCount = 0;
	    let queueClearDisabled = !!queueClearBtn.disabled;
	    Object.defineProperty(queueClearBtn, 'disabled', {
	      configurable: true,
	      get: () => {
	        queueClearDisabledReadCount++;
	        return queueClearDisabled;
	      },
	      set: (value: unknown) => {
	        queueClearDisabledWriteCount++;
	        queueClearDisabled = !!value;
	      },
    });

			    let bannerClassWriteCount = 0;
			    const originalBannerAdd = queueBanner.classList.add;
			    const originalBannerRemove = queueBanner.classList.remove;
			    const originalBannerToggle = queueBanner.classList.toggle;
			    const originalBannerContains = queueBanner.classList.contains;
			    let bannerClassReadCount = 0;
			    queueBanner.classList.add = (...names: string[]) => {
			      if (names.includes('hidden')) bannerClassWriteCount++;
			      return originalBannerAdd(...names);
			    };
			    queueBanner.classList.remove = (...names: string[]) => {
			      if (names.includes('hidden')) bannerClassWriteCount++;
			      return originalBannerRemove(...names);
			    };
			    queueBanner.classList.toggle = (name: string, force?: boolean) => {
			      if (name === 'hidden') bannerClassWriteCount++;
			      return originalBannerToggle(name, force);
			    };
			    queueBanner.classList.contains = (name: string) => {
			      if (name === 'hidden') bannerClassReadCount++;
			      return originalBannerContains(name);
			    };

	    let bannerTextWriteCount = 0;
	    for (const bannerTextEl of [queueBannerCount, queueBannerText, queueBannerHint]) {
	      let textValue = String(bannerTextEl.textContent || '');
	      Object.defineProperty(bannerTextEl, 'textContent', {
	        configurable: true,
	        get: () => textValue,
	        set: (value: unknown) => {
	          bannerTextWriteCount++;
	          textValue = String(value);
	        },
	      });
	    }
	    let queueStatusText = String(queueStatus.textContent || '');
	    let queueStatusWriteCount = 0;
	    Object.defineProperty(queueStatus, 'textContent', {
	      configurable: true,
	      get: () => queueStatusText,
	      set(value: unknown) {
	        queueStatusWriteCount++;
	        queueStatusText = String(value);
	      },
    });

	    context.setQueueState(queuedInputs);
	    const afterSecond = getCreatedCount();
	    const queueItems = elements.get('queueItems');
	    assert.ok(queueItems, 'expected queue items to be available');

	    let queueItemsInnerHtml = queueItems.innerHTML || '';
	    let queueItemsClearWrites = 0;
	    Object.defineProperty(queueItems, 'innerHTML', {
	      configurable: true,
	      get: () => queueItemsInnerHtml,
	      set(value: unknown) {
	        queueItemsInnerHtml = String(value);
	        if (queueItemsInnerHtml === '') {
	          queueItemsClearWrites++;
	          queueItems.children = [];
	          queueItems.firstChild = null;
	        }
	      },
    });
		    let queueItemsAppendWrites = 0;
		    let queueItemsReplaceWrites = 0;
		    const originalQueueItemsAppendChild = queueItems.appendChild;
		    const originalQueueItemsReplaceChildren = queueItems.replaceChildren;
		    queueItems.appendChild = function appendChild(child: any) {
		      queueItemsAppendWrites++;
		      return originalQueueItemsAppendChild.call(this, child);
		    };
		    queueItems.replaceChildren = function replaceChildren(...children: unknown[]) {
		      queueItemsReplaceWrites++;
		      return originalQueueItemsReplaceChildren.call(this, ...children);
		    };

	    const queueButton = queueItems.children[0];
	    const queueLabel = queueButton?.children?.[0]?.children?.[0];
	    assert.ok(queueButton, 'expected queue button to be rendered');
	    assert.ok(queueLabel, 'expected queue item label to be rendered');
	    assert.strictEqual(queueButton.dataset.id, undefined);
	    let queueButtonDatasetIdReads = 0;
	    let queueButtonDatasetIdWrites = 0;
	    Object.defineProperty(queueButton.dataset, 'id', {
	      configurable: true,
	      get() {
	        queueButtonDatasetIdReads++;
	        return undefined;
	      },
	      set() {
	        queueButtonDatasetIdWrites++;
	      },
	    });
	    let queueLabelText = String(queueLabel.textContent || '');
	    let queueLabelWriteCount = 0;
	    Object.defineProperty(queueLabel, 'textContent', {
	      configurable: true,
	      get: () => queueLabelText,
	      set(value: unknown) {
	        queueLabelWriteCount++;
	        queueLabelText = String(value);
	      },
    });
	    let queueButtonTitle = String(queueButton.title || '');
	    let queueButtonTitleWriteCount = 0;
	    Object.defineProperty(queueButton, 'title', {
	      configurable: true,
	      get: () => queueButtonTitle,
	      set(value: unknown) {
	        queueButtonTitleWriteCount++;
	        queueButtonTitle = String(value);
	      },
    });
	    let queueButtonAriaLabelWriteCount = 0;
	    const originalQueueButtonSetAttribute = queueButton.setAttribute;
	    queueButton.setAttribute = function setAttribute(name: string, value: unknown) {
	      if (name === 'aria-label') queueButtonAriaLabelWriteCount++;
	      return originalQueueButtonSetAttribute.call(this, name, value);
	    };

	    assert.strictEqual(queueItems?.children.length, 1);
	    assert.strictEqual(queueButton.getAttribute('aria-label'), 'Run now: queued message preview, 1 image attached');
	    assert.ok(afterFirst > before, 'expected first queue render to create DOM nodes');
	    assert.strictEqual(afterSecond, afterFirst, 'expected duplicate queue state to skip DOM creation');
	    assert.strictEqual(bannerClassWriteCount, 0, 'expected duplicate queue state to skip live banner class writes');
	    assert.strictEqual(bannerClassReadCount, 0, 'expected duplicate queue state to skip live banner class reads');
	    assert.strictEqual(bannerTextWriteCount, 0, 'expected duplicate queue state to skip live banner text writes');
	    assert.strictEqual(queueStatusWriteCount, 0, 'expected duplicate queue state to skip status announcements');
	    assert.strictEqual(queueClearDisabledWriteCount, 0, 'expected duplicate queue state to skip queue clear disabled writes');

	    const input = elements.get('input');
	    assert.ok(input, 'expected composer input to be available');
	    let inputDisabledReadCount = 0;
	    let inputDisabled = !!input.disabled;
	    Object.defineProperty(input, 'disabled', {
	      configurable: true,
	      get: () => {
	        inputDisabledReadCount++;
	        return inputDisabled;
	      },
	      set: (value: unknown) => {
	        inputDisabled = !!value;
	      },
	    });
	    queueClearDisabledReadCount = 0;
	    context.window.dispatchEvent({ type: 'message', data: { type: 'queueState', queuedInputs } });
	    assert.strictEqual(queueClearDisabledReadCount, 0, 'duplicate idle queueState should skip queue clear disabled reads');
	    assert.strictEqual(inputDisabledReadCount, 0, 'duplicate idle queueState should skip composer control sync reads');

		    context.setProcessing(true);
		    assert.strictEqual(bannerClassWriteCount, 0, 'visible processing state changes should not rewrite banner visibility');
		    assert.strictEqual(bannerClassReadCount, 0, 'visible processing state changes should not reread banner visibility');
		    assert.strictEqual(bannerTextWriteCount, 2, 'processing state changes should update only banner text and hint');
		    assert.strictEqual(queueStatusWriteCount, 1, 'processing state changes should update the queue status once');
		    assert.strictEqual(queueStatusText, '1 queued. Queued for the next step.');
		    assert.strictEqual(queueClearDisabledWriteCount, 0, 'processing without queue action changes should not rewrite queue clear disabled state');
		    assert.strictEqual(queueItemsClearWrites, 0, 'processing should not clear existing queue rows');
		    assert.strictEqual(queueItemsAppendWrites, 0, 'processing should not append existing queue rows');
		    assert.strictEqual(queueButtonDatasetIdReads, 0, 'processing should not read queue ids from dataset');
		    assert.strictEqual(queueButtonDatasetIdWrites, 0, 'processing should not mirror queue ids into dataset');
		    assert.strictEqual(queueLabelText, 'Steer now');
		    assert.strictEqual(queueLabelWriteCount, 1, 'processing should update the visible queue item label once');
		    assert.strictEqual(queueButtonTitle, 'Steer this queued message now');
		    assert.strictEqual(queueButtonTitleWriteCount, 1, 'processing should update the visible queue item title once');
		    assert.strictEqual(queueButton.getAttribute('aria-label'), 'Steer now: queued message preview, 1 image attached');
		    assert.strictEqual(queueButtonAriaLabelWriteCount, 1, 'processing should update the visible queue item accessible label once');

		    context.setProcessing(true);
		    assert.strictEqual(bannerClassReadCount, 0, 'unchanged processing should not reread banner visibility');
		    assert.strictEqual(queueItemsClearWrites, 0, 'unchanged processing should not clear existing queue rows');
		    assert.strictEqual(queueItemsAppendWrites, 0, 'unchanged processing should not append existing queue rows');
		    assert.strictEqual(queueLabelWriteCount, 1, 'unchanged processing should not rewrite the queue item label');
		    assert.strictEqual(queueButtonTitleWriteCount, 1, 'unchanged processing should not rewrite the queue item title');
		    assert.strictEqual(queueButtonAriaLabelWriteCount, 1, 'unchanged processing should not rewrite the queue item accessible label');
		    assert.strictEqual(queueStatusWriteCount, 1, 'unchanged processing should not rewrite the queue status');

			    context.setQueueState([
			      ...queuedInputs,
			      { id: 'q2', displayContent: 'second queued message preview', attachmentCount: 0 },
			    ]);
			    assert.strictEqual(queueItems?.children.length, 2);
			    assert.strictEqual(queueItemsReplaceWrites, 1, 'queue count changes should replace queue rows once');
			    assert.strictEqual(queueItemsClearWrites, 0, 'queue count changes should avoid innerHTML clears');
			    assert.strictEqual(queueItemsAppendWrites, 0, 'queue count changes should avoid direct queue appends');
			    assert.strictEqual(bannerClassWriteCount, 0, 'visible queue count changes should not rewrite banner visibility');
		    assert.strictEqual(bannerClassReadCount, 0, 'visible queue count changes should not reread banner visibility');
		    assert.strictEqual(bannerTextWriteCount, 3, 'queue count changes should update only the count text');
		    assert.strictEqual(queueStatusWriteCount, 2, 'queue count changes should update the queue status once');
		    assert.strictEqual(queueStatusText, '2 queued. Queued for the next step.');

			    let queueFragmentCalls = 0;
			    const originalCreateDocumentFragment = context.document.createDocumentFragment;
			    context.document.createDocumentFragment = () => {
			      queueFragmentCalls++;
			      return originalCreateDocumentFragment();
			    };
			    context.setQueueState([]);
			    assert.strictEqual(queueFragmentCalls, 0, 'empty queue render should clear rows without allocating a fragment');
			    assert.strictEqual(queueItemsReplaceWrites, 2, 'empty queue should replace queue rows once');
			    assert.strictEqual(queueItemsClearWrites, 0, 'empty queue should avoid innerHTML clears');
			    assert.strictEqual(queueItemsAppendWrites, 0, 'empty queue should avoid direct queue appends');
			    assert.strictEqual(bannerClassWriteCount, 1, 'empty queue should hide the banner once');
		    assert.strictEqual(bannerClassReadCount, 0, 'empty queue should not reread banner visibility before hiding');
		    assert.strictEqual(bannerTextWriteCount, 3, 'empty queue should not rewrite stale hidden banner text');
		    assert.strictEqual(queueStatusWriteCount, 3, 'empty queue should update the queue status once');
		    assert.strictEqual(queueStatusText, 'No queued messages.');

		    context.setProcessing(false);
		    assert.strictEqual(bannerClassWriteCount, 1, 'hidden processing state changes should not rewrite banner visibility');
		    assert.strictEqual(bannerClassReadCount, 0, 'hidden processing state changes should not reread banner visibility');
		    assert.strictEqual(bannerTextWriteCount, 3, 'hidden processing state changes should not rewrite banner text');
		    assert.strictEqual(queueStatusWriteCount, 3, 'hidden processing state changes should not rewrite queue status text');
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

