  test('queue item label cache refreshes stale label after subtree replacement', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    context.setQueueState([{ id: 'queued-stale-label', displayContent: 'queued message preview', attachmentCount: 0 }]);

    const queueItems = elements.get('queueItems');
    assert.ok(queueItems, 'expected queue items to be available');
    const queueButton = queueItems.children.find((child: any) => child.className === 'queue-item');
    assert.ok(queueButton, 'expected queue button to be rendered');
    const staleLabel = queueButton.children?.[0]?.children?.find((child: any) => child.className === 'queue-item-label');
    assert.ok(staleLabel, 'expected queue item label to be rendered');

    let staleLabelText = String(staleLabel.textContent || '');
    let staleLabelWrites = 0;
    Object.defineProperty(staleLabel, 'textContent', {
      configurable: true,
      get: () => staleLabelText,
      set(value: unknown) {
        staleLabelWrites++;
        staleLabelText = String(value);
      },
    });

    const nextBody = createMockElement('queue-item-body');
    nextBody.className = 'queue-item-body';
    const nextLabel = createMockElement('queue-item-label');
    nextLabel.className = 'queue-item-label';
    nextLabel.textContent = 'Run now';
    const nextText = createMockElement('queue-item-text');
    nextText.className = 'queue-item-text';
    nextText.textContent = 'queued message preview';
    nextBody.appendChild(nextLabel);
    nextBody.appendChild(nextText);
    nextBody.firstElementChild = nextLabel;
    queueButton.replaceChildren(nextBody);
    queueButton.firstElementChild = nextBody;

    let nextLabelText = String(nextLabel.textContent || '');
    let nextLabelWrites = 0;
    Object.defineProperty(nextLabel, 'textContent', {
      configurable: true,
      get: () => nextLabelText,
      set(value: unknown) {
        nextLabelWrites++;
        nextLabelText = String(value);
      },
    });

    let containsChecks = 0;
    queueButton.contains = (node: unknown) => {
      containsChecks++;
      return node === nextBody || node === nextLabel || node === nextText;
    };

    context.setProcessing(true);
    assert.strictEqual(staleLabelWrites, 0, 'processing update should not write into the detached queue label');
    assert.strictEqual(nextLabelText, 'Steer now');
    assert.strictEqual(nextLabelWrites, 1, 'processing update should refresh and write the visible queue label once');
    assert.strictEqual(containsChecks, 1, 'stale cached queue label should be checked with button.contains once');

    context.setProcessing(false);
    assert.strictEqual(nextLabelText, 'Run now');
    assert.strictEqual(nextLabelWrites, 2, 'cached refreshed queue label should be reused for later action updates');
    assert.strictEqual(containsChecks, 2, 'refreshed cached queue label should be validated before reuse');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

