  test('queue action failure notice syncs composer once through queue recovery', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    context.acquireVsCodeApi = () => ({
      postMessage: (message: any) => {
        if (message && message.type === 'clearQueue') throw new Error('queue clear failed');
        posted.push(message);
      },
    });
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [],
        sessions: [{ id: 'session-1', title: 'Session 1' }],
        activeSessionId: 'session-1',
        processing: false,
      },
    });

    assert.strictEqual(typeof context.setQueueState, 'function');
    context.setQueueState([{ id: 'q1', displayContent: 'queued message preview', attachmentCount: 0 }]);

    const input = elements.get('input');
    const inputHint = elements.get('inputHint');
    const queueClear = elements.get('queueClear');
    assert.ok(input, 'expected composer input to be created during startup');
    assert.ok(inputHint, 'expected input hint to be created during startup');
    assert.ok(queueClear, 'expected queue clear button to be created during startup');

    let inputDisabled = !!input.disabled;
    let inputDisabledReads = 0;
    let inputDisabledWrites = 0;
    Object.defineProperty(input, 'disabled', {
      configurable: true,
      get() {
        inputDisabledReads++;
        return inputDisabled;
      },
      set(value: unknown) {
        inputDisabledWrites++;
        inputDisabled = !!value;
      },
    });

    queueClear.dispatchEvent({ type: 'click' });

    assert.strictEqual(inputHint.textContent, 'Failed to request queue clear.');
    assert.strictEqual(inputDisabledReads, 2, 'pending queue sync plus recovery queue sync should read composer disabled state once each');
    assert.strictEqual(inputDisabledWrites, 0, 'queue clear failure should keep composer disabled state unchanged');
    assert.ok(!posted.some(message => message && message.type === 'clearQueue'));
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

  test('queue renderer caps visible rows and batches large queue insertion', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const bootstrapSource = scripts.find(script => script.label === 'bootstrap.js')?.source || '';
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    assert.strictEqual(typeof context.setQueueState, 'function');
    assert.strictEqual(typeof context.getQueueInputsRenderState, 'function');
    assert.strictEqual(typeof context.createCompactRenderStateKeyBuilder, 'function');
    assert.strictEqual(typeof context.appendCompactRenderStateKeyPart, 'function');
    assert.strictEqual(typeof context.finishCompactRenderStateKey, 'function');
    assert.match(bootstrapSource, /QUEUE_ITEMS_RENDER_LIMIT\s*=\s*24/);
    assert.doesNotMatch(bootstrapSource, /JSON\.stringify\(renderItems\)/);
    const longQueueState = context.getQueueInputsRenderState([{
      id: 'long-queued',
      displayContent: 'queue-key-secret-' + 'x'.repeat(140),
      attachmentCount: 1,
    }]);
    const longQueueRenderBase = longQueueState.visibleRenderBases[0];
    const expectedLongQueueKeyBuilder = context.createCompactRenderStateKeyBuilder();
    context.appendCompactRenderStateKeyPart(expectedLongQueueKeyBuilder, 1);
    context.appendCompactRenderStateKeyPart(expectedLongQueueKeyBuilder, longQueueRenderBase.id);
    context.appendCompactRenderStateKeyPart(expectedLongQueueKeyBuilder, longQueueRenderBase.preview);
    context.appendCompactRenderStateKeyPart(expectedLongQueueKeyBuilder, longQueueRenderBase.attachmentCount);
    context.appendCompactRenderStateKeyPart(expectedLongQueueKeyBuilder, longQueueState.renderableCount);
    assert.strictEqual(longQueueState.key, context.finishCompactRenderStateKey(expectedLongQueueKeyBuilder));
    assert.ok(longQueueState.key.length < 32, 'queue input render key should be compact');
    assert.ok(!longQueueState.key.includes('queue-key-secret'), 'queue input render key should not retain visible preview text');

    const queueItems = elements.get('queueItems');
    assert.ok(queueItems);

	    let liveAppendCount = 0;
	    let liveReplaceCount = 0;
	    const originalAppendChild = queueItems.appendChild;
	    const originalReplaceChildren = queueItems.replaceChildren;
	    queueItems.appendChild = function appendChild(child: any) {
	      liveAppendCount++;
	      return originalAppendChild.call(this, child);
	    };
	    queueItems.replaceChildren = function replaceChildren(...children: unknown[]) {
	      liveReplaceCount++;
	      return originalReplaceChildren.call(this, ...children);
	    };

    let visiblePreviewReads = 0;
    const queuedInputs = Array.from({ length: 150 }, (_unused, index) => {
      const item: any = {
        id: 'queued-' + index,
        attachmentCount: index % 3,
      };
      if (index < 24) {
        Object.defineProperty(item, 'displayContent', {
          get() {
            visiblePreviewReads++;
            return 'queued message preview ' + index;
          },
        });
      } else {
        Object.defineProperty(item, 'displayContent', {
          get() {
            throw new Error('hidden queue item preview should not be read');
          },
        });
      }
      return item;
    });

    context.setQueueState(queuedInputs);
    const rows = queueItems.children.filter((child: any) => child.className === 'queue-item');
    const overflow = queueItems.children.find((child: any) => child.className === 'queue-overflow');

		    assert.strictEqual(rows.length, 24);
		    assert.strictEqual(visiblePreviewReads, 24, 'expected first large queue render to normalize each visible preview once');
		    assert.strictEqual(overflow?.textContent, 'Showing 24 of 150 queued messages.');
		    assert.strictEqual(overflow?.getAttribute('role'), 'note');
		    assert.strictEqual(overflow?.getAttribute('aria-label'), 'Showing 24 of 150 queued messages.');
		    assert.strictEqual(liveReplaceCount, 1, 'expected large queue render to replace children once');
	    assert.strictEqual(liveAppendCount, 0, 'expected large queue render to avoid direct live appends');

	    let renderedQueueChildren = queueItems.children;
	    let queueChildrenReads = 0;
	    Object.defineProperty(queueItems, 'children', {
	      configurable: true,
	      get: () => {
	        queueChildrenReads++;
	        return renderedQueueChildren;
	      },
	      set: (next: any) => {
	        renderedQueueChildren = next;
	      },
	    });
	    visiblePreviewReads = 0;
	    context.setQueueState(queuedInputs);
	    assert.strictEqual(visiblePreviewReads, 24, 'expected duplicate large queue state to normalize visible previews once for key comparison');
	    assert.strictEqual(queueChildrenReads, 0, 'expected duplicate large queue state to skip live row control sync');
	    assert.strictEqual(liveReplaceCount, 1, 'expected duplicate large queue state to skip DOM replacement');
	    assert.strictEqual(liveAppendCount, 0, 'expected duplicate large queue state to avoid direct live appends');

	    let changedVisiblePreviewReads = 0;
	    const changedQueuedInputs = Array.from({ length: 150 }, (_unused, index) => {
	      const item: any = {
	        id: 'changed-queued-' + index,
	        attachmentCount: index % 2,
	      };
	      if (index < 24) {
	        Object.defineProperty(item, 'displayContent', {
	          get() {
	            changedVisiblePreviewReads++;
	            return 'changed queued message preview ' + index;
	          },
	        });
	      } else {
	        Object.defineProperty(item, 'displayContent', {
	          get() {
	            throw new Error('hidden changed queue item preview should not be read');
	          },
	        });
	      }
	      return item;
	    });
	    context.window.dispatchEvent({ type: 'message', data: { type: 'queueState', queuedInputs: changedQueuedInputs } });
	    assert.strictEqual(changedVisiblePreviewReads, 24, 'changed queueState should reuse one normalized visible preview set for keying and rendering');
	    assert.strictEqual(liveReplaceCount, 2, 'changed queueState should replace rows once');
	    assert.strictEqual(liveAppendCount, 0, 'changed queueState should still avoid direct live appends');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

	  test('send button presentation skips duplicate DOM rebuilds for identical input state', () => {
	    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted, getCreatedCount } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    assert.strictEqual(typeof context.syncInputState, 'function');
    const send = elements.get('send');
    assert.strictEqual(send?.children.length, 2);
    let sendInnerHtml = send.innerHTML || '';
    let sendClearWrites = 0;
    Object.defineProperty(send, 'innerHTML', {
      configurable: true,
      get: () => sendInnerHtml,
      set(value: unknown) {
        sendInnerHtml = String(value);
        if (sendInnerHtml === '') {
          sendClearWrites++;
          send.children = [];
          send.firstChild = null;
        }
      },
    });
    let sendAppendWrites = 0;
    let sendReplaceWrites = 0;
    const originalSendAppendChild = send.appendChild;
    const originalSendReplaceChildren = send.replaceChildren;
    send.appendChild = function appendChild(child: unknown) {
      sendAppendWrites++;
      return originalSendAppendChild.call(this, child);
    };
    send.replaceChildren = function replaceChildren(...children: unknown[]) {
      sendReplaceWrites++;
      return originalSendReplaceChildren.call(this, ...children);
    };
    const before = getCreatedCount();
    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });
    const afterChanged = getCreatedCount();
    assert.ok(afterChanged > before, 'expected changed send button state to create replacement nodes');
    assert.strictEqual(sendReplaceWrites, 1, 'expected changed send button presentation to replace children once');
    assert.strictEqual(sendClearWrites, 0, 'expected changed send button presentation to avoid innerHTML clears');
    assert.strictEqual(sendAppendWrites, 0, 'expected changed send button presentation to avoid direct button appends');

    context.syncInputState();
    const afterFirst = getCreatedCount();
    context.syncInputState();
    const afterSecond = getCreatedCount();

    assert.strictEqual(afterFirst, afterChanged, 'expected unchanged send button state to reuse existing nodes');
    assert.strictEqual(afterSecond, afterChanged, 'expected duplicate send button state to skip DOM creation');
    assert.strictEqual(sendReplaceWrites, 1, 'expected duplicate send button state to skip child replacement');
    assert.strictEqual(sendClearWrites, 0, 'expected duplicate send button state to avoid innerHTML clears');
    assert.strictEqual(sendAppendWrites, 0, 'expected duplicate send button state to avoid direct button appends');

    let sendFragmentCalls = 0;
    const originalCreateDocumentFragment = context.document.createDocumentFragment;
    context.document.createDocumentFragment = () => {
      sendFragmentCalls++;
      return originalCreateDocumentFragment();
    };
    context.setProcessing(true);
    assert.strictEqual(sendFragmentCalls, 0, 'changed send button presentation should use replaceChildren without fragment allocation');
    assert.strictEqual(sendReplaceWrites, 2, 'processing send button presentation should replace children once');
    assert.strictEqual(sendClearWrites, 0, 'processing send button presentation should avoid innerHTML clears');
    assert.strictEqual(sendAppendWrites, 0, 'processing send button presentation should avoid direct button appends');
    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
  });

