	  test('input hint skips duplicate DOM updates for unchanged state', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });

    const inputHint = elements.get('inputHint');
    assert.ok(inputHint, 'expected input hint element to be created during startup');
    assert.strictEqual(typeof context.syncInputState, 'function');
    assert.strictEqual(typeof context.setQueueState, 'function');
    assert.strictEqual(typeof context.setProcessing, 'function');

	    let hiddenClassWrites = 0;
	    const originalAdd = inputHint.classList.add;
	    const originalContains = inputHint.classList.contains;
	    const originalRemove = inputHint.classList.remove;
	    const originalToggle = inputHint.classList.toggle;
	    let hiddenClassReads = 0;
	    inputHint.classList.add = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalAdd(...names);
	    };
	    inputHint.classList.contains = (name: string) => {
	      if (name === 'hidden') hiddenClassReads++;
	      return originalContains(name);
	    };
	    inputHint.classList.remove = (...names: string[]) => {
	      if (names.includes('hidden')) hiddenClassWrites++;
	      return originalRemove(...names);
	    };
	    inputHint.classList.toggle = (name: string, force?: boolean) => {
	      if (name === 'hidden') hiddenClassWrites++;
	      return originalToggle(name, force);
	    };

    let textValue = String(inputHint.textContent || '');
    let textWriteCount = 0;
    Object.defineProperty(inputHint, 'textContent', {
      configurable: true,
      get: () => textValue,
      set: (value: unknown) => {
        textWriteCount++;
        textValue = String(value);
      },
    });

    context.syncInputState();
    context.syncInputState();
    assert.strictEqual(hiddenClassWrites, 0, 'unchanged visible hint should not rewrite visibility');
    assert.strictEqual(hiddenClassReads, 0, 'unchanged visible hint should not reread visibility');
    assert.strictEqual(textWriteCount, 0, 'unchanged visible hint should not rewrite text');

    context.setQueueState([{ id: 'queued-1', text: 'queued message' }]);
    assert.strictEqual(hiddenClassWrites, 1, 'hiding the hint should write visibility once');
    assert.strictEqual(hiddenClassReads, 0, 'hiding the hint should not reread visibility');
    assert.strictEqual(textWriteCount, 0, 'hiding the hint should not rewrite preserved text');

    context.syncInputState();
    context.syncInputState();
    assert.strictEqual(hiddenClassWrites, 1, 'unchanged hidden hint should not rewrite visibility');
    assert.strictEqual(hiddenClassReads, 0, 'unchanged hidden hint should not reread visibility');
    assert.strictEqual(textWriteCount, 0, 'unchanged hidden hint should not rewrite text');

    context.setQueueState([]);
    assert.strictEqual(hiddenClassWrites, 2, 'showing the preserved hint should write visibility once');
    assert.strictEqual(hiddenClassReads, 0, 'showing the preserved hint should not reread visibility');
    assert.strictEqual(textWriteCount, 0, 'showing unchanged preserved hint should not rewrite text');

    context.setProcessing(true);
    assert.strictEqual(textWriteCount, 1, 'changed processing hint should rewrite text once');

    context.syncInputState();
    context.syncInputState();
	    assert.strictEqual(textWriteCount, 1, 'unchanged processing hint should not rewrite text');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

