		      element.classList.add('hidden');
		      let hiddenReads = 0;
		      let hiddenWrites = 0;
		      const originalContains = element.classList.contains;
		      const originalAdd = element.classList.add;
		      const originalRemove = element.classList.remove;
		      const originalToggle = element.classList.toggle;
		      element.classList.contains = (name: string) => {
		        if (name === 'hidden') hiddenReads++;
		        return originalContains(name);
		      };
		      element.classList.add = (...names: string[]) => {
		        if (names.includes('hidden')) hiddenWrites++;
		        return originalAdd(...names);
		      };
		      element.classList.remove = (...names: string[]) => {
		        if (names.includes('hidden')) hiddenWrites++;
		        return originalRemove(...names);
		      };
		      element.classList.toggle = (name: string, force?: boolean) => {
		        if (name === 'hidden') hiddenWrites++;
		        return originalToggle(name, force);
		      };

