	    const { context, elements, posted } = createMockBrowserContext();
	    runScriptsInMockBrowser(scripts, context);
	    elements.get('outputModal')?.classList.add('hidden');
	    const timeoutCallbacks: Array<() => void> = [];
	    context.setTimeout = (callback: () => void) => {
	      timeoutCallbacks.push(callback);
	      return timeoutCallbacks.length;
	    };

	    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });

		    const focusOrder: string[] = [];
		    const focusEvents: Array<{ id: string; options: unknown }> = [];
		    const installFocus = (id: string) => {
		      const element = elements.get(id);
		      assert.ok(element, `expected ${id} to be created during startup`);
		      element.focus = (options?: unknown) => {
		        context.document.activeElement = element;
		        focusOrder.push(id);
		        focusEvents.push({ id, options });
		      };
		      element.contains = (target: unknown) => target === element;
		      return element;
	    };

	    const input = installFocus('input');
	    const modelPicker = installFocus('modelPicker');
	    const popovers = [
	      {
	        name: 'provider settings',
	        element: elements.get('providerSettingsPopover'),
	        trigger: installFocus('providerSettings'),
	        closeControl: installFocus('providerSettingsClose'),
	        open: 'openProviderSettingsPopover',
	        close: 'closeProviderSettingsPopover',
	      },
	      {
	        name: 'session settings',
	        element: elements.get('sessionSettingsPopover'),
	        trigger: installFocus('sessionSettings'),
	        closeControl: installFocus('sessionSettingsClose'),
	        open: 'openSessionSettingsPopover',
	        close: 'closeSessionSettingsPopover',
	      },
	      {
	        name: 'safety settings',
	        element: elements.get('safetySettingsPopover'),
	        trigger: installFocus('safetySettings'),
	        closeControl: installFocus('safetySettingsClose'),
	        open: 'openSafetySettingsPopover',
	        close: 'closeSafetySettingsPopover',
	      },
	      {
	        name: 'skills settings',
	        element: elements.get('skillsSettingsPopover'),
	        trigger: installFocus('skillsSettings'),
	        closeControl: installFocus('skillsSettingsClose'),
	        open: 'openSkillsSettingsPopover',
	        close: 'closeSkillsSettingsPopover',
	      },
	    ];

	    for (const popover of popovers) {
	      assert.ok(popover.element, `expected ${popover.name} popover to be created during startup`);
	      popover.element.contains = (target: unknown) => target === popover.closeControl;
	      popover.element.classList.add('hidden');
	      focusOrder.length = 0;
	      context.document.activeElement = popover.trigger;
	      context[popover.open]();
	      assert.strictEqual(context.document.activeElement, popover.closeControl, `${popover.name} should move focus inside on open`);
	      assert.strictEqual(popover.trigger.getAttribute('aria-expanded'), 'true');
	      context[popover.close]();
	      assert.strictEqual(popover.element.classList.contains('hidden'), true);
	      assert.strictEqual(popover.trigger.getAttribute('aria-expanded'), 'false');
	      assert.strictEqual(context.document.activeElement, popover.trigger, `${popover.name} should restore focus to its trigger`);
	      assert.deepStrictEqual(focusOrder, [popover.closeControl.id, popover.trigger.id]);
	    }

	    installFocus('modelSettings');
	    const modelSettingsPopover = elements.get('modelSettingsPopover');
	    const modelSettingsClose = installFocus('modelSettingsClose');
	    assert.ok(modelSettingsPopover, 'expected model settings popover to be created during startup');
	    modelSettingsPopover.contains = (target: unknown) => target === modelSettingsClose;
	    modelSettingsPopover.classList.add('hidden');

	    focusOrder.length = 0;
	    context.document.activeElement = modelPicker;
	    context.openModelSettingsPopover();
	    assert.strictEqual(context.document.activeElement, modelSettingsClose, 'model picker should move focus into generation settings on open');
	    context.closeModelSettingsPopover();
	    assert.strictEqual(context.document.activeElement, modelPicker, 'model picker should receive restored focus when it opened generation settings');
	    assert.strictEqual(modelPicker.getAttribute('aria-expanded'), 'false');

	    focusOrder.length = 0;
	    context.document.activeElement = modelPicker;
	    context.openModelSettingsPopover();
	    context.document.dispatchEvent({ type: 'click', target: modelPicker });
	    assert.strictEqual(modelSettingsPopover.classList.contains('hidden'), false, 'model picker trigger should not dismiss its own popover as an outside click');

	    timeoutCallbacks.length = 0;
	    focusOrder.length = 0;
	    context.document.activeElement = modelSettingsClose;
	    const outsideSurface = context.document.createElement('div');
	    context.document.dispatchEvent({ type: 'click', target: outsideSurface });
	    assert.strictEqual(modelSettingsPopover.classList.contains('hidden'), true);
	    assert.strictEqual(timeoutCallbacks.length, 1, 'outside dismissal should schedule hidden-focus cleanup');
	    timeoutCallbacks.shift()?.();
	    assert.strictEqual(context.document.activeElement, input, 'outside dismissal should not leave focus inside hidden generation settings');
	    assert.deepStrictEqual(focusOrder, ['input']);

	    const providerPopover = popovers[0];
	    const skillsPopover = popovers[3];
	    const contextPopover = elements.get('contextPopover');
	    assert.ok(contextPopover, 'expected context popover to be created during startup');
	    contextPopover.classList.remove('hidden');

	    focusOrder.length = 0;
	    context.document.activeElement = providerPopover.trigger;
	    context.openProviderSettingsPopover();
	    context.document.activeElement = skillsPopover.trigger;
	    context.openSkillsSettingsPopover();
	    context.document.activeElement = providerPopover.closeControl;
	    const stackedEscape: any = { type: 'keydown', key: 'Escape' };
	    context.document.dispatchEvent(stackedEscape);
	    assert.strictEqual(providerPopover.element.classList.contains('hidden'), false, 'Escape should leave older settings popovers open');
	    assert.strictEqual(skillsPopover.element.classList.contains('hidden'), true, 'Escape should close the most recently opened settings popover first');
	    assert.strictEqual(contextPopover.classList.contains('hidden'), false, 'settings Escape should not leak into later popover key handlers');
	    assert.strictEqual(context.document.activeElement, skillsPopover.trigger, 'stacked settings Escape should restore the latest opener');
	    assert.strictEqual(stackedEscape.defaultPrevented, true);
	    assert.strictEqual(stackedEscape.__stopImmediatePropagation, true);

	    context.document.activeElement = input;
	    const olderEscape: any = { type: 'keydown', key: 'Escape' };
	    context.document.dispatchEvent(olderEscape);
	    assert.strictEqual(providerPopover.element.classList.contains('hidden'), true, 'a second Escape should close the next settings popover in the stack');
	    assert.strictEqual(contextPopover.classList.contains('hidden'), false, 'settings Escape should still stop later document handlers');
	    assert.strictEqual(context.document.activeElement, providerPopover.trigger, 'older settings Escape should restore its opener');

		    context.document.activeElement = providerPopover.trigger;
		    context.openProviderSettingsPopover();
		    const outputModal = elements.get('outputModal');
		    const outputModalBackdrop = elements.get('outputModalBackdrop');
		    assert.ok(outputModal, 'expected output modal to be created during startup');
		    assert.ok(outputModalBackdrop, 'expected output modal backdrop to be created during startup');
		    outputModal.contains = (target: unknown) => target === outputModal || target === outputModalBackdrop;
		    assert.strictEqual(typeof context.openOutputModal, 'function', 'expected output modal opener');
		    context.openOutputModal('Settings test output', 'alpha');
		    const outputEscape: any = { type: 'keydown', key: 'Escape' };
		    context.document.dispatchEvent(outputEscape);
		    assert.strictEqual(providerPopover.element.classList.contains('hidden'), false, 'output modal Escape should take precedence over settings popovers');
		    assert.strictEqual(contextPopover.classList.contains('hidden'), false, 'output modal Escape should not close underlying context popovers');
		    assert.strictEqual(outputModal.classList.contains('hidden'), true);
		    assert.strictEqual(outputEscape.defaultPrevented, true);
		    assert.strictEqual(outputEscape.__stopImmediatePropagation, true);

		    context.openOutputModal('Settings test output', 'beta');
		    contextPopover.classList.remove('hidden');
		    const modalMouseDown: any = { type: 'mousedown', target: outputModalBackdrop };
		    context.document.dispatchEvent(modalMouseDown);
