  test('tool runtime limits metadata skips duplicate value and title writes', () => {
    const controller = createStandaloneChatController();
    const webview = {
      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    const initialLimits = {
      toolTimeoutMs: 0,
      readMaxLines: 300,
      bashBackgroundTtlMs: 600000,
      bashBackgroundCaptureMs: 2000,
      bashBackgroundCaptureLines: 50,
      workspaceShellTimeoutMs: 60000,
      httpTimeoutMs: 30000,
    };
    context.window.dispatchEvent({
      type: 'message',
      data: {
        type: 'init',
        messages: [],
        skills: [],
        toolRuntimeLimits: initialLimits,
      },
    });

    const safetySettings = elements.get('safetySettings');
    const toolTimeoutMsInput = elements.get('toolTimeoutMsInput');
    const toolTimeoutMsLabel = elements.get('toolTimeoutMsLabel');
    const readMaxLinesInput = elements.get('readMaxLinesInput');
    const readMaxLinesLabel = elements.get('readMaxLinesLabel');
    const bashBackgroundTtlMsInput = elements.get('bashBackgroundTtlMsInput');
    const bashBackgroundTtlMsLabel = elements.get('bashBackgroundTtlMsLabel');
    const bashBackgroundCaptureMsInput = elements.get('bashBackgroundCaptureMsInput');
    const bashBackgroundCaptureMsLabel = elements.get('bashBackgroundCaptureMsLabel');
    const bashBackgroundCaptureLinesInput = elements.get('bashBackgroundCaptureLinesInput');
    const bashBackgroundCaptureLinesLabel = elements.get('bashBackgroundCaptureLinesLabel');
    const workspaceShellTimeoutMsInput = elements.get('workspaceShellTimeoutMsInput');
    const workspaceShellTimeoutMsLabel = elements.get('workspaceShellTimeoutMsLabel');
    const httpTimeoutMsInput = elements.get('httpTimeoutMsInput');
    const httpTimeoutMsLabel = elements.get('httpTimeoutMsLabel');
    const toolLimitsApply = elements.get('toolLimitsApply');
    for (const [name, element] of Object.entries({
      safetySettings,
      toolTimeoutMsInput,
      toolTimeoutMsLabel,
      readMaxLinesInput,
      readMaxLinesLabel,
      bashBackgroundTtlMsInput,
      bashBackgroundTtlMsLabel,
      bashBackgroundCaptureMsInput,
      bashBackgroundCaptureMsLabel,
      bashBackgroundCaptureLinesInput,
      bashBackgroundCaptureLinesLabel,
      workspaceShellTimeoutMsInput,
      workspaceShellTimeoutMsLabel,
      httpTimeoutMsInput,
      httpTimeoutMsLabel,
      toolLimitsApply,
    })) {
      assert.ok(element, `expected ${name} to be created during startup`);
    }

    const observePropertyWrites = (element: any, property: string) => {
      let value = element[property];
      let count = 0;
      Object.defineProperty(element, property, {
        configurable: true,
        get: () => value,
        set: (next: unknown) => {
          count++;
          value = next;
        },
      });
      return () => count;
    };

    const safetySettingsTitleWrites = observePropertyWrites(safetySettings, 'title');
    const toolTimeoutValueWrites = observePropertyWrites(toolTimeoutMsInput, 'value');
    const toolTimeoutTitleWrites = observePropertyWrites(toolTimeoutMsLabel, 'title');
    const readMaxLinesValueWrites = observePropertyWrites(readMaxLinesInput, 'value');
    const readMaxLinesTitleWrites = observePropertyWrites(readMaxLinesLabel, 'title');
    const bashTtlValueWrites = observePropertyWrites(bashBackgroundTtlMsInput, 'value');
    const bashTtlTitleWrites = observePropertyWrites(bashBackgroundTtlMsLabel, 'title');
    const bashCaptureMsValueWrites = observePropertyWrites(bashBackgroundCaptureMsInput, 'value');
    const bashCaptureMsTitleWrites = observePropertyWrites(bashBackgroundCaptureMsLabel, 'title');
    const bashCaptureLinesValueWrites = observePropertyWrites(bashBackgroundCaptureLinesInput, 'value');
    const bashCaptureLinesTitleWrites = observePropertyWrites(bashBackgroundCaptureLinesLabel, 'title');
    const shellTimeoutValueWrites = observePropertyWrites(workspaceShellTimeoutMsInput, 'value');
    const shellTimeoutTitleWrites = observePropertyWrites(workspaceShellTimeoutMsLabel, 'title');
    const httpTimeoutValueWrites = observePropertyWrites(httpTimeoutMsInput, 'value');
    const httpTimeoutTitleWrites = observePropertyWrites(httpTimeoutMsLabel, 'title');
    const totalWrites = () =>
      safetySettingsTitleWrites() +
      toolTimeoutValueWrites() +
      toolTimeoutTitleWrites() +
      readMaxLinesValueWrites() +
      readMaxLinesTitleWrites() +
      bashTtlValueWrites() +
      bashTtlTitleWrites() +
      bashCaptureMsValueWrites() +
      bashCaptureMsTitleWrites() +
      bashCaptureLinesValueWrites() +
      bashCaptureLinesTitleWrites() +
      shellTimeoutValueWrites() +
      shellTimeoutTitleWrites() +
      httpTimeoutValueWrites() +
      httpTimeoutTitleWrites();

	    context.window.dispatchEvent({ type: 'message', data: { type: 'settingsState', toolRuntimeLimits: initialLimits } });
	    assert.strictEqual(totalWrites(), 0, 'unchanged tool runtime limits should not rewrite value or title properties');
	    assert.strictEqual(typeof context.normalizeToolRuntimeLimits, 'function');
	    assert.strictEqual(typeof context.updateNormalizedToolRuntimeLimitsState, 'function');

    const changedLimits = {
      toolTimeoutMs: 10000,
      readMaxLines: 500,
      bashBackgroundTtlMs: 900000,
      bashBackgroundCaptureMs: 3500,
      bashBackgroundCaptureLines: 80,
      workspaceShellTimeoutMs: 90000,
      httpTimeoutMs: 45000,
    };
    context.window.dispatchEvent({ type: 'message', data: { type: 'settingsState', toolRuntimeLimits: changedLimits } });

    assert.strictEqual(safetySettingsTitleWrites(), 1, 'changed tool runtime limits should update the safety summary once');
    assert.strictEqual(toolTimeoutValueWrites(), 1, 'changed tool timeout should write value once');
    assert.strictEqual(toolTimeoutTitleWrites(), 1, 'changed tool timeout should write title once');
    assert.strictEqual(readMaxLinesValueWrites(), 1, 'changed read max lines should write value once');
    assert.strictEqual(readMaxLinesTitleWrites(), 1, 'changed read max lines should write title once');
    assert.strictEqual(bashTtlValueWrites(), 1, 'changed bash TTL should write value once');
    assert.strictEqual(bashTtlTitleWrites(), 1, 'changed bash TTL should write title once');
    assert.strictEqual(bashCaptureMsValueWrites(), 1, 'changed bash capture timeout should write value once');
    assert.strictEqual(bashCaptureMsTitleWrites(), 1, 'changed bash capture timeout should write title once');
    assert.strictEqual(bashCaptureLinesValueWrites(), 1, 'changed bash capture lines should write value once');
    assert.strictEqual(bashCaptureLinesTitleWrites(), 1, 'changed bash capture lines should write title once');
    assert.strictEqual(shellTimeoutValueWrites(), 1, 'changed workspace shell timeout should write value once');
    assert.strictEqual(shellTimeoutTitleWrites(), 1, 'changed workspace shell timeout should write title once');
    assert.strictEqual(httpTimeoutValueWrites(), 1, 'changed HTTP timeout should write value once');
    assert.strictEqual(httpTimeoutTitleWrites(), 1, 'changed HTTP timeout should write title once');
    const afterChangedState = totalWrites();

    context.window.dispatchEvent({ type: 'message', data: { type: 'settingsState', toolRuntimeLimits: changedLimits } });
    assert.strictEqual(totalWrites(), afterChangedState, 'repeated changed tool runtime limits should not rewrite metadata');

    const beforeNoopToolLimitsApply = posted.length;
    toolLimitsApply.dispatchEvent({ type: 'click', preventDefault: () => {} });
    assert.strictEqual(
      posted.slice(beforeNoopToolLimitsApply).filter(message => message && message.type === 'setToolRuntimeLimits').length,
      0,
      'unchanged tool runtime limits apply should not post'
    );

    const beforeChangedToolLimitsApply = posted.length;
    toolTimeoutMsInput.value = '10001.9';
    toolLimitsApply.dispatchEvent({ type: 'click', preventDefault: () => {} });
    const changedToolLimitMessages = posted.slice(beforeChangedToolLimitsApply).filter(message => message && message.type === 'setToolRuntimeLimits');
    assert.strictEqual(changedToolLimitMessages.length, 1, 'changed tool runtime limits apply should post normalized limits once');
	    assert.deepStrictEqual(JSON.parse(JSON.stringify(changedToolLimitMessages[0].limits)), {
	      ...changedLimits,
	      toolTimeoutMs: 10001,
	    });
	    let normalizedToolLimitReads = 0;
	    const normalizedToolLimits = context.normalizeToolRuntimeLimits({
	      toolTimeoutMs: 12000,
	      readMaxLines: 700,
	      bashBackgroundTtlMs: 700000,
	      bashBackgroundCaptureMs: 1200,
	      bashBackgroundCaptureLines: 40,
	      workspaceShellTimeoutMs: 65000,
	      httpTimeoutMs: 25000,
	    });
	    const trackedToolLimits: any = {};
	    for (const field of [
	      'toolTimeoutMs',
	      'readMaxLines',
	      'bashBackgroundTtlMs',
	      'bashBackgroundCaptureMs',
	      'bashBackgroundCaptureLines',
	      'workspaceShellTimeoutMs',
	      'httpTimeoutMs',
	    ]) {
	      Object.defineProperty(trackedToolLimits, field, {
	        configurable: true,
	        get: () => {
	          normalizedToolLimitReads++;
	          return (normalizedToolLimits as any)[field];
	        },
	      });
	    }
	    context.updateNormalizedToolRuntimeLimitsState(trackedToolLimits);
	    assert.ok(
	      normalizedToolLimitReads <= 15,
	      'normalized tool runtime limit updates should only read fields for controls and summary text'
	    );
	    assert.strictEqual(toolTimeoutMsInput.value, '12000');
	    assert.strictEqual(readMaxLinesInput.value, '700');
	    assert.strictEqual(httpTimeoutMsInput.value, '25000');
	    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
	  });

			  test('safety debug and plugin controls skip duplicate disabled label and text writes', () => {
	    const controller = createStandaloneChatController();
	    const webview = {
	      cspSource: 'test-csp',
      asWebviewUri: (uri: unknown) => uri,
    } as unknown as vscode.Webview;

    const html = controller.webviewApi.getHtml(webview);
    const scripts = extractOrderedScriptSources(html);
    const { context, elements, posted } = createMockBrowserContext();
    runScriptsInMockBrowser(scripts, context);

    context.window.dispatchEvent({ type: 'message', data: { type: 'init', messages: [], skills: [] } });

    const controlIds = [
      'safetySelect',
      'safetySettings',
      'allowExternalPathsToggle',
      'blockGitPushToggle',
      'debugDetailsToggle',
      'debugLlmToggle',
      'debugToolsToggle',
      'debugPluginsToggle',
      'listTools',
      'runTool',
      'createToolsConfig',
      'pluginsAutoDiscoverToggle',
      'pluginsWorkspaceDirInput',
      'pluginSpecsInput',
      'pluginSettingsApply',
    ];
    const labelIds = [
      'allowExternalPathsLabel',
      'blockGitPushLabel',
      'debugDetailsLabel',
      'debugLlmLabel',
      'debugToolsLabel',
      'debugPluginsLabel',
      'pluginsAutoDiscoverLabel',
      'pluginsWorkspaceDirLabel',
      'pluginSpecsLabel',
    ];
    const initiallyDisabled = new Map<string, boolean>();

		    let disabledReadCount = 0;
			    let disabledWriteCount = 0;
		    for (const id of controlIds) {
		      const element = elements.get(id);
		      assert.ok(element, `expected ${id} to be created during startup`);
		      initiallyDisabled.set(id, !!element.disabled);
		      let disabled = !!element.disabled;
			      Object.defineProperty(element, 'disabled', {
			        configurable: true,
			        get: () => {
			          disabledReadCount++;
			          return disabled;
			        },
		        set: (value: unknown) => {
		          disabledWriteCount++;
		          disabled = !!value;
		        },
		      });
		    }

    let labelToggleCount = 0;
    for (const id of labelIds) {
      const element = elements.get(id);
      assert.ok(element, `expected ${id} to be created during startup`);
      const originalToggle = element.classList.toggle;
      element.classList.toggle = (name: string, force?: boolean) => {
        labelToggleCount++;
        return originalToggle(name, force);
      };
    }

    const showLogs = elements.get('showLogs');
    assert.ok(showLogs, 'expected show logs button to be created during startup');
    let showLogsDisabled = !!showLogs.disabled;
    let showLogsDisabledReadCount = 0;
    let showLogsDisabledWriteCount = 0;
    Object.defineProperty(showLogs, 'disabled', {
      configurable: true,
      get: () => {
        showLogsDisabledReadCount++;
        return showLogsDisabled;
      },
      set: (value: unknown) => {
        showLogsDisabledWriteCount++;
        showLogsDisabled = !!value;
      },
    });
    let showLogsText = String(showLogs.textContent || '');
    let showLogsTextReadCount = 0;
    let showLogsTextWriteCount = 0;
	    Object.defineProperty(showLogs, 'textContent', {
	      configurable: true,
	      get: () => {
	        showLogsTextReadCount++;
	        return showLogsText;
      },
      set: (value: unknown) => {
        showLogsTextWriteCount++;
	        showLogsText = String(value);
	      },
	    });
		    let showLogsAriaWriteCount = 0;
	    const originalShowLogsSetAttribute = showLogs.setAttribute;
	    showLogs.setAttribute = (name: string, value: string) => {
	      if (name === 'aria-label') showLogsAriaWriteCount++;
	      return originalShowLogsSetAttribute.call(showLogs, name, value);
	    };

    assert.strictEqual(typeof context.syncInputState, 'function');
    assert.strictEqual(typeof context.setProcessing, 'function');
    context.syncInputState();
    context.syncInputState();
    assert.strictEqual(disabledWriteCount, 0, 'unchanged safety/debug/plugin controls should not rewrite disabled state');
    assert.strictEqual(labelToggleCount, 0, 'unchanged safety/debug/plugin labels should not rewrite class state');
	    assert.strictEqual(showLogsDisabledWriteCount, 0, 'unchanged show-logs disabled state should not rewrite');
	    assert.strictEqual(showLogsTextWriteCount, 0, 'unchanged show-logs label should not rewrite');
	    assert.strictEqual(showLogsAriaWriteCount, 0, 'unchanged show-logs accessible label should not rewrite');

    showLogsDisabledReadCount = 0;
    showLogsTextReadCount = 0;
    context.window.dispatchEvent({ type: 'message', data: { type: 'logsActionState', pending: false } });
    assert.strictEqual(showLogsDisabledReadCount, 0, 'duplicate idle logs state should skip show-logs disabled reads');
    assert.strictEqual(showLogsTextReadCount, 0, 'duplicate idle logs state should skip show-logs text reads');
	    assert.strictEqual(showLogsDisabledWriteCount, 0, 'duplicate idle logs state should not rewrite disabled');
	    assert.strictEqual(showLogsTextWriteCount, 0, 'duplicate idle logs state should not rewrite text');
	    assert.strictEqual(showLogsAriaWriteCount, 0, 'duplicate idle logs state should not rewrite accessible label');

    disabledReadCount = 0;
    const writesAfterDuplicateSafetyState = disabledWriteCount;
	    context.window.dispatchEvent({ type: 'message', data: { type: 'autoApproveState', autoApprove: false } });
	    context.window.dispatchEvent({ type: 'message', data: { type: 'allowExternalPathsState', allowExternalPaths: false } });
	    context.window.dispatchEvent({ type: 'message', data: { type: 'blockGitPushState', blockGitPush: true } });
	    context.window.dispatchEvent({ type: 'message', data: { type: 'debugSettingsState', debugSettings: {} } });
	    context.window.dispatchEvent({ type: 'message', data: { type: 'pluginSettingsState', pluginSettings: {} } });
	    assert.strictEqual(disabledReadCount, 0, 'duplicate idle safety setting states should skip safety control reads');
	    assert.strictEqual(disabledWriteCount, writesAfterDuplicateSafetyState, 'duplicate idle safety setting states should not rewrite controls');

    const controlsEnabledBeforeProcessing = controlIds.filter(id => !initiallyDisabled.get(id)).length;
    context.setProcessing(true);
    assert.strictEqual(disabledWriteCount, controlsEnabledBeforeProcessing, 'processing should only disable enabled safety/debug/plugin controls');
    assert.strictEqual(labelToggleCount, labelIds.length, 'processing should mark each safety/debug/plugin label once');
    assert.strictEqual(showLogsDisabledWriteCount, 0, 'processing should not disable show logs');
    assert.strictEqual(showLogsTextWriteCount, 0, 'processing should not rewrite show-logs text');
    for (const id of controlIds) {
      assert.strictEqual(elements.get(id).disabled, true, `expected ${id} to be disabled while processing`);
    }
    for (const id of labelIds) {
      assert.strictEqual(elements.get(id).classList.contains('disabled'), true, `expected ${id} to have disabled class`);
    }

    context.setProcessing(true);
    assert.strictEqual(disabledWriteCount, controlsEnabledBeforeProcessing, 'unchanged processing state should not rewrite safety/debug/plugin controls');
    assert.strictEqual(labelToggleCount, labelIds.length, 'unchanged processing state should not retoggle safety/debug/plugin labels');

    context.setProcessing(false);
    assert.strictEqual(disabledWriteCount, controlsEnabledBeforeProcessing * 2, 'stopping processing should restore changed safety/debug/plugin controls once');
    assert.strictEqual(labelToggleCount, labelIds.length * 2, 'stopping processing should clear safety/debug/plugin labels once');
    for (const id of controlIds) {
      assert.strictEqual(elements.get(id).disabled, initiallyDisabled.get(id), `expected ${id} to return to its initial state`);
    }
    for (const id of labelIds) {
      assert.strictEqual(elements.get(id).classList.contains('disabled'), false, `expected ${id} to clear disabled class`);
    }

    showLogs.dispatchEvent({ type: 'click', preventDefault: () => {} });
    assert.strictEqual(showLogsDisabledWriteCount, 1, 'show-logs click should disable the button once');
    assert.strictEqual(showLogsTextWriteCount, 1, 'show-logs click should rewrite the button text once');
	    assert.strictEqual(showLogs.disabled, true);
	    assert.strictEqual(showLogs.textContent, 'Opening logs…');
	    assert.strictEqual(showLogs.getAttribute('aria-label'), 'Opening logs…, open the LingYun output channel');
	    assert.strictEqual(showLogsAriaWriteCount, 1, 'show-logs click should rewrite the accessible label once');
	    context.syncInputState();
	    assert.strictEqual(showLogsDisabledWriteCount, 1, 'unchanged pending show-logs state should not rewrite disabled');
		    assert.strictEqual(showLogsTextWriteCount, 1, 'unchanged pending show-logs state should not rewrite text');
	    assert.strictEqual(showLogsAriaWriteCount, 1, 'unchanged pending show-logs state should not rewrite accessible label');

    showLogsDisabledReadCount = 0;
    showLogsTextReadCount = 0;
    context.window.dispatchEvent({ type: 'message', data: { type: 'logsActionState', pending: false } });
    assert.ok(showLogsDisabledReadCount > 0, 'finishing pending logs should sync show-logs disabled state');
    assert.ok(showLogsTextReadCount > 0, 'finishing pending logs should sync show-logs text');
	    assert.strictEqual(showLogsDisabledWriteCount, 2, 'finishing pending logs should enable the button once');
	    assert.strictEqual(showLogsTextWriteCount, 2, 'finishing pending logs should restore the button label once');
	    assert.strictEqual(showLogs.disabled, false);
	    assert.strictEqual(showLogs.textContent, 'Show logs');
	    assert.strictEqual(showLogs.getAttribute('aria-label'), 'Show logs, open the LingYun output channel');
	    assert.strictEqual(showLogsAriaWriteCount, 2, 'finishing pending logs should restore the accessible label once');

    showLogsDisabledReadCount = 0;
    showLogsTextReadCount = 0;
    context.window.dispatchEvent({ type: 'message', data: { type: 'logsActionState', pending: false } });
	    assert.strictEqual(showLogsDisabledReadCount, 0, 'duplicate completed logs state should skip disabled reads');
	    assert.strictEqual(showLogsTextReadCount, 0, 'duplicate completed logs state should skip text reads');
	    assert.strictEqual(showLogsDisabledWriteCount, 2, 'duplicate completed logs state should not rewrite disabled');
	    assert.strictEqual(showLogsTextWriteCount, 2, 'duplicate completed logs state should not rewrite text');
	    assert.strictEqual(showLogsAriaWriteCount, 2, 'duplicate completed logs state should not rewrite accessible label');

    const allowExternalPathsToggle = elements.get('allowExternalPathsToggle');
    disabledReadCount = 0;
    allowExternalPathsToggle.checked = true;
    allowExternalPathsToggle.dispatchEvent({ type: 'change', preventDefault: () => {} });
    assert.ok(disabledReadCount > 0, 'starting external-path setting update should sync safety controls');
    assert.strictEqual(allowExternalPathsToggle.disabled, true);

    disabledReadCount = 0;
	    context.window.dispatchEvent({ type: 'message', data: { type: 'allowExternalPathsState', allowExternalPaths: true } });
	    assert.ok(disabledReadCount > 0, 'finishing pending external-path state should sync safety controls');
	    assert.strictEqual(allowExternalPathsToggle.disabled, false);
	    const debugDetailsToggle = elements.get('debugDetailsToggle');
	    disabledReadCount = 0;
	    debugDetailsToggle.checked = true;
	    debugDetailsToggle.dispatchEvent({ type: 'change', preventDefault: () => {} });
	    assert.ok(disabledReadCount > 0, 'starting debug settings update should sync safety controls');
	    assert.strictEqual(debugDetailsToggle.disabled, true);

	    disabledReadCount = 0;
	    context.window.dispatchEvent({ type: 'message', data: { type: 'debugSettingsState', debugSettings: { details: true } } });
	    assert.ok(disabledReadCount > 0, 'finishing pending debug settings state should sync safety controls');
	    assert.strictEqual(debugDetailsToggle.disabled, false);

	    const pluginSpecsInput = elements.get('pluginSpecsInput');
	    const pluginSettingsApply = elements.get('pluginSettingsApply');
	    disabledReadCount = 0;
	    pluginSpecsInput.value = './plugins/example';
	    pluginSettingsApply.dispatchEvent({ type: 'click', preventDefault: () => {} });
	    assert.ok(disabledReadCount > 0, 'starting plugin settings update should sync safety controls');
	    assert.strictEqual(pluginSpecsInput.disabled, true);

	    disabledReadCount = 0;
	    context.window.dispatchEvent({ type: 'message', data: { type: 'pluginSettingsState', pluginSettings: { plugins: ['./plugins/example'], autoDiscover: false, workspaceDir: '.lingyun' } } });
	    assert.ok(disabledReadCount > 0, 'finishing pending plugin settings state should sync safety controls');
	    assert.strictEqual(pluginSpecsInput.disabled, false);
		    assert.ok(!posted.some(message => message && message.type === WEBVIEW_MESSAGE_ERROR));
		  });

